insert into public.kanji (id, character, meanings, on_readings, kun_readings, jlpt_level, grade, stroke_count, unicode_hex, etymology, mnemonic)
values
  ('一', '一', '["one","one radical (no.1)"]'::jsonb, '{"イチ","イツ"}', '{"ひと-","ひと.つ"}', 'N5', 1, 1, '4e00', 'Pure ideograph (指事): a single horizontal stroke — one counting rod laid on the ground. The simplest possible written sign, unchanged since oracle-bone script.', 'One stroke, one finger laid flat, one horizon. Everything in the writing system is built on top of this line — it is the floor the other kanji stand on.'),
  ('右', '右', '["right"]'::jsonb, '{"ウ","ユウ"}', '{"みぎ"}', 'N5', 1, 5, '53f3', 'Compound ideograph: a hand (𠂇) over a mouth (口) — the right hand, the one you eat with and raise to speak or swear.', 'The hand that carries food to the mouth: your right — みぎ. Stroke tip: the sweep goes first here, then the horizontal — mirror etiquette to 左.'),
  ('雨', '雨', '["rain"]'::jsonb, '{"ウ"}', '{"あめ","あま-","-さめ"}', 'N5', 1, 8, '96e8', 'Pictograph: the vault of the sky as a canopy, with four drops falling inside it. As a crown component it governs all weather kanji (雪, 雲, 電).', 'A window pane in a storm: four drops caught mid-fall behind the glass — あめ. When 雨 sits on a kanji''s head, look up: weather incoming.'),
  ('円', '円', '["circle","yen","round"]'::jsonb, '{"エン"}', '{"まる.い","まる","まど","まど.か","まろ.やか"}', 'N5', 1, 4, '5186', 'Simplified from 圓: an enclosure (囗) around the phonetic 員. The perfect round shape — chosen in 1871 as the name of Japan''s round coin: the yen.', 'A coin standing upright in its slot — まる, the circle; エン, the yen it became. Every price tag in Japan ends in this little window: 百円, 千円.'),
  ('下', '下', '["below","down","descend","give","low","inferior"]'::jsonb, '{"カ","ゲ"}', '{"した","しも","もと","さ.げる","さ.がる","くだ.る","くだ.り","くだ.す","-くだ.す","くだ.さる","お.ろす","お.りる"}', 'N5', 1, 3, '4e0b', 'Pure ideograph: a short mark placed under a base line — the mirror of 上. The pair appears together on the oldest oracle bones.', 'A root and a drop hanging under the ground line: down, below — した. Flip 上 in a mirror along the ground and it falls to become 下.'),
  ('火', '火', '["fire"]'::jsonb, '{"カ"}', '{"ひ","-び","ほ-"}', 'N5', 1, 4, '706b', 'Pictograph: a flame rising from a burning pile, sparks flying off both sides. As a bottom component it flattens into four dots (灬).', 'A campfire: the central blaze and two sparks leaping away — ひ. Tuesday, 火曜日, is fire''s day. Keep it away from 木 unless you want ashes.'),
  ('花', '花', '["flower"]'::jsonb, '{"カ","ケ"}', '{"はな"}', 'N5', 1, 7, '82b1', 'Phono-semantic: the grass crown (艹) gives the meaning — a plant — while 化 ''change, transform'' lends the reading カ. The plant transformed into its loveliest state: a flower.', 'Under the grass crown, a plant works its transformation (化) — and blooms: はな. 花見 is the festival of watching that magic happen.'),
  ('学', '学', '["study","learning","science"]'::jsonb, '{"ガク"}', '{"まな.ぶ"}', 'N5', 1, 8, '5b66', 'Simplified from 學: a child (子) under a roof, with hands above passing knowledge down. The three little strokes on top are all that remain of those hands.', 'A child under a sparkling roof — sparks of knowledge raining down from the teacher''s hands: to study, まなぶ. 学校 is where the sparks fly, ガッコウ.'),
  ('気', '気', '["spirit","mind","air","atmosphere","mood"]'::jsonb, '{"キ","ケ"}', '{"いき","き"}', 'N5', 1, 6, '6c17', 'Simplified from 氣: vapor (气) rising from cooking rice (米) — steam, breath, and by extension the invisible energy of weather and mood.', 'Steam curling off a pot of rice: invisible, but it moves everything — き. The sky''s steam is 天気, yours is 元気. When both are good, life is too.'),
  ('休', '休', '["rest","day off","retire","sleep"]'::jsonb, '{"キュウ"}', '{"やす.む","やす.まる","やす.める"}', 'N5', 1, 6, '4f11', 'Compound ideograph: a person (亻) leaning against a tree (木) — resting in its shade. One of the textbook examples of a meaning built from two pictures.', 'A hiker slumped against a tree trunk, hat over the eyes — やすむ. 休み is that tree-shade taken as a day off.'),
  ('金', '金', '["gold"]'::jsonb, '{"キン","コン","ゴン"}', '{"かね","かな-","-がね"}', 'N5', 1, 8, '91d1', 'By the classic account: nuggets (the two dots) buried in layered earth (土) under a cover (𠆢) — metal in the mine. Later ''metal'' in general, then gold and money.', 'Under a little roof, in the earth, two nuggets gleam — かね, gold, money. Friday, 金曜日, is payday: the day the nuggets reach your pocket.'),
  ('九', '九', '["nine"]'::jsonb, '{"キュウ","ク"}', '{"ここの","ここの.つ"}', 'N5', 1, 2, '4e5d', 'Originally a pictograph of a bent elbow with a hand reaching in — borrowed for the number nine since oracle-bone times.', 'A baseball pitcher''s arm frozen mid-throw, elbow bent, wrist hooked: nine innings, きゅう. The hook at the end is the ball leaving the hand.'),
  ('空', '空', '["empty","sky","void","vacant","vacuum"]'::jsonb, '{"クウ"}', '{"そら","あ.く","あ.き","あ.ける","から","す.く","す.かす","むな.しい"}', 'N5', 1, 8, '7a7a', 'Phono-semantic: hole (穴) + 工 (phonetic クウ) — a hollowed-out space: empty; and the greatest hollow of all, the open sky.', 'Dig through the cave roof (穴) with your tools (工) and break into the biggest empty room there is: the sky — そら. 空港: the harbor of the sky.'),
  ('月', '月', '["month","moon"]'::jsonb, '{"ゲツ","ガツ"}', '{"つき"}', 'N5', 1, 4, '6708', 'Pictograph: the crescent moon with two shading strokes inside. One full cycle of the moon = one month.', 'The sun''s window (日) grew legs and slimmed down for the night shift: the moon. It waxes and wanes once a month — つき / ゲツ, as in 月曜日, the moon''s own day.'),
  ('見', '見', '["see","hopes","chances","idea","opinion","look at","visible"]'::jsonb, '{"ケン"}', '{"み.る","み.える","み.せる"}', 'N5', 1, 7, '898b', 'Compound ideograph: an eye (目) set on human legs (儿) — a person shown as nothing but their looking. To see is to walk your eye over to something.', 'An eyeball that grew legs and runs around looking at things — みる. When you ''go see'' a friend, this little creature is what you send ahead.'),
  ('五', '五', '["five"]'::jsonb, '{"ゴ"}', '{"いつ","いつ.つ"}', 'N5', 1, 4, '4e94', 'Ideograph: originally an X between two horizontal lines — a tally device marking the halfway point of ten. The X ''crosses over'' at five.', 'The tally-keeper''s shortcut: when you reach five, you stop drawing sticks and cross them off — ご! Four strokes that mean one full hand of fingers.'),
  ('口', '口', '["mouth"]'::jsonb, '{"コウ","ク"}', '{"くち"}', 'N5', 1, 3, '53e3', 'Pictograph (象形): an open mouth, squared off by the brush. One of the most productive components in the writing system — anything spoken, eaten or shouted tends to contain it.', 'A wide-open mouth turned into a square frame. Every time you spot this box in a kanji, someone is talking, eating or shouting — くち.'),
  ('校', '校', '["exam","school","printing","proof","correction"]'::jsonb, '{"コウ","キョウ"}', '{}', 'N5', 1, 10, '6821', 'Phono-semantic: tree/wood (木) + 交 ''to cross'' (phonetic コウ). Originally wooden frames and fetters; settled on the wooden halls where paths cross — the school.', 'A wooden building (木) where a thousand lives crisscross (交) every morning — コウ, the school of 学校. Also the place your test gets ''crossed'' with red ink.'),
  ('左', '左', '["left"]'::jsonb, '{"サ","シャ"}', '{"ひだり"}', 'N5', 1, 5, '5de6', 'Compound ideograph: a left hand (𠂇) holding a carpenter''s tool (工). The left hand steadies the work while the right one acts.', 'The hand that holds the ruler (工) while the other draws: your left — ひだり. Stroke tip: here the horizontal goes first, then the sweep — the mirror of 右.'),
  ('三', '三', '["three"]'::jsonb, '{"サン","ゾウ"}', '{"み","み.つ","みっ.つ"}', 'N5', 1, 3, '4e09', 'Ideograph: three counting rods. Heaven, humankind and earth in the old Chinese reading of the three lines — top, middle, bottom.', 'Three floors of a building seen from the side. The middle floor is the smallest — the child between two parents.'),
  ('山', '山', '["mountain"]'::jsonb, '{"サン","セン"}', '{"やま"}', 'N5', 1, 3, '5c71', 'Pictograph: three peaks, the middle one highest. Unchanged in three thousand years.', 'Three peaks on the horizon — やま. Japan''s favorite kanji: it caps 富士山 and half the family names in the country (山田, 山本).'),
  ('四', '四', '["four"]'::jsonb, '{"シ"}', '{"よ","よ.つ","よっ.つ","よん"}', 'N5', 1, 5, '56db', 'Originally written as four stacked bars (亖); the current form — breath dispersing from a mouth, drawn as legs inside a box — was borrowed for its sound over 2,000 years ago.', 'A window (the box) with a pair of legs dangling out of it: four legs in all if you count the window''s own two sides. よん — the yawn of someone climbing out of that window.'),
  ('子', '子', '["child","sign of the rat","11PM-1AM","first sign of Chinese zodiac"]'::jsonb, '{"シ","ス","ツ"}', '{"こ","-こ","ね"}', 'N5', 1, 3, '5b50', 'Pictograph: a swaddled baby — big head, arms spread wide, legs bound together in the wrapping cloth.', 'A baby with arms flung out and its legs still wrapped in a blanket — こ. Girls'' names end with it (花子), and it hides in 好き: a woman with her child, fondness itself.'),
  ('耳', '耳', '["ear"]'::jsonb, '{"ジ"}', '{"みみ"}', 'N5', 1, 6, '8033', 'Pictograph: an ear with its outer rim and lobe — the horizontal strokes trace the folds of the ear itself.', 'An ear drawn in profile, lobe trailing off at the bottom stroke — みみ. Two of them frame your face; two strokes frame this kanji.'),
  ('七', '七', '["seven"]'::jsonb, '{"シチ"}', '{"なな","なな.つ","なの"}', 'N5', 1, 2, '4e03', 'Originally a picture of a line being cut crosswise — it was the first way of writing 切 ''to cut''. Borrowed early on for the number seven.', 'An upside-down seven with a hook. A knife slicing diagonally through a line: cut a cake into seven pieces — しち slices.'),
  ('車', '車', '["car"]'::jsonb, '{"シャ"}', '{"くるま"}', 'N5', 1, 7, '8eca', 'Pictograph: a cart seen from above — the axle running vertically, the wheel-body in the middle, crossbars at each end.', 'Bird''s-eye view of a chariot: axle, cabin, two wheels — くるま. Two millennia later it still parks inside 電車 and 自転車 without a scratch.'),
  ('手', '手', '["hand"]'::jsonb, '{"シュ","ズ"}', '{"て","て-","-て","た-"}', 'N5', 1, 4, '624b', 'Pictograph: an open hand seen palm-on — the central stroke is the middle finger, the horizontals the spread of the others. As a left-side component it becomes 扌.', 'Five fingers fanned from a wrist — て. Almost everything you do in Japanese is done ''by hand'': 手紙 a letter, 上手 a skilled hand, 歌手 a singer ''of the hand(craft)''.'),
  ('十', '十', '["ten"]'::jsonb, '{"ジュウ","ジッ","ジュッ"}', '{"とお","と","そ"}', 'N5', 1, 2, '5341', 'Originally a single vertical stroke (a needle — the ancestor of 針); a dot, later a crossbar, was added to distinguish it. Borrowed for ''ten'': one full crossing of both hands'' fingers.', 'A perfect cross: all ten fingers of two open hands meeting at right angles. じゅう — the intersection where the count is complete.'),
  ('出', '出', '["exit","leave","go out","come out","put out","protrude"]'::jsonb, '{"シュツ","スイ"}', '{"で.る","-で","だ.す","-だ.す","い.でる","い.だす"}', 'N5', 1, 5, '51fa', 'Oracle-bone ideograph: a foot stepping up and out of a pit or dwelling — going out. The later form looks like a sprout growing on past its first frame.', 'One mountain climbing out of another: whatever was inside is on its way out — でる. On every door in Japan: 出口, the way out.'),
  ('女', '女', '["woman","female"]'::jsonb, '{"ジョ","ニョ","ニョウ"}', '{"おんな","め"}', 'N5', 1, 3, '5973', 'Pictograph: a figure kneeling with hands crossed — the posture of a woman in ancient formal dress. The three strokes still trace the crossed arms and folded legs.', 'A dancer mid-curtsy, arms crossing her body — おんな. In compounds she signals the feminine: 女の子, girl; 彼女, she.'),
  ('小', '小', '["little","small"]'::jsonb, '{"ショウ"}', '{"ちい.さい","こ-","お-","さ-"}', 'N5', 1, 3, '5c0f', 'Ideograph: three tiny points — grains of sand or slivers falling away from a blade. Smallness shown by sheer lack of material.', 'A hook with two shy drops hiding on either side: something so small it barely exists — ちいさい. The vertical stroke is a needle; the drops, its parings.'),
  ('上', '上', '["above","up"]'::jsonb, '{"ジョウ","ショウ","シャン"}', '{"うえ","-うえ","うわ-","かみ","あ.げる","-あ.げる","あ.がる","-あ.がる","あ.がり","-あ.がり","のぼ.る","のぼ.り","のぼ.せる","のぼ.す","たてまつ.る"}', 'N5', 1, 3, '4e0a', 'Pure ideograph: a short mark placed above a base line. Its twin 下 puts the mark below. Among the oldest abstract signs in the script.', 'A little flag planted on top of the ground line: up, above — うえ. The vertical stroke grows upward like a sapling; nothing hangs below the line.'),
  ('人', '人', '["person"]'::jsonb, '{"ジン","ニン"}', '{"ひと","-り","-と"}', 'N5', 1, 2, '4eba', 'Pictograph: a human figure in profile, mid-stride — two legs and a leaning body reduced to two strokes.', 'Two strokes leaning on each other — ひと. The oldest joke in kanji class is also true: people hold each other up. It leans left; its twin 入 (enter) leans in.'),
  ('水', '水', '["water"]'::jsonb, '{"スイ"}', '{"みず","みず-"}', 'N5', 1, 4, '6c34', 'Pictograph: a central current with droplets splashing to both sides. As a left-side component it compresses into the three drops of 氵.', 'A river seen head-on: the main stream down the middle, spray flying left and right — みず. Its on-reading スイ flows through 水曜日, Wednesday, the water day.'),
  ('生', '生', '["life","genuine","birth"]'::jsonb, '{"セイ","ショウ"}', '{"い.きる","い.かす","い.ける","う.まれる","うま.れる","う.まれ","うまれ","う.む","お.う","は.える","は.やす","き","なま","なま-","な.る","な.す","む.す","-う"}', 'N5', 1, 5, '751f', 'Pictograph: a young plant breaking out of the soil — life emerging. Its dozen readings (いきる, うまれる, なま, セイ…) all grow from this one sprout.', 'A seedling standing up out of the ground line — life itself, せい. Raw (なま) like a fresh shoot, born (うまれる) like a first leaf: every reading is this sprout at another age. The 先生 has simply been growing longer.'),
  ('先', '先', '["before","ahead","previous","future","precedence"]'::jsonb, '{"セン"}', '{"さき","ま.ず"}', 'N5', 1, 6, '5148', 'Compound ideograph: a foot (止, worn to a slanted form) above walking legs (儿) — a footprint out in front of the walker: whoever went ahead, before.', 'Fresh footprints ahead of you on the trail: someone went before — さき. The 先生 is simply the one ''born before'' you, walking the path first.'),
  ('千', '千', '["thousand"]'::jsonb, '{"セン"}', '{"ち"}', 'N5', 1, 3, '5343', 'Formed in oracle-bone script from person (人) + one (一) as a phonetic-numeric device: ''one (unit of) persons'' = a thousand.', 'A ten (十) wearing a swept hat: promoted a hundred ranks overnight — せん, one thousand. The hat is the zero-multiplier.'),
  ('川', '川', '["stream","river","river or three-stroke river radical (no. 47)"]'::jsonb, '{"セン"}', '{"かわ"}', 'N5', 1, 3, '5ddd', 'Pictograph: three lines of flowing water between two banks — a river drawn exactly as it looks from a hill.', 'Three currents running side by side downhill — かわ. The outer strokes are the banks, the middle one the fast water. Found in half the place-names of Japan (小川, 川口).'),
  ('足', '足', '["leg","foot","be sufficient","counter for pairs of footwear"]'::jsonb, '{"ソク"}', '{"あし","た.りる","た.る","た.す"}', 'N5', 1, 7, '8db3', 'Pictograph: the kneecap (the box) above a foot (an old form of 止) — the whole leg. ''To suffice'' is an ancient borrowed sense of the same character.', 'A knee, a shin, a foot planted flat — あし. Two of them are plenty: 足りる, ''that''s enough legs to stand on''.'),
  ('大', '大', '["large","big"]'::jsonb, '{"ダイ","タイ"}', '{"おお-","おお.きい","-おお.いに"}', 'N5', 1, 3, '5927', 'Pictograph: a person standing with arms and legs stretched wide — the human body making itself as big as it can.', '''How big was the fish?'' — arms flung wide: THIS big! おおきい. A stick figure showing off maximum size with its whole body.'),
  ('男', '男', '["male"]'::jsonb, '{"ダン","ナン"}', '{"おとこ","お"}', 'N5', 1, 7, '7537', 'Compound ideograph: rice field (田) + strength/plow (力) — the one whose muscle works the field: a man.', 'Strength (力) under the rice field (田): the farmhand flexing beneath his plot — おとこ. On restroom doors, he''s the 男 with the heavy lifting.'),
  ('中', '中', '["in","inside","middle","mean","center"]'::jsonb, '{"チュウ"}', '{"なか","うち","あた.る"}', 'N5', 1, 4, '4e2d', 'Ideograph: a pole planted through the exact center of a camp or banner — dead middle. Oracle-bone forms show a flagpole with streamers.', 'An arrow through the bullseye of a target box: right in the middle — なか. In compounds it means ''inside'' or ''throughout'': 中国, the Middle Country.'),
  ('天', '天', '["heavens","sky","imperial"]'::jsonb, '{"テン"}', '{"あまつ","あめ","あま-"}', 'N5', 1, 4, '5929', 'Ideograph: a line drawn above the big person (大) — that which stretches over every head: heaven, the sky.', 'The widest thing a person (大) can point at is the line above them: the heavens — てん. 天気 is the sky''s mood today.'),
  ('土', '土', '["soil","earth","ground","Turkey"]'::jsonb, '{"ド","ト"}', '{"つち"}', 'N5', 1, 3, '571f', 'Pictograph: a mound of earth raised on the ground line — the altar of the soil god in its oldest form.', 'A little pile of dirt on the ground with a sprout''s cross planted in it — つち. Saturday, 土曜日, is the day you dig in the garden.'),
  ('二', '二', '["two","two radical (no. 7)"]'::jsonb, '{"ニ","ジ"}', '{"ふた","ふた.つ","ふたたび"}', 'N5', 1, 2, '4e8c', 'Ideograph: two counting rods. The upper stroke is slightly shorter, as when two rods are laid neatly one above the other.', 'Two shelves: a short one on top, a long one below. Count them out loud — に, に — like knocking twice on a door.'),
  ('日', '日', '["day","sun","Japan","counter for days"]'::jsonb, '{"ニチ","ジツ"}', '{"ひ","-び","-か"}', 'N5', 1, 4, '65e5', 'Pictograph: the sun — originally a circle with a dot at its center, squared by the brush into a rectangle with a bar. One sun crossing the sky = one day.', 'A window with the blind half-drawn: through it, the sun. One sunrise per day — ひ, the sun; にち, the day it makes.'),
  ('入', '入', '["enter","insert"]'::jsonb, '{"ニュウ","ジュ"}', '{"い.る","-い.る","-い.り","い.れる","-い.れ","はい.る"}', 'N5', 1, 2, '5165', 'Pictograph: a wedge or arrowhead driving inward — or the flap of a tent parting as you step in. The mirror-twin of 人, but leaning the other way.', 'A tent flap pushed open inward: step in — はいる. Watch the lean: 人 walks by, 入 goes in. 入口 is where it happens.'),
  ('年', '年', '["year","counter for years"]'::jsonb, '{"ネン"}', '{"とし"}', 'N5', 1, 6, '5e74', 'Oracle-bone ideograph: a person carrying home the ripened grain (禾) — one harvest, one year. The strokes fused over time into the modern form.', 'A farmer bent under a sheaf of rice: another harvest carried home, another year gone — とし. 今年, this crop; 来年, the next.'),
  ('白', '白', '["white"]'::jsonb, '{"ハク","ビャク"}', '{"しろ","しら-","しろ.い"}', 'N5', 1, 5, '767d', 'Origin debated: commonly explained as a ray of light breaking from the sun (日 with a spark on top), or as a white acorn. Its ''bright, plain'' sense is ancient.', 'The first drop of daylight hitting the sun''s window at dawn: everything bleaches white — しろ. A sunbeam with the brightness turned all the way up.'),
  ('八', '八', '["eight","eight radical (no. 12)"]'::jsonb, '{"ハチ","ハツ"}', '{"や","や.つ","やっ.つ","よう"}', 'N5', 1, 2, '516b', 'Ideograph: two strokes leaning away from each other — the act of dividing something in two. Eight is the number you reach by halving three times (2·2·2).', 'Two ski tracks parting on the slope. Divide, divide, divide: 2, 4, 8 — はち. The strokes never touch, like a pie split for sharing.'),
  ('百', '百', '["hundred"]'::jsonb, '{"ヒャク","ビャク"}', '{"もも"}', 'N5', 1, 6, '767e', 'Phono-semantic (形声): one (一) on top for the count, white (白) beneath lending the ancient sound. One ''white'' = one hundred.', 'One (一) white (白) hair — the first of a hundred to come, says your grandmother. ひゃく! Count to one hundred and you''ve earned exactly one white hair.'),
  ('本', '本', '["book","present","main","origin","real","counter for long cylindrical things"]'::jsonb, '{"ホン"}', '{"もと"}', 'N5', 1, 5, '672c', 'Ideograph: a tree (木) with a stroke marking its base — the root, the origin. Books came later: the ''root'' of knowledge, and paper from the tree itself.', 'Mark the root of the tree: that is where everything begins — もと. From that root comes paper, and from paper the ほん you''re reading. 日本: the land at the sun''s root.'),
  ('名', '名', '["name","noted","distinguished","reputation"]'::jsonb, '{"メイ","ミョウ"}', '{"な","-な"}', 'N5', 1, 6, '540d', 'Compound ideograph: evening (夕) + mouth (口). In the dark you cannot be seen — so you call out your name to be known.', 'Too dark to see faces at dusk, so a mouth calls into the night: ''It''s me!'' — your name, なまえ. The password that works when eyes don''t.'),
  ('木', '木', '["tree","wood"]'::jsonb, '{"ボク","モク"}', '{"き","こ-"}', 'N5', 1, 4, '6728', 'Pictograph: a tree — trunk, spreading branches, roots below. Doubled it becomes a wood (林), tripled a forest (森).', 'Trunk up the middle, branches out, roots down — き. Thursday, 木曜日, is the tree''s day. Wherever wood is worked, this kanji stands at the left of the character.'),
  ('目', '目', '["eye","class","look","insight","experience","care","favor"]'::jsonb, '{"モク","ボク"}', '{"め","-め","ま-"}', 'N5', 1, 5, '76ee', 'Pictograph: an eye with its pupil, drawn horizontally on the oracle bones and later stood upright by the brush.', 'An eye standing on end: the two inner bars are the iris and pupil. Stack it next to 日 and 月 — sun, moon, and the め that watches them both.'),
  ('立', '立', '["stand up","rise","set up","erect"]'::jsonb, '{"リツ","リュウ","リットル"}', '{"た.つ","-た.つ","た.ち-","た.てる","-た.てる","た.て-","たて-","-た.て","-だ.て","-だ.てる"}', 'N5', 1, 5, '7acb', 'Pictograph: a person standing squarely on the ground line, arms out for balance — the act of standing itself.', 'Feet planted on the floor line, arms out: stand up! — たつ. A lamp standing at attention on its base; it holds this pose inside 駅 platforms and 立入禁止 signs alike.'),
  ('六', '六', '["six"]'::jsonb, '{"ロク","リク"}', '{"む","む.つ","むっ.つ","むい"}', 'N5', 1, 4, '516d', 'Originally the pictograph of a small hut with a roof; the word for ''six'' was written with it purely for its sound (rebus borrowing).', 'A tiny hut: pointed roof on top, two legs for walls. Six people are crammed inside — ろく, they groan, as the roof creaks.'),
  ('音', '音', '["sound","noise"]'::jsonb, '{"オン","イン","-ノン"}', '{"おと","ね"}', 'N4', 1, 9, '97f3', 'Derived from 言 ''say'' by adding a stroke inside the mouth — sound held in the mouth: tone without words yet.', 'A voice standing (立) on the sun (日), humming with no words — おと. Pure sound, waiting to become speech: turn up the 音楽.'),
  ('犬', '犬', '["dog"]'::jsonb, '{"ケン"}', '{"いぬ","いぬ-"}', 'N4', 1, 4, '72ac', 'Pictograph: a dog — the oracle-bone form shows the whole animal; the modern form keeps a big body (大) and one dot for the ear.', 'A big (大) creature with one flea (the dot) it can''t stop scratching — いぬ. Man''s best friend, one stroke away from ''big''.'),
  ('字', '字', '["character","letter","word","section of village"]'::jsonb, '{"ジ"}', '{"あざ","あざな","-な"}', 'N4', 1, 6, '5b57', 'Compound ideograph: a child (子) raised under a roof (宀). Characters were the ''children'' bred in the house of writing — simple signs combined and multiplied.', 'A child under the roof of the schoolhouse, copying its very first letter — ジ. Kanji breed like children: two simple ones move in together and a new 字 is born.'),
  ('森', '森', '["forest","woods"]'::jsonb, '{"シン"}', '{"もり"}', 'N4', 1, 12, '68ee', 'Compound ideograph: three trees (木) — more trees than a grove (林): a forest.', 'One tree is a tree, two is a grove (林), three is a forest deep enough to get lost in — もり. Count the canopy: the third tree sits on top of the other two.'),
  ('正', '正', '["correct","justice","righteous","10**40"]'::jsonb, '{"セイ","ショウ"}', '{"ただ.しい","ただ.す","まさ","まさ.に"}', 'N4', 1, 5, '6b63', 'Compound ideograph: a foot (止) marching straight at a line/target (一) — going straight at it: correct, upright.', 'Walk the straight line without wobbling: that is correct — ただしい. Teachers count scores with this kanji, one stroke per point: five strokes, one 正.'),
  ('青', '青', '["blue","green"]'::jsonb, '{"セイ","ショウ"}', '{"あお","あお-","あお.い"}', 'N4', 1, 8, '9752', 'Compound: a sprout (生, worn down) over a well or mineral vein (丹→月) — the fresh blue-green of plants over deep water. Japanese 青 spans both blue and green.', 'Young shoots reflected in a well: that fresh color between green and blue — あおい. Traffic lights in Japan turn 青 — blue — even when they look green.'),
  ('赤', '赤', '["red"]'::jsonb, '{"セキ","シャク"}', '{"あか","あか-","あか.い","あか.らむ","あか.らめる"}', 'N4', 1, 7, '8d64', 'Compound ideograph: a person (大) beside a great fire (火, flattened at the bottom) — skin glowing red in the blaze.', 'Stand big and close to the bonfire and your face turns red — あかい. A newborn is a 赤ちゃん: red-faced and yelling.'),
  ('早', '早', '["early","fast"]'::jsonb, '{"ソウ","サッ"}', '{"はや.い","はや","はや-","はや.まる","はや.める","さ-"}', 'N4', 1, 6, '65e9', 'Compound: the sun (日) just clearing the top of a pole (十) — the first hour of daylight: early.', 'The sun climbing the flagpole at dawn while everyone sleeps — はやい. Early and fast are the same kanji: the sun wastes no time.'),
  ('村', '村', '["village","town"]'::jsonb, '{"ソン"}', '{"むら"}', 'N4', 1, 7, '6751', 'Originally written 邨 (with a phonetic); the modern form is wood (木) + hand-measure (寸) — a settlement measured out in timber.', 'A hand (寸) pacing out plots between the trees (木): here the well, there the houses — a village, むら. Every RPG starts in one.'),
  ('町', '町', '["town","village","block","street"]'::jsonb, '{"チョウ"}', '{"まち"}', 'N4', 1, 7, '753a', 'Phono-semantic: rice field (田) + 丁 (phonetic チョウ) — the raised paths dividing fields into neat blocks; then the blocks of a town.', 'Fields (田) nailed (丁) into a tidy grid of streets — まち. The address system still counts in 丁目: block one, block two.'),
  ('田', '田', '["rice field","rice paddy"]'::jsonb, '{"デン"}', '{"た"}', 'N4', 1, 5, '7530', 'Pictograph: a rice paddy seen from above — the box is the dike, the cross the footpaths between plots.', 'A perfect aerial photo of a paddy: four plots, two paths — た. It grows inside half the surnames of Japan: 田中, 山田, 本田.'),
  ('文', '文', '["sentence","literature","style","art","decoration","figures","plan","literary radical (no. 67)"]'::jsonb, '{"ブン","モン"}', '{"ふみ","あや"}', 'N4', 1, 4, '6587', 'Pictograph: a standing figure with a pattern tattooed on the chest — ornament, pattern, and from there writing and literature.', 'A scholar in a crossed robe, patterns inked on his chest: the first text was worn, not written — ブン. 文学 is that ink grown into literature.'),
  ('夕', '夕', '["evening"]'::jsonb, '{"セキ"}', '{"ゆう"}', 'N4', 1, 3, '5915', 'Pictograph: the crescent moon just risen — half of 月, for the half-lit hour of dusk.', 'The moon with one stroke still missing: too early for full night — ゆう, the evening. 夕方 is when the sky can''t decide.'),
  ('力', '力', '["power","strength","strong","strain","bear up","exert"]'::jsonb, '{"リョク","リキ","リイ"}', '{"ちから"}', 'N4', 1, 2, '529b', 'Pictograph: a flexed arm with its bulge of muscle — or, by another old reading, a plow biting the earth. Raw strength either way.', 'A bicep curling into a hook — ちから. Wherever it hides in a kanji (男, 助, 動), someone is straining at something.'),
  ('林', '林', '["grove","forest"]'::jsonb, '{"リン"}', '{"はやし"}', 'N4', 1, 8, '6797', 'Compound ideograph: two trees (木) side by side — a stand of trees: a grove. Add a third and it thickens into 森.', 'Two trees planted like neighbors, close enough to share shade — はやし. Halfway between one lonely 木 and the deep 森.'),
  ('王', '王', '["king","rule","magnate"]'::jsonb, '{"オウ","-ノウ"}', '{}', 'N3', 1, 4, '738b', 'Pictograph of a great ceremonial axe, emblem of royal power; the classic reading sees three lines (heaven, humankind, earth) joined by one vertical: the king.', 'Heaven, people, earth — and one stroke holding all three together: that job is the king''s — オウ.'),
  ('貝', '貝', '["shellfish"]'::jsonb, '{"バイ"}', '{"かい"}', 'N3', 1, 7, '8c9d', 'Pictograph: a cowrie shell with its feelers — cowries were ancient China''s money, so 貝 marks value in 買, 貸, 質 and kin.', 'A shell on two little legs — かい. Wherever 貝 hides in a kanji, money is changing hands.'),
  ('玉', '玉', '["jewel","ball"]'::jsonb, '{"ギョク"}', '{"たま","たま-","-だま"}', 'N3', 1, 5, '7389', 'Pictograph: three jade discs strung on a cord; the dot was added to distinguish it from 王 ''king''.', 'The king (王) with one gem in his pocket — たま. Jade beads, rice balls, ten-yen coins: anything round and precious.'),
  ('糸', '糸', '["thread"]'::jsonb, '{"シ"}', '{"いと"}', 'N3', 1, 6, '7cf8', 'Pictograph: a twisted skein of silk. As a left-side component it spins through everything woven, tied or connected (紙, 線, 組).', 'A silk skein with loose ends dangling — いと. Follow the thread and half the kanji dictionary unravels.'),
  ('石', '石', '["stone"]'::jsonb, '{"セキ","シャク","コク"}', '{"いし"}', 'N3', 1, 5, '77f3', 'Pictograph: a boulder (口) lying at the foot of a cliff (厂) — stone.', 'One rock rolled off the cliff and sat down at the bottom — いし. It''s been there since the oracle bones.'),
  ('草', '草', '["grass","weeds","herbs","pasture","write","draft"]'::jsonb, '{"ソウ"}', '{"くさ","くさ-","-ぐさ"}', 'N3', 1, 9, '8349', 'Phono-semantic: plants (艹) + 早 ''early'' (phonetic ソウ) — the green that comes up earliest and everywhere: grass.', 'Up at dawn (早) before anything else in the garden: the weeds — くさ. Grass never sleeps in.'),
  ('竹', '竹', '["bamboo"]'::jsonb, '{"チク"}', '{"たけ"}', 'N3', 1, 6, '7af9', 'Pictograph: two bamboo stalks with drooping leaves. As a crown (⺮) it heads everything once made of bamboo: brushes, boxes, flutes, counting slips.', 'Two stalks leaning together, leaves like little flags — たけ. Under the bamboo crown, someone is always weaving or counting.'),
  ('虫', '虫', '["insect","bug","temper"]'::jsonb, '{"チュウ","キ"}', '{"むし"}', 'N3', 1, 6, '866b', 'Pictograph: originally a coiled viper; the sign broadened to cover every creeping, crawling creature: insects.', 'A grub standing upright with feelers out — むし. The kanji started as a snake and got demoted to bugs.'),
  ('何', '何', '["what"]'::jsonb, '{"カ"}', '{"なに","なん","なに-","なん-"}', 'N5', 2, 7, '4f55', 'Phono-semantic: person (亻) + 可 (phonetic カ). Originally ''to shoulder a load'' (the ancestor of 荷); borrowed since antiquity for the question word ''what''.', 'A person stopped by a strange box with a hook: ''What is that?'' — なに. The kanji of every beginner''s sentence: 何ですか.'),
  ('会', '会', '["meeting","meet","party","association","interview","join"]'::jsonb, '{"カイ","エ"}', '{"あ.う","あ.わせる","あつ.まる"}', 'N5', 2, 6, '4f1a', 'Simplified from 會: a lid closing over a layered steamer pot — things coming together as one: to meet.', 'A roof pulled down over rising steam: everyone gathered under one lid — あう. 会社 is where the lid closes on you every morning, カイシャ.'),
  ('外', '外', '["outside"]'::jsonb, '{"ガイ","ゲ"}', '{"そと","ほか","はず.す","はず.れる","と-"}', 'N5', 2, 5, '5916', 'Compound ideograph: evening (夕) + divination crack (卜). Divination performed at evening, outside the proper morning ritual — hence ''outside, other''.', 'At dusk (夕) the fortune-teller reads cracks (卜) in a bone by the city gate — outside the walls, where the wild things are: そと, 外国 the lands outside.'),
  ('間', '間', '["interval","space"]'::jsonb, '{"カン","ケン"}', '{"あいだ","ま","あい"}', 'N5', 2, 12, '9593', 'Compound ideograph: originally moonlight (月) shining through the crack of a gate (門) — later the sun (日) took the moon''s place. The gap itself: interval, in space or time.', 'Sunlight slicing through the gap between two gate doors: that sliver is the interval — あいだ. 時間 measures it in hours, 一週間 in laps of the week.'),
  ('魚', '魚', '["fish"]'::jsonb, '{"ギョ"}', '{"うお","さかな","-ざかな"}', 'N5', 2, 11, '9b5a', 'Pictograph: a whole fish — head at the top (𠂊), scaled body (田), and a tail that later flattened into four dots (灬).', 'Head, scaly belly, flick of a tail: a fish drawn head-up as if hauled from the water — さかな. The four dots are drops still falling from its fins.'),
  ('言', '言', '["say","word"]'::jsonb, '{"ゲン","ゴン"}', '{"い.う","こと"}', 'N5', 2, 7, '8a00', 'Pictograph: a mouth (口) with sound waves rising from it — speech leaving the lips. As a left-side component it marks nearly everything said in the language.', 'Four sound waves stacked over a mouth: words on their way out — いう. Whenever 言 stands at the left of a kanji, somebody is talking.'),
  ('古', '古', '["old"]'::jsonb, '{"コ"}', '{"ふる.い","ふる-","-ふる.す"}', 'N5', 2, 5, '53e4', 'Compound ideograph (会意) by the classic account: ten (十) mouths (口) — a story that has passed through ten generations of tellers is old indeed.', 'Ten mouths have told this tale before yours: it is ancient — ふるい. Picture a weathered cross planted over a stone box, standing there for centuries.'),
  ('午', '午', '["noon","sign of the horse","11AM-1PM","seventh sign of Chinese zodiac"]'::jsonb, '{"ゴ"}', '{"うま"}', 'N5', 2, 4, '5348', 'Pictograph of a wooden pestle, borrowed for the zodiac sign of the Horse — whose hour straddles midday. Hence ''noon'': 午前 before it, 午後 after it.', 'A pestle standing bolt upright, like the sun at the top of the sky: noon — ゴ. Morning is 午前, ''before the pestle''; afternoon 午後, ''after it''.'),
  ('後', '後', '["behind","back","later"]'::jsonb, '{"ゴ","コウ"}', '{"のち","うし.ろ","うしろ","あと","おく.れる"}', 'N5', 2, 9, '5f8c', 'Compound ideograph: a step (彳) hobbled by a small thread (幺) and a dragging foot (夂) — falling behind on the road; hence ''behind'' in space and ''after'' in time.', 'Shoelace tangled (幺), foot dragging (夂): you fall behind the group — うしろ, and you''ll arrive after them — あと, ゴ (午後, the afternoon limping in after noon).'),
  ('語', '語', '["word","speech","language"]'::jsonb, '{"ゴ"}', '{"かた.る","かた.らう"}', 'N5', 2, 14, '8a9e', 'Phono-semantic: words (言) + 吾 ''I, we'' (phonetic ゴ) — speech exchanged between me and you: language.', 'My (吾) words (言) — the language I carry: ゴ. It closes the name of every tongue on earth: 日本語, フランス語, and yours next.'),
  ('行', '行', '["going","journey","carry out","conduct","act","line","row","bank"]'::jsonb, '{"コウ","ギョウ","アン"}', '{"い.く","ゆ.く","-ゆ.き","-ゆき","-い.き","-いき","おこな.う","おこ.なう"}', 'N5', 2, 6, '884c', 'Pictograph: a crossroads seen from above — both halves are streets. To go is to be out where the roads cross; as a component it flanks kanji of movement.', 'Two street corners facing each other: you''re standing in the intersection, already going — いく. 銀行, the bank, sits on the busiest crossroads in town, コウ/ギョウ/いく — a kanji with three lives, all on the move.'),
  ('高', '高', '["tall","high","expensive"]'::jsonb, '{"コウ"}', '{"たか.い","たか","-だか","たか.まる","たか.める"}', 'N5', 2, 10, '9ad8', 'Pictograph: a tall watchtower or gate-building — roof at the top, upper chamber, and the gateway below. ''High'' in every later sense, including prices.', 'A pagoda drawn floor by floor: roof, window, gate — たかい. High building, high rank, high price: the tower charges admission.'),
  ('国', '国', '["country"]'::jsonb, '{"コク"}', '{"くに"}', 'N5', 2, 8, '56fd', 'Simplified from 國: a territory enclosed by borders (囗); the modern form places a jewel (玉) inside — the treasure a border exists to guard: a country.', 'A jewel locked inside four walls: the realm and its crown treasure — くに. Line them up: 中国, 外国, and your own 国.'),
  ('今', '今', '["now"]'::jsonb, '{"コン","キン"}', '{"いま"}', 'N5', 2, 4, '4eca', 'Ideograph: a cover coming down over something — the instant caught and held under the lid: now.', 'A lid snapping shut on the present moment before it escapes — いま. 今日 is today under the lid; 今 is the only kanji you can never write yesterday.'),
  ('時', '時', '["time","hour"]'::jsonb, '{"ジ"}', '{"とき","-どき"}', 'N5', 2, 10, '6642', 'Phono-semantic: sun (日) gives the meaning — time measured by the sun — while 寺 (temple) lends the reading ジ. Temples were the timekeepers, ringing the hours.', 'The temple bell tolls as the sun moves: that is how you know the hour — とき, ジ. 何時ですか — ''what time is it?'' asks the sun of the temple.'),
  ('社', '社', '["company","firm","office","association","shrine"]'::jsonb, '{"シャ"}', '{"やしろ"}', 'N5', 2, 7, '793e', 'Compound ideograph: altar (示, compressed to ネ) + soil (土) — the shrine of the local earth god, where the community gathered. From ''gathered community'' came ''society'' and ''company''.', 'An altar planted in the village soil: the whole community assembles there — シャ. Today the assembly wears suits: 会社. The gods kept the original office: 神社.'),
  ('週', '週', '["week"]'::jsonb, '{"シュウ"}', '{}', 'N5', 2, 11, '9031', 'Phono-semantic: movement (辶) + 周 ''circuit, all around'' (phonetic シュウ) — going one full round. Applied to the seven-day cycle when Japan adopted the Western week.', 'Walk one full lap (周) around the calendar and you''re back where you started: one week — シュウ. 毎週, every lap.'),
  ('書', '書', '["write"]'::jsonb, '{"ショ"}', '{"か.く","-が.き","-がき"}', 'N5', 2, 10, '66f8', 'Compound ideograph: a hand gripping a brush (聿) over a tablet (the 日-shaped block below) — the act of writing caught mid-stroke.', 'A hand pressing a brush down onto the page, line after line — かく. The stacked horizontals are the ruled lines of the notebook; 図書館 keeps what the brush leaves behind.'),
  ('少', '少', '["few","little"]'::jsonb, '{"ショウ"}', '{"すく.ない","すこ.し"}', 'N5', 2, 4, '5c11', 'Derived from 小 (small) with an extra stroke shaving something off — smaller still in quantity: few, scarce.', 'Take ''small'' (小) and slice one more piece off with a diagonal cut: now there''s hardly any left — すこし, すくない.'),
  ('食', '食', '["eat","food"]'::jsonb, '{"ショク","ジキ"}', '{"く.う","く.らう","た.べる","は.む"}', 'N5', 2, 9, '98df', 'Pictograph: a lid (𠆢) over a full food vessel on its stand — a covered dish waiting to be eaten. The component form 飠 fronts most kanji of eating.', 'Lift the lid: dinner is served — たべる. Everything under that little roof is on the menu; 食べ物 is whatever the lid was hiding.'),
  ('新', '新', '["new"]'::jsonb, '{"シン"}', '{"あたら.しい","あら.た","あら-","にい-"}', 'N5', 2, 13, '65b0', 'Phono-semantic: 亲 (a standing tree, phonetic シン) + axe (斤) — wood at the instant the axe cuts it: fresh, new.', 'The axe bites and the pale fresh grain gleams where the bark fell away: brand-new — あたらしい. 新聞: the news, cut fresh every morning.'),
  ('西', '西', '["west","Spain"]'::jsonb, '{"セイ","サイ","ス"}', '{"にし"}', 'N5', 2, 6, '897f', 'Traditionally: a bird settling into its nest — which birds do at sundown, in the direction of the setting sun: west. The oldest forms show a woven nest or basket.', 'A bird folding itself into a basket-nest as the sun drops behind it: face that glow and you face west — にし. 関西 lies that way from Tokyo.'),
  ('前', '前', '["in front","before"]'::jsonb, '{"ゼン"}', '{"まえ","-まえ"}', 'N5', 2, 9, '524d', 'Originally a foot aboard a boat gliding forward — ''to advance''; the blade (刂) entered the character early as a graphic-phonetic addition. ''In front, before'' is the settled meaning.', 'On the prow of the boat, blade in hand, cutting the water ahead: everything in front of you — まえ. 名前 puts your name out front for the world.'),
  ('多', '多', '["many","frequent","much"]'::jsonb, '{"タ"}', '{"おお.い","まさ.に","まさ.る"}', 'N5', 2, 6, '591a', 'Compound ideograph: two evenings (夕) stacked — night after night after night. Repetition itself made visible: many.', 'Two crescent moons piled up like plates after a feast: one evening wasn''t enough, there were many — おおい. Stack anything twice in kanji and it multiplies.'),
  ('長', '長', '["long","leader","superior","senior"]'::jsonb, '{"チョウ"}', '{"なが.い","おさ"}', 'N5', 2, 8, '9577', 'Pictograph: an elder with long flowing hair leaning on a staff — long in hair, long in years; and the eldest leads, hence ''chief''.', 'Hair so long it takes six strokes, and a cane to match — ながい. The one who''s been here longest sits at the head of the table: 社長, 校長.'),
  ('店', '店', '["store","shop"]'::jsonb, '{"テン"}', '{"みせ","たな"}', 'N5', 2, 8, '5e97', 'Phono-semantic: a building with a canopy (广) + 占 ''occupy a spot'' (phonetic テン) — a stall pitched under an awning that claimed its corner: a shop.', 'Under the awning, a fortune-teller (占) set up shop and never left — みせ. The 喫茶店 on the corner has occupied that spot forever.'),
  ('電', '電', '["electricity"]'::jsonb, '{"デン"}', '{}', 'N5', 2, 13, '96fb', 'Compound: rain (雨) over a lightning bolt with a trailing tail (an old form of 申, itself a pictograph of forked lightning). First ''lightning'', then ''electricity''.', 'Out of the storm cloud, a bolt with a hooked tail — raw electricity: デン. It powers the whole modern lexicon: 電気, 電車, 電話.'),
  ('東', '東', '["east"]'::jsonb, '{"トウ"}', '{"ひがし"}', 'N5', 2, 8, '6771', 'Traditionally explained as the sun (日) rising behind a tree (木) — the east. Paleographers read the oldest form as a tied sack, borrowed for its sound; the sunrise story is what stuck.', 'The sun climbing up through the branches of a tree at dawn: look that way and you face east — ひがし. 東京: the capital of the east.'),
  ('道', '道', '["road-way","street","district","journey","course","moral","teachings"]'::jsonb, '{"ドウ","トウ"}', '{"みち","いう"}', 'N5', 2, 12, '9053', 'Compound ideograph: movement (辶) + head (首) — walking with your head leading you: the road you follow, and figuratively the Way (as in 柔道, 茶道).', 'Your head out in front, feet rolling beneath it down the path — みち. Every martial art ends in this kanji: the road you walk your whole life, ドウ.'),
  ('読', '読', '["read"]'::jsonb, '{"ドク","トク","トウ"}', '{"よ.む","-よ.み"}', 'N5', 2, 14, '8aad', 'Phono-semantic: words (言) + 売 ''sell'' (simplified from 賣, the old phonetic ドク/トク) — words offered up like wares, taken in by reading.', 'A street seller (売) hawking words (言) aloud — and you, reading the signboard: よむ. 読書 is buying stories with your eyes.'),
  ('南', '南', '["south"]'::jsonb, '{"ナン","ナ"}', '{"みなみ"}', 'N5', 2, 9, '5357', 'Origin debated — the oldest forms show a hanging bell or a tent; the classic account reads it as a shelter whose opening faces the warm side. Whatever the picture, it has meant ''south'' for three millennia.', 'A greenhouse with its door thrown open to the sun''s warm side: plants crowding toward the south — みなみ. 東南アジア: where that warmth lives year-round.'),
  ('買', '買', '["buy"]'::jsonb, '{"バイ"}', '{"か.う"}', 'N5', 2, 12, '8cb7', 'Compound ideograph: a net (罒) over a cowrie shell (貝, ancient money) — netting goods with money: to buy.', 'Casting a net straight over the treasure shell: haul it in, it''s yours — かう. 買い物: hunting with a wallet for a net.'),
  ('半', '半', '["half","middle","odd number","semi-","part-"]'::jsonb, '{"ハン"}', '{"なか.ば"}', 'N5', 2, 5, '534a', 'Compound ideograph: divide (八) atop an ox (牛) — an ox split down the middle for sharing: half.', 'The ox chopped clean in two — each side gets half, はん. Clock language lives here: 三時半, half past three.'),
  ('父', '父', '["father"]'::jsonb, '{"フ"}', '{"ちち"}', 'N5', 2, 4, '7236', 'Pictograph: a hand gripping a stone axe — the provider and protector of the household: father.', 'Crossed arms holding two axes: dad guarding the door — ちち. Address him gently and he softens to お父さん.'),
  ('分', '分', '["part","minute of time","segment","share","degree","one''s lot","duty","understand","know","rate","1%","chances","shaku/100"]'::jsonb, '{"ブン","フン","ブ"}', '{"わ.ける","わ.け","わ.かれる","わ.かる","わ.かつ"}', 'N5', 2, 4, '5206', 'Compound ideograph: divide (八) + sword (刀) — a blade splitting something in two: a part. An hour cut into sixty parts gives the minute; a thing cut open gives understanding (分かる).', 'The sword slices the pie in two — one part for you, ブン. Slice the hour: minutes, フン. Slice a problem open: 分かった, got it!'),
  ('聞', '聞', '["hear","ask","listen"]'::jsonb, '{"ブン","モン"}', '{"き.く","き.こえる"}', 'N5', 2, 14, '805e', 'Phono-semantic: ear (耳) inside gate (門, phonetic モン→ブン) — an ear pressed to the gate: to hear; and, in Japanese, to ask.', 'An ear flattened against the gate, catching every word from the other side — きく. To hear is half of it; the nosy half is to ask. 新聞: everything the ear at the gate collected, printed by morning.'),
  ('母', '母', '["mother"]'::jsonb, '{"ボ"}', '{"はは","も"}', 'N5', 2, 5, '6bcd', 'Pictograph: the woman sign (女) with two dots added for the breasts — a nursing mother. One of the most transparent kanji in the script.', 'A woman with two dots: the mother who nursed you — はは. The frame around the dots is her embrace; every stroke leans inward, protective.'),
  ('北', '北', '["north"]'::jsonb, '{"ホク"}', '{"きた"}', 'N5', 2, 5, '5317', 'Compound ideograph: two people sitting back to back — the origin of 背 ''back''. In a south-facing culture, north is the direction at everyone''s back.', 'Two travelers huddle back to back against the cold wind: they''re facing away from the north — きた. 北海道 is where they huddle hardest.'),
  ('毎', '毎', '["every"]'::jsonb, '{"マイ"}', '{"ごと","-ごと.に"}', 'N5', 2, 6, '6bce', 'Originally the mother sign (母) crowned with a hairpin or sprout — fertile, ever-producing growth; borrowed early for ''every, each''.', 'A mother with a feather in her hair, up at dawn without fail: every single day — まい. 毎日, 毎週, 毎年: she never misses one.'),
  ('万', '万', '["ten thousand","10,000"]'::jsonb, '{"マン","バン"}', '{"よろず"}', 'N5', 2, 3, '4e07', 'Simplification of 萬, originally the pictograph of a scorpion, borrowed since antiquity for the number 10,000.', 'A scorpion with its tail curled — count its swarm of eggs: ten thousand, まん. In prices it swings that tail through your wallet: 一万円.'),
  ('友', '友', '["friend"]'::jsonb, '{"ユウ"}', '{"とも"}', 'N5', 2, 4, '53cb', 'Compound ideograph: two right hands reaching the same way — hands joined in common work: a friend.', 'Two hands stacked in a team huddle — とも. A 友だち is the hand that shows up when yours is full.'),
  ('来', '来', '["come","due","next","cause","become"]'::jsonb, '{"ライ","タイ"}', '{"く.る","きた.る","きた.す","き.たす","き.たる","き","こ"}', 'N5', 2, 7, '6765', 'Simplified from 來, the pictograph of a ripened wheat plant. Legend held that wheat ''came from heaven'' — so the grain sign was borrowed for ''to come'' and never given back.', 'A wheat stalk waving you over from the field''s edge: come! — くる. What is on its way is 来る; next year, 来年, is already walking toward you.'),
  ('話', '話', '["tale","talk"]'::jsonb, '{"ワ"}', '{"はな.す","はなし"}', 'N5', 2, 13, '8a71', 'Phono-semantic: words (言) + tongue (舌, from an older phonetic) — the tongue shaping words into a story or conversation.', 'Words (言) rolled off a tongue (舌) and braided into a tale — はなし. Phone conversations are 電話: electric talk.'),
  ('引', '引', '["pull","tug","jerk","admit","install","quote","refer to"]'::jsonb, '{"イン"}', '{"ひ.く","ひ.ける"}', 'N4', 2, 4, '5f15', 'Compound ideograph: a bow (弓) plus a single vertical stroke — the string drawn back: to pull.', 'Grab the bowstring (the lone stroke) and pull the bow (弓) to full stretch — ひく. Doors in Japan tell you which side does it: 引 pull, 押 push.'),
  ('遠', '遠', '["distant","far"]'::jsonb, '{"エン","オン"}', '{"とお.い"}', 'N4', 2, 13, '9060', 'Phono-semantic: movement (辶) + 袁 ''long flowing robe'' (phonetic エン) — a walk so long you need your traveling robe: distant.', 'Hitch up the long robe and start walking: it''s far — とおい. 遠足 is the school excursion that never seems to end.'),
  ('夏', '夏', '["summer"]'::jsonb, '{"カ","ガ","ゲ"}', '{"なつ"}', 'N4', 2, 10, '590f', 'Pictograph: a grand masked dancer — a great head with trailing legs (夂) — from the midsummer festival dances of ancient China.', 'A masked dancer stamping slow steps in the heat of the festival night — なつ. Summer is when the mask comes out and the legs drag.'),
  ('家', '家', '["house","home","family","professional","expert","performer"]'::jsonb, '{"カ","ケ"}', '{"いえ","や","うち"}', 'N4', 2, 10, '5bb6', 'Compound ideograph: a pig (豕) under a roof (宀) — livestock beneath the family roof was the ancient household''s wealth: home.', 'A pig snoring under the roof: the house is doing well — いえ. Home is where the bacon sleeps; the ~カ ending also names the expert ''of the house'': 作家, 画家.'),
  ('歌', '歌', '["song","sing"]'::jsonb, '{"カ"}', '{"うた","うた.う"}', 'N4', 2, 14, '6b4c', 'Phono-semantic: 哥 (two 可, phonetic カ) + 欠, the wide-open mouth — breath pouring out in melody: song.', 'Two karaoke prompts (可可) and a mouth thrown wide open (欠) — うた! The 歌手 holds the note; you hold the remote.'),
  ('画', '画', '["brush-stroke","picture"]'::jsonb, '{"ガ","カク","エ","カイ"}', '{"えが.く","かく.する","かぎ.る","はかりごと","はか.る"}', 'N4', 2, 8, '753b', 'Simplified from 畫: a hand with a brush (聿) drawing the boundaries of a field (田) — to draw; a drawn stroke; a picture.', 'A framed field hung on the wall: the first landscape painting — ガ. Movies are 映画, moving pictures; each kanji stroke is one 画.'),
  ('回', '回', '["-times","round","game","revolve","counter for occurrences"]'::jsonb, '{"カイ","エ"}', '{"まわ.る","-まわ.る","-まわ.り","まわ.す","-まわ.す","まわ.し-","-まわ.し","もとお.る","か.える"}', 'N4', 2, 6, '56de', 'Pictograph: a spiral, squared by the brush into a box within a box — turning around, a revolution, hence a counter for repetitions.', 'A whirlpool drawn with a ruler: around and around — まわる. Each full loop counts one time: 一回, 二回, 三回.'),
  ('海', '海', '["sea","ocean"]'::jsonb, '{"カイ"}', '{"うみ"}', 'N4', 2, 9, '6d77', 'Phono-semantic: water (氵) + 毎 ''every'' (phonetic カイ) — the water every river runs home to: the sea.', 'Every (毎) drop of water (氵) ends up in the same place — うみ. Mother ocean: look closely, 母 is sitting inside 毎.'),
  ('楽', '楽', '["music","comfort","ease"]'::jsonb, '{"ガク","ラク","ゴウ"}', '{"たの.しい","たの.しむ","この.む"}', 'N4', 2, 13, '697d', 'Simplified from 樂: a great drum hung with bells on a wooden stand (木) — music; and the ease and pleasure music brings.', 'A festival drum on its wooden stand, bells jingling on both sides — music, ガク; and the crowd''s face: 楽しい, たのしい. One kanji, both the song and the smile.'),
  ('顔', '顔', '["face","expression"]'::jsonb, '{"ガン"}', '{"かお"}', 'N4', 2, 18, '9854', 'Phono-semantic: 彦 ''handsome young man'' (phonetic ガン) + 頁 ''head'' — the front of the head at its most presentable: the face.', 'The handsome one (彦) turns his head (頁) toward the camera: that''s the face — かお. 顔 is what 洗顔 washes and 笑顔 lights up.'),
  ('帰', '帰', '["homecoming","arrive at","lead to","result in"]'::jsonb, '{"キ"}', '{"かえ.る","かえ.す","おく.る","とつ.ぐ"}', 'N4', 2, 10, '5e30', 'Simplified from 歸: troops (𠂤) coming back to the wife''s broom (帚) — the soldier returning to swept floors: to go home.', 'The sword hung up at the door, the broom waiting inside: homecoming — かえる. ただいま! is this kanji spoken aloud.'),
  ('牛', '牛', '["cow"]'::jsonb, '{"ギュウ"}', '{"うし"}', 'N4', 2, 4, '725b', 'Pictograph: an ox head seen from the front — the top strokes are the horns, the vertical its long face.', 'Face-to-face with an ox: one horn up, ears out, the long nose down the middle — うし. 牛乳 is what it gives; 牛肉 is what it becomes.'),
  ('京', '京', '["capital","10**16"]'::jsonb, '{"キョウ","ケイ","キン"}', '{"みやこ"}', 'N4', 2, 8, '4eac', 'Pictograph: a tall building raised on high ground — the watchtower of the royal city: the capital.', 'A palace tower on the hill, visible for miles: you''ve reached the capital — キョウ. It anchors both 東京 and 京都 — the new capital and the old.'),
  ('強', '強', '["strong"]'::jsonb, '{"キョウ","ゴウ"}', '{"つよ.い","つよ.まる","つよ.める","し.いる","こわ.い"}', 'N4', 2, 11, '5f37', 'Originally the name of a hard-shelled weevil; borrowed early for 彊 ''powerful bow''. The bow (弓) stayed on as the character''s anchor of meaning.', 'A bow (弓) so taut even the armored beetle (虫) bounces off — つよい. 勉強, studying, is this strength applied to your own skull.'),
  ('教', '教', '["teach","faith","doctrine"]'::jsonb, '{"キョウ"}', '{"おし.える","おそ.わる"}', 'N4', 2, 11, '6559', 'Compound: a child (子) under crossed counting-sticks (爻), with the master''s hand holding a rod (攵) — instruction, old style: to teach.', 'The old master taps the board, the child copies the crossed strokes — おしえる. 教室 is the room where the tapping happens.'),
  ('近', '近', '["near","early","akin","tantamount"]'::jsonb, '{"キン","コン"}', '{"ちか.い"}', 'N4', 2, 7, '8fd1', 'Phono-semantic: movement (辶) + 斤 ''axe'' (phonetic キン) — within walking distance of the sound of the axe: near.', 'If you can hear the axe chopping, you''re almost there — ちかい. 近所 is everything within one axe-echo of your door.'),
  ('兄', '兄', '["elder brother","big brother"]'::jsonb, '{"ケイ","キョウ"}', '{"あに"}', 'N4', 2, 5, '5144', 'Compound ideograph: a mouth (口) on legs (儿) — the sibling old enough to speak for the others: the elder brother.', 'A walking mouth that never stops giving orders — あに. Politely he''s お兄さん; in the kanji he''s still just a bossy mouth on legs.'),
  ('計', '計', '["plot","plan","scheme","measure"]'::jsonb, '{"ケイ"}', '{"はか.る","はか.らう"}', 'N4', 2, 9, '8a08', 'Compound ideograph: words (言) + ten (十) — counting out loud to ten: to reckon, measure, plan.', 'Count to ten before you act — that''s a plan, ケイ. The 時計 on your wrist counts for you, all day long.'),
  ('元', '元', '["beginning","former time","origin"]'::jsonb, '{"ゲン","ガン"}', '{"もと"}', 'N4', 2, 4, '5143', 'Pictograph: a person (儿) with the head emphasized by two strokes — the head as the origin-point of the body: beginning, source.', 'A pair of legs carrying the ''first thing'' on top: the head, where everything starts — もと. 元気 is your original energy, factory settings restored.'),
  ('光', '光', '["ray","light"]'::jsonb, '{"コウ"}', '{"ひか.る","ひかり"}', 'N4', 2, 6, '5149', 'Compound ideograph: fire (火, flattened) carried on a person''s legs (儿) — a torch-bearer: light on the move, rays.', 'A runner carrying the torch through the dark, sparks streaming — ひかり. Light with legs: that''s a ray.'),
  ('工', '工', '["craft","construction","katakana e radical (no. 48)"]'::jsonb, '{"コウ","ク","グ"}', '{}', 'N4', 2, 3, '5de5', 'Pictograph: a carpenter''s square or work-tool — craft, work, construction. One of the oldest tool-signs in the script.', 'An I-beam standing in the frame of a building site — コウ. Wherever 工 appears (工事, 工場), someone in a helmet is measuring twice.'),
  ('広', '広', '["wide","broad","spacious"]'::jsonb, '{"コウ"}', '{"ひろ.い","ひろ.まる","ひろ.める","ひろ.がる","ひろ.げる"}', 'N4', 2, 5, '5e83', 'Simplified from 廣: a building (广) with a vast interior (the phonetic 黄 reduced to 厶) — a roomy hall: wide, spacious.', 'Under one roof, so much empty floor that a single elbow (厶) rattles around in it — ひろい. 広場: the wide-open plaza.'),
  ('考', '考', '["consider","think over"]'::jsonb, '{"コウ"}', '{"かんが.える","かんが.え"}', 'N4', 2, 6, '8003', 'Phono-semantic: an old man (耂) + a bent breath-stroke (丂, phonetic コウ) — the elder bent over a question: to ponder.', 'The old master strokes his beard, thoughts bending like the bottom stroke — かんがえる. Real thinking has a crook in it.'),
  ('合', '合', '["fit","suit","join"]'::jsonb, '{"ゴウ","ガッ","カッ"}', '{"あ.う","-あ.う","あ.い","あい-","-あ.い","-あい","あ.わす","あ.わせる","-あ.わせる"}', 'N4', 2, 6, '5408', 'Compound ideograph: a lid (亼) settling onto a mouth or vessel (口) — two halves made for each other: to fit, to match.', 'The lid clicks perfectly onto the jar — あう. Whatever matches, matches here: 試合 a match of players, 都合 a match of schedules.'),
  ('黒', '黒', '["black"]'::jsonb, '{"コク"}', '{"くろ","くろ.ずむ","くろ.い"}', 'N4', 2, 11, '9ed2', 'Simplified from 黑: a chimney vent blackened by the fire (灬) burning below — soot: black.', 'Look up the chimney over the flames: everything the smoke touched is black — くろい. The four dots are the fire still cooking the soot.'),
  ('作', '作', '["make","production","prepare","build"]'::jsonb, '{"サク","サ"}', '{"つく.る","つく.り","-づく.り"}', 'N4', 2, 7, '4f5c', 'Phono-semantic: person (亻) + 乍 ''to hew, notch'' (phonetic サク) — a person cutting something into shape: to make.', 'A craftsman notching wood, chip by chip, until the thing exists — つくる. The 作家 hews sentences instead.'),
  ('姉', '姉', '["elder sister"]'::jsonb, '{"シ"}', '{"あね","はは"}', 'N4', 2, 8, '59c9', 'Phono-semantic: woman (女) + a right side descended from an old phonetic (written like 市 ''market'' today) — the elder sister.', 'The young woman (女) sent to the market (市) with the family purse: responsibility means you''re the elder sister — あね, お姉さん.'),
  ('市', '市', '["market","city","town"]'::jsonb, '{"シ"}', '{"いち"}', 'N4', 2, 5, '5e02', 'Pictograph: a pole with a banner (亠) raised over cloth stalls (巾) — the sign that market day is on; later the market town, the city.', 'Raise the flag over the cloth stalls and the whole town gathers — いち, the market; シ, the city it grew into (広島市, 京都市).'),
  ('思', '思', '["think"]'::jsonb, '{"シ"}', '{"おも.う","おもえら.く","おぼ.す"}', 'N4', 2, 9, '601d', 'Compound ideograph: originally the fontanelle/brain (囟, later confused with 田) over the heart (心) — brain and heart working together: to think, to feel.', 'The field on top is your brain''s little plot; the heart below waters it — おもう. In Japanese you think with both: と思います.'),
  ('止', '止', '["stop","halt"]'::jsonb, '{"シ"}', '{"と.まる","-ど.まり","と.める","-と.める","-ど.め","とど.める","とど.め","とど.まる","や.める","や.む","-や.む","よ.す","-さ.す","-さ.し"}', 'N4', 2, 4, '6b62', 'Pictograph: a footprint — the foot planted: to stop. As a component it walks through 歩, 正, 歴 and dozens more.', 'A foot slammed flat on the ground: halt! — とまる. Red sign in Japan: 止まれ. The footprint that refuses to move.'),
  ('紙', '紙', '["paper"]'::jsonb, '{"シ"}', '{"かみ"}', 'N4', 2, 10, '7d19', 'Phono-semantic: thread (糸) + 氏 (phonetic シ) — sheets felted from silk and plant fiber: paper, which China invented from exactly that.', 'Mash the fibers (糸) flat and let them dry into a sheet — かみ. A 手紙 is fiber that carries your handwriting across the country.'),
  ('自', '自', '["oneself"]'::jsonb, '{"ジ","シ"}', '{"みずか.ら","おの.ずから","おの.ずと"}', 'N4', 2, 6, '81ea', 'Pictograph: a nose seen from the front. To this day Japanese speakers point at their nose to say ''me?'' — oneself.', 'Point at your own nose: me, myself — ジ. Everything automatic (自動), self-made (自分) or free-willed (自由) starts at the nose.'),
  ('室', '室', '["room","apartment","chamber","greenhouse","cellar"]'::jsonb, '{"シツ"}', '{"むろ"}', 'N4', 2, 9, '5ba4', 'Phono-semantic: roof (宀) + 至 ''to arrive'' (phonetic シツ) — the space under the roof you arrive into: a room.', 'Walk under the roof until you can go no further (至): you''ve arrived in the room — シツ. The 教室 is the room the school day arrives at.'),
  ('弱', '弱', '["weak","frail"]'::jsonb, '{"ジャク"}', '{"よわ.い","よわ.る","よわ.まる","よわ.める"}', 'N4', 2, 10, '5f31', 'Compound: two bows (弓) with soft frayed decorations hanging from them — ornamental bows never meant to fire: weak.', 'Two ceremonial bows dripping with tassels: pretty, useless in a fight — よわい. Twice the bows, half the strength.'),
  ('首', '首', '["neck","counter for songs and poems"]'::jsonb, '{"シュ"}', '{"くび"}', 'N4', 2, 9, '9996', 'Pictograph: a head with its hair (the top strokes) and its face reduced to an eye — the head, and by extension the neck it sits on.', 'Hair on top, eye in the middle: a head planted on a neck — くび. The 首相 is the ''neck minister'': the head of government.'),
  ('秋', '秋', '["autumn"]'::jsonb, '{"シュウ"}', '{"あき","とき"}', 'N4', 2, 9, '79cb', 'Compound ideograph: grain (禾) + fire (火) — the stubble fires burning after harvest: autumn.', 'The harvest is in and the fields are set alight; smoke and gold everywhere — あき. Autumn is grain plus flame.'),
  ('春', '春', '["springtime","spring (season)"]'::jsonb, '{"シュン"}', '{"はる"}', 'N4', 2, 9, '6625', 'Compound: sprouts pushing up (an old form of 屯, worn into 三 + 人) under the sun (日) — the season of germination: spring.', 'Three shoots and a pair of legs racing up toward the sun — はる. Spring is the ground sprinting.'),
  ('場', '場', '["location","place"]'::jsonb, '{"ジョウ","チョウ"}', '{"ば"}', 'N4', 2, 12, '5834', 'Phono-semantic: soil (土) + 昜 ''sun rising high'' (phonetic ジョウ) — sunlit ground: an open place, a site.', 'A patch of earth the sun picks out like a spotlight: the place where things happen — ば. 場所, 工場, 野球場 — every stage is soil plus light.'),
  ('色', '色', '["color"]'::jsonb, '{"ショク","シキ"}', '{"いろ"}', 'N4', 2, 6, '8272', 'Compound: two bent human figures pressed together — originally facial flush and passion; from the color of the face came ''color'' itself.', 'A blush spreading over a face: the first color anyone notices — いろ. Feelings leak out as colors; that''s why 色 means both.'),
  ('心', '心', '["heart","mind","spirit","heart radical (no. 61)"]'::jsonb, '{"シン"}', '{"こころ","-ごころ"}', 'N4', 2, 4, '5fc3', 'Pictograph: the heart organ with its chambers — three drops of blood around the central hook. As a component (心/忄) it beats inside every kanji of feeling.', 'A heart mid-beat, blood flying — こころ. Find it at the bottom of 思, 悪, 意: whatever the top does, the heart underneath feels it.'),
  ('親', '親', '["parent","intimacy","relative","familiarity","dealer (cards)"]'::jsonb, '{"シン"}', '{"おや","おや-","した.しい","した.しむ"}', 'N4', 2, 16, '89aa', 'Phono-semantic: 亲 (a standing tree, phonetic シン) + 見 ''watch'' — the classic image: the parent up the tree, watching for the child''s return.', 'Climbed up the tree (亲), eyes on the road (見), waiting for you to come home — おや. That worried silhouette is what ''parent'' looks like.'),
  ('図', '図', '["map","drawing","plan","extraordinary","audacious"]'::jsonb, '{"ズ","ト"}', '{"え","はか.る"}', 'N4', 2, 7, '56f3', 'Simplified from 圖: a bordered territory (囗) with its granaries and roads sketched inside — a plan, a map.', 'A framed sheet with X-marks-the-spot scratched inside: the map — ズ. The 図書館 shelves whole worlds folded flat.'),
  ('声', '声', '["voice"]'::jsonb, '{"セイ","ショウ"}', '{"こえ","こわ-"}', 'N4', 2, 7, '58f0', 'Simplified from 聲: a hanging stone chime being struck, with an ear listening below — ringing sound: the voice.', 'A stone chime hangs from its frame; strike it and it answers — こえ. Your voice is the chime only you can ring.'),
  ('切', '切', '["cut","cutoff","be sharp"]'::jsonb, '{"セツ","サイ"}', '{"き.る","-き.る","き.り","-き.り","-ぎ.り","き.れる","-き.れる","き.れ","-き.れ","-ぎ.れ"}', 'N4', 2, 4, '5207', 'Phono-semantic: 七 (originally the picture of cutting crosswise, phonetic セツ) + 刀 ''sword'' — the blade doing what 七 once drew: to cut.', 'Seven (七) slices of the sword (刀) — きる. 切符 is a ticket cut from the roll; 大切 is what you''d never let be cut away.'),
  ('走', '走', '["run"]'::jsonb, '{"ソウ"}', '{"はし.る"}', 'N4', 2, 7, '8d70', 'Compound ideograph: a person leaning into a sprint (worn into 土) over a flying foot (止) — arms pumping: to run.', 'Torso pitched forward, one foot barely touching ground — はしる. The whole kanji is mid-stride; that''s why nothing in it stands straight.'),
  ('太', '太', '["plump","thick","big around"]'::jsonb, '{"タイ","タ"}', '{"ふと.い","ふと.る"}', 'N4', 2, 4, '592a', 'Derived from 大 ''big'' with a dot added for emphasis — bigger than big: thick, stout.', '''Big'' (大) after dessert: one extra dot at the belly — ふとい. The 太陽, the sun, is the plumpest thing in the sky.'),
  ('体', '体', '["body","substance","object","reality","counter for images"]'::jsonb, '{"タイ","テイ"}', '{"からだ","かたち"}', 'N4', 2, 7, '4f53', 'Modern form of 體: person (亻) + 本 ''root'' — the body as a person''s root and trunk, the base everything else grows from.', 'Your body is the root (本) your person (亻) is planted in — からだ. Take care of the trunk before decorating the branches.'),
  ('台', '台', '["pedestal","a stand","counter for machines and vehicles"]'::jsonb, '{"ダイ","タイ"}', '{"うてな","われ","つかさ"}', 'N4', 2, 5, '53f0', 'Adopted as the simple form of 臺 ''raised tower'' — an old character combining 厶 and 口, long used for platforms and stands; now also the counter for machines.', 'A little podium: base block (口) with a speaker''s arm (厶) resting on top — ダイ. Machines get counted on pedestals: 一台, 二台.'),
  ('知', '知', '["know","wisdom"]'::jsonb, '{"チ"}', '{"し.る","し.らせる"}', 'N4', 2, 8, '77e5', 'Compound ideograph: arrow (矢) + mouth (口) — an answer that flies from the mouth straight as an arrow: to know.', 'Ask, and the reply hits the bullseye before you finish the question — しる. Knowledge is a mouth with good aim.'),
  ('地', '地', '["ground","earth"]'::jsonb, '{"チ","ジ"}', '{}', 'N4', 2, 6, '5730', 'Phono-semantic: soil (土) + 也 (phonetic チ) — the ground underfoot; the earth as terrain rather than dirt.', 'Soil (土) stretching away in a long winding tail (也): the land itself — チ. 地図 maps it, 地下鉄 tunnels under it.'),
  ('池', '池', '["pond","cistern","pool","reservoir"]'::jsonb, '{"チ"}', '{"いけ"}', 'N4', 2, 6, '6c60', 'Phono-semantic: water (氵) + 也 (phonetic チ) — water gathered in a hollow of the ground: a pond. The twin of 地 with water swapped for soil.', 'Same winding hollow as 地, but filled with water (氵): the garden pond — いけ. Where 地 ends, 池 reflects.'),
  ('茶', '茶', '["tea"]'::jsonb, '{"チャ","サ"}', '{}', 'N4', 2, 9, '8336', 'Variant of the older 荼: the plant (艹) over a phonetic reduced to a canopy on a tree-like base — the tea bush, and the drink that conquered the world.', 'A leaf (艹) drying under a little canopy on a wooden rack: tea in the making — チャ. お茶 time is when the kanji finally gets poured.'),
  ('昼', '昼', '["daytime","noon"]'::jsonb, '{"チュウ"}', '{"ひる"}', 'N4', 2, 9, '663c', 'Simplified from 晝: a hand with a brush (聿) ruling off the hours of the sun (日) — the measured stretch of daylight: daytime.', 'A ruler laid across the sun: the bright hours, measured from bell to bell — ひる. 昼ご飯 lands exactly in the middle of the ruler.'),
  ('朝', '朝', '["morning","dynasty","regime","epoch","period","(North) Korea"]'::jsonb, '{"チョウ"}', '{"あさ"}', 'N4', 2, 12, '671d', 'Compound ideograph: the sun (日) rising through grass (the vertical strokes) while the moon (月) still hangs in the west — dawn: morning.', 'Sun climbing through the reeds on the left, pale moon not yet gone on the right — あさ. Morning is the shift change, caught mid-handover.'),
  ('鳥', '鳥', '["bird","chicken"]'::jsonb, '{"チョウ"}', '{"とり"}', 'N4', 2, 11, '9ce5', 'Pictograph: a long-tailed bird — crest, eye, folded wing, and the four dots of its tail feathers (灬).', 'Crest up, wing tucked, tail feathers fanned into four dots — とり. Remove one stroke (the eye) and the poor thing goes 烏, blind crow.'),
  ('通', '通', '["traffic","pass through","avenue","commute","counter for letters, notes, documents, etc."]'::jsonb, '{"ツウ","ツ"}', '{"とお.る","とお.り","-とお.り","-どお.り","とお.す","とお.し","-どお.し","かよ.う"}', 'N4', 2, 10, '901a', 'Phono-semantic: movement (辶) + 甬 ''hollow tube'' (phonetic ツウ) — passing through like water through a pipe: to go through, commute, connect.', 'The road becomes a tube and you slide through it, door to door, every day — とおる, かよう. 交通 is everyone in the tubes at once.'),
  ('弟', '弟', '["younger brother","faithful service to elders"]'::jsonb, '{"テイ","ダイ","デ"}', '{"おとうと"}', 'N4', 2, 7, '5f1f', 'Pictograph: a leather cord wound around a stake in descending turns — sequence, order of birth: the one born after, the younger brother.', 'The cord spirals down the pole, turn below turn: he comes after you — おとうと. Birth order, drawn as a winding.'),
  ('冬', '冬', '["winter"]'::jsonb, '{"トウ"}', '{"ふゆ"}', 'N4', 2, 5, '51ac', 'Compound: the tied-off ends of a rope (夂 — the year''s thread finished) with ice (冫) beneath — the season that closes the year: winter.', 'The year''s rope tied off, two icicles hanging from the knot — ふゆ. Winter is the calendar''s final knot, frozen stiff.'),
  ('答', '答', '["solution","answer"]'::jsonb, '{"トウ"}', '{"こた.える","こた.え"}', 'N4', 2, 12, '7b54', 'Phono-semantic: bamboo (竹) + 合 ''fit'' (phonetic トウ) — bamboo tally-slips split in two: the half that fits yours is the answer.', 'Snap the bamboo slip in two, keep one half: the reply that clicks (合) back into it is the answer — こたえ.'),
  ('頭', '頭', '["head","counter for large animals"]'::jsonb, '{"トウ","ズ","ト"}', '{"あたま","かしら","-がしら","かぶり"}', 'N4', 2, 16, '982d', 'Phono-semantic: 豆 ''ritual vessel on a stem'' (phonetic トウ) + 頁 ''head'' — the head on its stem of a neck.', 'A goblet (豆) balancing a big head (頁): don''t tip it — あたま. When it aches, the vessel is overfull: 頭が痛い.'),
  ('同', '同', '["same","agree","equal"]'::jsonb, '{"ドウ"}', '{"おな.じ"}', 'N4', 2, 6, '540c', 'Compound: one cover (the frame) over one (一) mouth (口) — many people speaking as one under one roof: same, together.', 'One hood, one line, one mouth: everyone inside says the same thing — おなじ. 同じ! echoes the room.'),
  ('肉', '肉', '["meat"]'::jsonb, '{"ニク"}', '{"しし"}', 'N4', 2, 6, '8089', 'Pictograph: a slab of meat with its sinew-lines inside. As a component it disguises itself as 月 (the ''meat moon'') in 体-adjacent kanji like 腹 and 脳.', 'A cut of ribs hanging in the frame, marbling drawn as two little persons — にく. 焼肉: this kanji, grilling.'),
  ('売', '売', '["sell"]'::jsonb, '{"バイ"}', '{"う.る","う.れる"}', 'N4', 2, 7, '58f2', 'Simplified from 賣: taking out (出, worn into 士) what was bought (買, reduced to the cover and legs) — goods carried out to market: to sell.', 'A salesman (士) sets up his little stand (the cover) and runs (legs) after every customer — うる. 売り切れ: run after too well — sold out.'),
  ('風', '風', '["wind","air","style","manner"]'::jsonb, '{"フウ","フ"}', '{"かぜ","かざ-"}', 'N4', 2, 9, '98a8', 'Phono-semantic: a sail-canopy (凡, phonetic フウ) over an insect (虫) — the ancients believed wind bred the insects it carried: wind.', 'A sail bellies out and a single bug rides the gust inside it — かぜ. Wind carries seeds, smells, bugs and fashions: 和風, Japanese style, is Japan riding its own breeze.'),
  ('歩', '歩', '["walk","counter for steps"]'::jsonb, '{"ホ","ブ","フ"}', '{"ある.く","あゆ.む"}', 'N4', 2, 8, '6b69', 'Compound ideograph: two footprints, one after the other (止 + a reversed foot worn into 少) — left, right: to walk.', 'Stop (止) a little (少), step, stop, step: that rhythm is walking — あるく. The 散歩 is the art of stopping slightly, beautifully.'),
  ('方', '方', '["direction","person","alternative"]'::jsonb, '{"ホウ"}', '{"かた","-かた","-がた"}', 'N4', 2, 4, '65b9', 'Origin debated — a plow, or two boats lashed side by side. It has meant ''direction, side'' since the oracle bones, and politely, ''the person over on that side''.', 'A weathervane with a crooked tail, pointing somewhere — ほう, the direction; かた, the honored person standing that way. あの方 = that way, that person.'),
  ('妹', '妹', '["younger sister"]'::jsonb, '{"マイ"}', '{"いもうと"}', 'N4', 2, 8, '59b9', 'Phono-semantic: woman (女) + 未 ''not yet'' (phonetic マイ) — the woman not yet grown: the younger sister.', 'A girl (女) with a ''not yet'' (未) pinned to her: not yet as tall as you, not yet allowed to stay up — いもうと.'),
  ('明', '明', '["bright","light"]'::jsonb, '{"メイ","ミョウ","ミン"}', '{"あ.かり","あか.るい","あか.るむ","あか.らむ","あき.らか","あ.ける","-あ.け","あ.く","あ.くる","あ.かす"}', 'N4', 2, 8, '660e', 'Compound ideograph: sun (日) and moon (月) shining together — the two lights of heaven in one character: bright, clear.', 'Sun and moon on at the same time: maximum brightness — あかるい. 明日 is the bright side of midnight: tomorrow.'),
  ('門', '門', '["gate","counter for cannons"]'::jsonb, '{"モン"}', '{"かど","と"}', 'N4', 2, 8, '9580', 'Pictograph: a double-leafed gate, both doors on their hinges. As a frame-component it hosts whatever happens at the threshold (間, 開, 聞).', 'Two saloon doors still swinging — モン. Whoever stands inside this frame in a kanji is doing something at the gate: listening (聞), opening (開), measuring the gap (間).'),
  ('夜', '夜', '["night","evening"]'::jsonb, '{"ヤ"}', '{"よ","よる"}', 'N4', 2, 8, '591c', 'Phono-semantic: a person (亻) under a cover (亠) with the moon (夕) tucked at their side — the dark hours a person spends under shelter: night.', 'Coat on the hook, someone home under the roof, the moon leaning at the window — よる. 今夜: tonight, the moon already in position.'),
  ('野', '野', '["plains","field","rustic","civilian life"]'::jsonb, '{"ヤ","ショ"}', '{"の","の-"}', 'N4', 2, 11, '91ce', 'Phono-semantic: 里 ''village and its fields'' + 予 (phonetic ヤ) — the open land beyond the last houses: plains, the wild.', 'Past the village (里) the fences stop and the grass takes over — の. 野球 is baseball: the game of the open field.'),
  ('曜', '曜', '["weekday"]'::jsonb, '{"ヨウ"}', '{}', 'N4', 2, 18, '66dc', 'Phono-semantic: sun (日) + 翟 ''pheasant with spread feathers'' (phonetic ヨウ) — the shining of the heavenly bodies, adopted to name the days of the week.', 'The sun preening its feathered wings — a different plumage every day of the week: ヨウ. 月曜日, 火曜日… seven outfits, one bird.'),
  ('用', '用', '["utilize","business","service","use","employ"]'::jsonb, '{"ヨウ"}', '{"もち.いる"}', 'N4', 2, 5, '7528', 'Pictograph of debated origin — a bucket or a section of fencing. It has meant ''use, employ, task'' since the earliest inscriptions.', 'A sturdy bucket ribbed with slats: grabbed every single day because it just works — もちいる, ヨウ. 用事 is whatever the bucket is needed for today.'),
  ('理', '理', '["logic","arrangement","reason","justice","truth"]'::jsonb, '{"リ"}', '{"ことわり"}', 'N4', 2, 11, '7406', 'Phono-semantic: jade (王) + 里 (phonetic リ) — carving jade along its natural veins: the inner pattern of things, hence reason, logic.', 'Cut the gem with its grain, never against: follow the hidden lines — リ. 料理, 理由, 無理 — cooking, reasons, and what goes against the grain.'),
  ('羽', '羽', '["feathers","counter for birds, rabbits"]'::jsonb, '{"ウ"}', '{"は","わ","はね"}', 'N3', 2, 6, '7fbd', 'Pictograph: a pair of wings, each with its barbs — feathers; the counter for birds and rabbits.', 'Two wings folded side by side — はね. Rabbits get counted with it too: monks once declared them ''birds'' to eat them.'),
  ('雲', '雲', '["cloud"]'::jsonb, '{"ウン"}', '{"くも","-ぐも"}', 'N3', 2, 12, '96f2', '云 alone was the original cloud pictograph — curling vapor; the rain crown (雨) was added once 云 got borrowed for ''to say''.', 'Vapor curling up (云) until the sky''s ceiling (雨) catches it — くも. A cloud is rain still making up its mind.'),
  ('園', '園', '["park","garden","yard","farm"]'::jsonb, '{"エン"}', '{"その"}', 'N3', 2, 13, '5712', 'Phono-semantic: walls (囗) + 袁 (phonetic エン) — a walled pleasure-ground: garden, park.', 'Trailing robes strolling inside the walls: the palace garden — その, エン. 公園 opened those walls to everyone; 動物園 filled them with animals.'),
  ('黄', '黄', '["yellow"]'::jsonb, '{"コウ","オウ"}', '{"き","こ-"}', 'N3', 2, 11, '9ec4', 'Origin debated — most read the old form as a person wearing a great jade pendant at the belt; it has meant ''yellow'' since the oracle bones.', 'A courtier weighed down by an amber pendant, glowing at the waist — きいろ. Yellow is the color of worn treasure.'),
  ('科', '科', '["department","course","section"]'::jsonb, '{"カ"}', '{}', 'N3', 2, 9, '79d1', 'Compound ideograph: grain (禾) sorted with the measuring ladle (斗) — grading into kinds: category, department, branch of study.', 'Scoop the harvest into bins: this grade here, that grade there — カ. 科学 sorts the world; 歯科 is the tooth bin.'),
  ('絵', '絵', '["picture","drawing","painting","sketch"]'::jsonb, '{"カイ","エ"}', '{}', 'N3', 2, 12, '7d75', 'Simplified from 繪: threads (糸) brought together (会) — colored silks meeting in embroidery: a picture.', 'Where the colored threads all meet (会), an image appears — え. Before paint, pictures were sewn.'),
  ('角', '角', '["angle","corner","square","horn","antlers"]'::jsonb, '{"カク"}', '{"かど","つの"}', 'N3', 2, 7, '89d2', 'Pictograph: an animal horn with its striations — a horn; hence anything that juts: angle, corner.', 'A striped horn planted point-up — つの; turn at it and it''s the かど, the street corner; measure it and it''s カク, the angle.'),
  ('活', '活', '["lively","resuscitation","being helped","living"]'::jsonb, '{"カツ"}', '{"い.きる","い.かす","い.ける"}', 'N3', 2, 9, '6d3b', 'Phono-semantic: water (氵) + a phonetic written 舌 — water rushing and gurgling: alive, vigorous.', 'A stream chattering like a tongue (舌): that sound is aliveness — カツ. 生活 is your daily portion of it.'),
  ('丸', '丸', '["round","full (month)","perfection","-ship","pills","make round","roll up","curl up","seduce","explain away"]'::jsonb, '{"ガン"}', '{"まる","まる.める","まる.い"}', 'N3', 2, 3, '4e38', 'Pictograph: a person curled into a ball mid-tumble — round, whole.', 'Knees to chin, rolling downhill — まる. Ships and castle keeps take it as a name-ending: the 〜丸, snug and complete.'),
  ('岩', '岩', '["boulder","rock","cliff"]'::jsonb, '{"ガン"}', '{"いわ"}', 'N3', 2, 8, '5ca9', 'Compound ideograph: mountain (山) + stone (石) — mountain-sized stone: a boulder, bedrock.', 'A stone with a whole mountain stacked on top — いわ. Not a pebble: the kind climbers rope onto.'),
  ('記', '記', '["scribe","account","narrative"]'::jsonb, '{"キ"}', '{"しる.す"}', 'N3', 2, 10, '8a18', 'Phono-semantic: words (言) + 己 (phonetic キ) — words set down so the self won''t forget: to record.', 'Write it down (言) for your future self (己) — キ. 日記 is that deal kept nightly; the 記者 keeps it for everyone.'),
  ('形', '形', '["shape","form","style"]'::jsonb, '{"ケイ","ギョウ"}', '{"かた","-がた","かたち","なり"}', 'N3', 2, 7, '5f62', 'Phono-semantic: 开 ''frame'' (phonetic ケイ) + 彡 ''strokes of shading'' — the outline plus its rendering: shape, form.', 'First the frame, then three quick shading strokes: the form appears — かたち. Every 人形 (doll) is born this way.'),
  ('原', '原', '["meadow","original","primitive","field","plain","prairie","tundra","wilderness"]'::jsonb, '{"ゲン"}', '{"はら"}', 'N3', 2, 10, '539f', 'Compound ideograph: a spring (泉) welling at the foot of a cliff (厂) — the source; and the open land it waters: plain, meadow; hence ''original''.', 'Where the water first leaves the rock: the source — はら, the open field it feeds; ゲン, the origin of things (原因).'),
  ('戸', '戸', '["door","counter for houses","door radical (no. 63)"]'::jsonb, '{"コ"}', '{"と"}', 'N3', 2, 4, '6238', 'Pictograph: a single door leaf on its hinge — half of the double gate 門: the household door, and the counter for households.', 'One door leaf, slightly ajar — と. A 門 is for the city; a 戸 is for your house. 江戸: the door of the bay.'),
  ('交', '交', '["mingle","mixing","association","coming & going"]'::jsonb, '{"コウ"}', '{"まじ.わる","まじ.える","ま.じる","まじ.る","ま.ざる","ま.ぜる","-か.う","か.わす","かわ.す","こもごも"}', 'N3', 2, 6, '4ea4', 'Pictograph: a person standing with legs crossed — crossing, exchanging, mingling.', 'Legs crossed mid-dance-step: paths crossing everywhere — まじわる. 交通 is a whole city doing it at once.'),
  ('公', '公', '["public","prince","official","governmental"]'::jsonb, '{"コウ","ク"}', '{"おおやけ"}', 'N3', 2, 4, '516c', 'Compound ideograph, by the classic account: to divide (八) away the private (厶) — what belongs to no one alone: public.', 'Split open the private pocket and share it out: public property — コウ. The 公園 is the garden nobody owns and everybody has.'),
  ('才', '才', '["genius","years old","cubic shaku"]'::jsonb, '{"サイ"}', '{}', 'N3', 2, 3, '624d', 'Pictograph read as a new sprout breaking the ground — raw, inborn capacity: talent; borrowed in Japanese as the everyday counter for age.', 'One shoot up before the field is even plowed: born gifted — サイ. Age borrowed the character: 十才, ten years grown.'),
  ('細', '細', '["dainty","get thin","taper","slender","narrow","detailed","precise"]'::jsonb, '{"サイ"}', '{"ほそ.い","ほそ.る","こま.か","こま.かい"}', 'N3', 2, 11, '7d30', 'Phono-semantic: thread (糸) + a right side originally the fontanelle 囟 (later written 田) — thread fine as a baby''s hair: thin, detailed.', 'Thread split until it''s almost thought — ほそい. 細かい is that fineness applied to details (and to people who mind them).'),
  ('算', '算', '["calculate","divining","number","abacus","probability"]'::jsonb, '{"サン"}', '{"そろ"}', 'N3', 2, 14, '7b97', 'Compound ideograph: hands (廾) working bamboo counting-rods (竹) on the board — to calculate.', 'Bamboo rods clicking between busy hands: ancient spreadsheet — サン. 計算 still means moving the rods, just faster.'),
  ('寺', '寺', '["Buddhist temple"]'::jsonb, '{"ジ"}', '{"てら"}', 'N3', 2, 6, '5bfa', 'Originally ''to hold, administer'' (a foot + a hand): a government office; when Buddhism arrived, the office that housed foreign monks became the temple.', 'The old administration building handed over to the monks — てら. It still administrates: bells, time, and half the kanji it appears in (時, 待, 持).'),
  ('数', '数', '["number","strength","fate","law","figures"]'::jsonb, '{"スウ","ス","サク","ソク","シュ"}', '{"かず","かぞ.える","しばしば","せ.める","わずらわ.しい"}', 'N3', 2, 13, '6570', 'Simplified from 數: a hand with a stick (攵) tallying off a bundled phonetic — to count; a number.', 'Tap, tap, tap — the stick counts the sacks of rice — かず, スウ. 数学 is the tapping turned into a science.'),
  ('星', '星', '["star","spot","dot","mark"]'::jsonb, '{"セイ","ショウ"}', '{"ほし","-ぼし"}', 'N3', 2, 9, '661f', 'Phono-semantic: sun (日) + 生 (phonetic セイ) — lights born (生) of the same fire as the sun, scattered small: stars.', 'Baby suns sprouting (生) across the night field — ほし. Each star is the sun''s seedling.'),
  ('晴', '晴', '["clear up"]'::jsonb, '{"セイ"}', '{"は.れる","は.れ","は.れ-","-ば.れ","は.らす"}', 'N3', 2, 12, '6674', 'Phono-semantic: sun (日) + 青 ''blue'' (phonetic セイ) — the sun in a blue sky: clear weather.', 'Sun plus blue: the forecast you wanted — はれ. 晴れ is the sky wearing its best kanji.'),
  ('雪', '雪', '["snow"]'::jsonb, '{"セツ"}', '{"ゆき"}', 'N3', 2, 11, '96ea', 'Compound ideograph: rain (雨) + a hand with a broom (彗 reduced to ヨ) — the one precipitation you have to sweep: snow.', 'Rain you shovel — ゆき. The broom under the rain-crown is the whole story of a northern winter.'),
  ('線', '線', '["line","track"]'::jsonb, '{"セン"}', '{"すじ"}', 'N3', 2, 15, '7dda', 'Phono-semantic: thread (糸) + 泉 ''spring'' (phonetic セン) — a thread flowing continuous as spring-water: a line.', 'Water from the spring pulled into a thread that never breaks — セン. Train lines (山手線), phone lines, pencil lines: all this thread.'),
  ('船', '船', '["ship","boat"]'::jsonb, '{"セン"}', '{"ふね","ふな-"}', 'N3', 2, 11, '8239', 'Phono-semantic: boat (舟) + 㕣 (phonetic セン) — the full-sized vessel: a ship.', 'The little boat (舟) that grew a cabin and a cargo hold — ふね. 風船 is its airborne cousin: a balloon, ship of wind.'),
  ('組', '組', '["association","braid","plait","construct","assemble","unite","cooperate","grapple"]'::jsonb, '{"ソ"}', '{"く.む","くみ","-ぐみ"}', 'N3', 2, 11, '7d44', 'Phono-semantic: thread (糸) + 且 (phonetic ソ) — cords braided together: to assemble; the group so woven.', 'Strands braided into one rope: the team — くみ. 組み立てる is braiding parts into a machine; a 番組 braids minutes into a show.'),
  ('谷', '谷', '["valley"]'::jsonb, '{"コク"}', '{"たに","きわ.まる"}', 'N3', 2, 7, '8c37', 'Pictograph: slopes parting above a mouth-like opening — the cleft where water exits the mountains: a valley.', 'Two ridges peel apart and the land opens its mouth — たに. 渋谷: the valley that got a scramble crossing.'),
  ('直', '直', '["straightaway","honesty","frankness","fix","repair"]'::jsonb, '{"チョク","ジキ","ジカ"}', '{"ただ.ちに","なお.す","-なお.す","なお.る","なお.き","す.ぐ"}', 'N3', 2, 8, '76f4', 'Compound ideograph: ten (十) eyes (目) inspecting even the hidden corner (乚) — nothing crooked survives: straight, honest; to set straight.', 'Ten eyes check the corner and the line comes out true — なおす, to fix; ただちに, straight away. Honesty is just geometry with witnesses.'),
  ('点', '点', '["spot","point","mark","speck","decimal point"]'::jsonb, '{"テン"}', '{"つ.ける","つ.く","た.てる","さ.す","とぼ.す","とも.す","ぼち"}', 'N3', 2, 9, '70b9', 'Simplified from 點 ''black mark'': 占 (phonetic テン) over fire (灬) — a burn-black dot: a point, a mark, a score.', 'The fortune-teller (占) drops sparks (灬) — each scorch mark one point — テン. Tests are scored in little burns: 百点!'),
  ('当', '当', '["hit","right","appropriate","himself"]'::jsonb, '{"トウ"}', '{"あ.たる","あ.たり","あ.てる","あ.て","まさ.に","まさ.にべし"}', 'N3', 2, 6, '5f53', 'Simplified from 當: 尚 (phonetic トウ) over 田 — fields matched in value: fitting exactly; hence to hit the mark, to be right.', 'The dart lands dead on — あたる. 当たり! for the winning ticket; 本当 for the statement that hits reality square.'),
  ('内', '内', '["inside","within","between","among","house","home"]'::jsonb, '{"ナイ","ダイ"}', '{"うち"}', 'N3', 2, 4, '5185', 'Compound ideograph: entering (入) under a cover (冂) — what is within: inside.', 'Step in under the tent flap: now you''re in-house — うち. 家内, 案内, 内緒: family, guidance, secrets — all indoor matters.'),
  ('馬', '馬', '["horse"]'::jsonb, '{"バ"}', '{"うま","うま-","ま"}', 'N3', 2, 10, '99ac', 'Pictograph: a horse — arched neck with mane (the top strokes) and four galloping legs flattened into dots (灬).', 'Mane flying, four hooves drumming into dots — うま. Stations (駅) and tests (験) still carry this horse inside them.'),
  ('麦', '麦', '["barley","wheat"]'::jsonb, '{"バク"}', '{"むぎ"}', 'N3', 2, 7, '9ea6', 'Simplified from 麥: the wheat plant (來) with a foot (夂) below — grain trodden into the winter field: barley, wheat.', 'Stamp the seed in and let winter do the rest — むぎ. Beer, udon and bread all start at this footprint.'),
  ('番', '番', '["turn","number in a series"]'::jsonb, '{"バン"}', '{"つが.い"}', 'N3', 2, 12, '756a', 'Compound ideograph: an animal''s paw-print (釆) crossing a field (田) — tracks in sequence: one''s turn, a number in a series.', 'Prints across the paddy, one after another: whose turn is it? — バン. 一番 is the first footprint; 電話番号 a whole trail of them.'),
  ('米', '米', '["rice","USA","metre"]'::jsonb, '{"ベイ","マイ","メエトル"}', '{"こめ","よね"}', 'N3', 2, 6, '7c73', 'Pictograph: rice grains spreading from the ear of the plant. Also abbreviates アメリカ (米国) by old phonetic convention.', 'Six grains bursting off the stalk — こめ. One kanji feeds a continent and names another: 米国, the rice-character country that grows wheat.'),
  ('鳴', '鳴', '["chirp","cry","bark","sound","ring","echo","honk"]'::jsonb, '{"メイ"}', '{"な.く","な.る","な.らす"}', 'N3', 2, 14, '9cf4', 'Compound ideograph: mouth (口) + bird (鳥) — the bird''s voice: to cry, chirp; of things, to ring and sound.', 'Give the bird its mouth back and the morning starts — なく. Phones, bells and stomachs all 鳴る: everything chirps in Japanese.'),
  ('毛', '毛', '["fur","hair","feather","down"]'::jsonb, '{"モウ"}', '{"け"}', 'N3', 2, 4, '6bdb', 'Pictograph: a tuft of hair curling at the tip — fur, hair, down.', 'One curling hair, magnified — け. 毛布 is a blanket of it; the 髪の毛 on your head is this kanji by the hundred thousand.'),
  ('汽', '汽', '["vapor","steam"]'::jsonb, '{"キ"}', '{}', 'N2', 2, 7, '6c7d', 'Phono-semantic: water (氵) + 气 ''breath'' (phonetic キ) — water become breath: steam.', 'Water exhaling — キ. 汽車: the train that ran on sighs.'),
  ('弓', '弓', '["bow","bow (archery, violin)"]'::jsonb, '{"キュウ"}', '{"ゆみ"}', 'N2', 2, 3, '5f13', 'Pictograph: an unstrung bow in profile.', 'The curve waiting for its string — ゆみ. It arms 引, 強, 弱 across the dictionary.'),
  ('刀', '刀', '["sword","saber","knife"]'::jsonb, '{"トウ"}', '{"かたな","そり"}', 'N2', 2, 2, '5200', 'Pictograph: a single-edged blade with its curved back. As a right-side component it sharpens into 刂.', 'The katana''s silhouette in two strokes — かたな. 日本刀: the pictograph, forged.'),
  ('矢', '矢', '["dart","arrow"]'::jsonb, '{"シ"}', '{"や"}', 'N2', 2, 5, '77e2', 'Pictograph: an arrow — head at the top, fletching below.', 'Nocked and ready — や. Inside 知 it''s the answer in flight.'),
  ('里', '里', '["ri","village","parent''s home","league"]'::jsonb, '{"リ"}', '{"さと"}', 'N2', 2, 7, '91cc', 'Compound ideograph: fields (田) on tilled earth (土) — a settlement and the old league measuring the walk between them.', 'Field plus soil equals home village — さと. ふるさと的距離: measured in 里.'),
  ('安', '安', '["relax","cheap","low","quiet","rested","contented","peaceful"]'::jsonb, '{"アン"}', '{"やす.い","やす.まる","やす","やす.らか"}', 'N5', 3, 6, '5b89', 'Compound ideograph: a woman (女) at rest under a roof (宀) — peace, safety, ease. ''Cheap'' grew later from ''easy on the purse''.', 'Home at last, under her own roof, she finally relaxes — やすい. And relax your wallet too: this shop is 安い, reassuringly cheap.'),
  ('飲', '飲', '["drink","smoke","take"]'::jsonb, '{"イン","オン"}', '{"の.む","-の.み"}', 'N5', 3, 12, '98f2', 'Compound: the food vessel (飠) + 欠, a person with mouth stretched wide open — head tipped back, pouring it down: to drink.', 'Head thrown back (欠) over the covered jar (飠): glug, glug — のむ. 飲み物 is anything that disappears that way.'),
  ('駅', '駅', '["station"]'::jsonb, '{"エキ"}', '{}', 'N5', 3, 14, '99c5', 'Simplified from 驛: horse (馬) + a phonetic (originally 睪, trimmed to 尺). The relay post of the imperial roads, where riders changed horses — reborn as the railway station.', 'Where travelers once measured out (尺) a fresh horse (馬), they now measure out a train — えき. Same spot on the map, two thousand years apart: 駅前 is still the busiest corner in town.'),
  ('悪', '悪', '["bad","vice","rascal","evil","wrong"]'::jsonb, '{"アク","オ"}', '{"わる.い","わる-","あ.し","にく.い","-にく.い","ああ","いずくに","いずくんぞ","にく.む"}', 'N4', 3, 11, '60aa', 'Phono-semantic: 亜 — the cramped floor-plan of an ancient tomb chamber (phonetic ア) — + heart (心): a heart twisted into a cramped shape: bad, evil.', 'A heart squeezed into a tomb-shaped box until it warps — わるい. Villains aren''t born; their 心 just ran out of floor space.'),
  ('暗', '暗', '["darkness","disappear","shade","informal","grow dark","be blinded"]'::jsonb, '{"アン"}', '{"くら.い","くら.む","くれ.る"}', 'N4', 3, 13, '6697', 'Phono-semantic: sun (日) + 音 (phonetic アン) — the sun muffled like a sound behind a wall: dark, dim; also ''by heart'' (in the dark, without looking).', 'The lights go out and the sun becomes a sound you can only hear — くらい. 暗記: learning in the dark, eyes closed.'),
  ('意', '意', '["idea","mind","heart","taste","thought","desire","care","liking"]'::jsonb, '{"イ"}', '{}', 'N4', 3, 13, '610f', 'Compound ideograph: the sound (音) of the heart (心) — what the heart is saying before the mouth does: intention, meaning, idea.', 'Put a stethoscope to the chest: the heart is humming a plan — イ. 意味 is the meaning; 注意 is turning the volume up on it.'),
  ('医', '医', '["doctor","medicine"]'::jsonb, '{"イ"}', '{"い.やす","い.する","くすし"}', 'N4', 3, 7, '533b', 'Simplified from 醫: an arrow (矢) in a surgeon''s box (匚) — the healer who pulls arrowheads from wounds: doctor.', 'Open the doctor''s case: inside, the arrow he just removed — イ. The 医者 keeps every arrow life fires at you.'),
  ('員', '員', '["employee","member","number","the one in charge"]'::jsonb, '{"イン"}', '{}', 'N4', 3, 10, '54e1', 'Originally the round mouth (口) of a bronze tripod vessel (貝-shaped below) — ''round'' was borrowed long ago for counting people: member, personnel.', 'A mouth to feed sitting on the payroll money (貝): one head counted — イン. 店員, 会社員, 駅員: wherever there''s a counter, there''s an 員 behind it.'),
  ('院', '院', '["Inst.","institution","temple","mansion","school"]'::jsonb, '{"イン"}', '{}', 'N4', 3, 10, '9662', 'Phono-semantic: wall/mound (阝) + 完 ''complete'' (phonetic イン) — a compound completely enclosed by walls: an institution.', 'Walls (阝) all the way around until the enclosure is complete (完): hospital, temple, academy — イン. 病院: the walled place you''d rather visit than inhabit.'),
  ('運', '運', '["carry","luck","destiny","fate","lot","transport","progress","advance"]'::jsonb, '{"ウン"}', '{"はこ.ぶ"}', 'N4', 3, 12, '904b', 'Phono-semantic: movement (辶) + 軍 ''army'' (phonetic ウン) — army wagons rolling supplies down the road: to transport; and the fortune that rolls with the convoy.', 'The supply wagons roll: whatever they bring you is your luck — はこぶ, ウン. 運転 is keeping your own wagon on the road; 運がいい is when the road is kind.'),
  ('屋', '屋', '["roof","house","shop","dealer","seller"]'::jsonb, '{"オク"}', '{"や"}', 'N4', 3, 9, '5c4b', 'Compound: a low covering (尸) over 至 ''arrive'' — the shelter you arrive under: roof, house; in Japanese, the shop and its keeper (〜屋).', 'Duck under the low roof: you''ve arrived at the shop — や. 本屋, パン屋, 花屋 — every trade gets its own little roof.'),
  ('界', '界', '["world","boundary"]'::jsonb, '{"カイ"}', '{}', 'N4', 3, 9, '754c', 'Phono-semantic: field (田) + 介 ''between'' (phonetic カイ) — the dividing ridges between fields: boundaries, and the bounded whole they define — the world.', 'Stand on the ridge between two paddies: every world is fields plus fences — カイ. 世界: all the fields, all the fences, seen at once.'),
  ('開', '開', '["open","unfold","unseal"]'::jsonb, '{"カイ"}', '{"ひら.く","ひら.き","-びら.き","ひら.ける","あ.く","あ.ける"}', 'N4', 3, 12, '958b', 'Compound ideograph: two hands (开) lifting the bar from inside the gate (門) — to open.', 'Both hands on the crossbar, lift, and the gate swings — あける, ひらく. The elevator button says 開: hands off the bar, doors open.'),
  ('寒', '寒', '["cold"]'::jsonb, '{"カン"}', '{"さむ.い"}', 'N4', 3, 12, '5bd2', 'Compound ideograph: a person packed in straw under a roof, ice (冫) at the bottom — winter insulation, ancient style: cold.', 'Stuffed under the blankets, hay in the walls, and still two icicles at your feet — さむい. Cold enough that even the kanji is bundled up.'),
  ('漢', '漢', '["Sino-","China"]'::jsonb, '{"カン"}', '{}', 'N4', 3, 13, '6f22', 'Phono-semantic: water (氵) + a phonetic — the Han River, which named the Han dynasty, which named the Chinese script itself: 漢字.', 'A river (氵) so important a dynasty took its name, and the dynasty named the characters — カン. Every 漢字 you learn flows out of that one river.'),
  ('館', '館', '["building","mansion","large building","palace"]'::jsonb, '{"カン"}', '{"やかた","たて"}', 'N4', 3, 16, '9928', 'Phono-semantic: food (飠) + 官 ''official'' (phonetic カン) — the official guesthouse where envoys were fed: a grand building, a hall.', 'The building big enough to feed officials — カン. Libraries (図書館), cinemas (映画館), embassies (大使館): if it has marble floors, it ends in 館.'),
  ('起', '起', '["rouse","wake up","get up"]'::jsonb, '{"キ"}', '{"お.きる","お.こる","お.こす","おこ.す","た.つ"}', 'N4', 3, 10, '8d77', 'Phono-semantic: run (走) + 己 ''self'' (phonetic キ) — the self getting up and breaking into a run: to rise, to wake, to start.', 'The alarm rings and your self (己) launches into a sprint (走) — おきる. Every day 起きる is the first race you win or lose.'),
  ('急', '急', '["hurry","emergency","sudden","steep"]'::jsonb, '{"キュウ"}', '{"いそ.ぐ","いそ.ぎ","せ.く"}', 'N4', 3, 9, '6025', 'Compound: a hand reaching to catch someone ahead (an old form of 及) over a heart (心) — the heart straining to catch up: hurry, urgent.', 'Your hand grabs for the closing train door and your heart slams — いそぐ. 急行: the train for hearts in exactly that state.'),
  ('究', '究', '["research","study"]'::jsonb, '{"キュウ","ク"}', '{"きわ.める"}', 'N4', 3, 7, '7a76', 'Phono-semantic: hole (穴) + 九 (phonetic キュウ) — probing a cave to its very last turn: to investigate exhaustively.', 'Crawl into the cave (穴) nine (九) turns deep, to the very end — キュウ. 研究 is refusing to stop at turn eight.'),
  ('去', '去', '["gone","past","quit","leave","elapse","eliminate","divorce"]'::jsonb, '{"キョ","コ"}', '{"さ.る","-さ.る"}', 'N4', 3, 5, '53bb', 'Compound ideograph: a figure striding away from a hollow or dwelling (厶) — departed: gone; of time, the past.', 'Footsteps walking away from the empty nest — さる. 去年 is the year that walked off and isn''t coming back.'),
  ('業', '業', '["business","vocation","arts","performance"]'::jsonb, '{"ギョウ","ゴウ"}', '{"わざ"}', 'N4', 3, 13, '696d', 'Pictograph: a notched wooden rack for hanging bells and drums — the equipment of one''s craft: work, trade, vocation (and karma, in the temples).', 'Your tools hung on the rack in their notches: that rack is your trade — ギョウ. 卒業 is the day you hang them up at school for the last time.'),
  ('銀', '銀', '["silver"]'::jsonb, '{"ギン"}', '{"しろがね"}', 'N4', 3, 14, '9280', 'Phono-semantic: metal (金) + 艮 (phonetic ギン) — the metal that stands second to gold: silver.', 'Gold''s quieter sibling, same mine, one shade paler — ギン. Banks (銀行) are where silver goes to work; the Ginza is where it goes to shop.'),
  ('区', '区', '["ward","district"]'::jsonb, '{"ク","オウ","コウ"}', '{}', 'N4', 3, 4, '533a', 'Simplified from 區: a box (匚) crowded with mouths/households (品, reduced to メ) — a district full of homes: a ward.', 'One drawer of the city''s filing cabinet, an X marking your neighborhood — ク. 渋谷区, 新宿区: Tokyo is a cabinet of 23 drawers.'),
  ('軽', '軽', '["lightly","trifling","unimportant"]'::jsonb, '{"ケイ","キョウ","キン"}', '{"かる.い","かろ.やか","かろ.んじる"}', 'N4', 3, 12, '8efd', 'Phono-semantic: cart (車) + 圣 (simplified 巠, phonetic ケイ) — a cart light enough to fly down the road: lightweight.', 'A cart loaded with nothing but thread: the horse barely notices — かるい. 軽自動車: the modern featherweight cart.'),
  ('研', '研', '["polish","study of","sharpen"]'::jsonb, '{"ケン"}', '{"と.ぐ"}', 'N4', 3, 9, '7814', 'Compound: stone (石) + 开 ''made level/even'' — grinding on a stone until flat and sharp: to polish; figuratively, to grind at a subject.', 'Blade on the whetstone, back and forth until it gleams level — と(ぐ). 研究: polishing a question until it cuts.'),
  ('県', '県', '["prefecture"]'::jsonb, '{"ケン"}', '{"か.ける"}', 'N4', 3, 9, '770c', 'Simplified from 縣, which grimly showed a head hung upside-down by a cord — the original sense was ''to suspend'' (ancestor of 懸); borrowed for the administrative district ''suspended'' from the capital.', 'A watchful eye (目) hanging from the capital by a thread: local government — ケン. All 43 県 dangle from Tokyo on the same string.'),
  ('仕', '仕', '["attend","doing","official","serve"]'::jsonb, '{"シ","ジ"}', '{"つか.える"}', 'N4', 3, 5, '4ed5', 'Phono-semantic: person (亻) + 士 ''gentleman-retainer'' (phonetic シ) — a person in service to a lord: to serve, to work.', 'A person standing at the gentleman''s side, ready — つかえる. 仕事 is the modern lord: service, five days a week.'),
  ('使', '使', '["use","send on a mission","order","messenger","envoy","ambassador","cause"]'::jsonb, '{"シ"}', '{"つか.う","つか.い","-つか.い","-づか.い"}', 'N4', 3, 8, '4f7f', 'Compound: person (亻) + 吏 ''official'' — a person dispatched on official business: an envoy; to employ, to use.', 'The boss points: you, go — you''ve been used, err, dispatched — つかう. The 大使 is the grandest errand-runner of all: the ambassador.'),
  ('始', '始', '["commence","begin"]'::jsonb, '{"シ"}', '{"はじ.める","-はじ.める","はじ.まる"}', 'N4', 3, 8, '59cb', 'Phono-semantic: woman (女) + 台 (phonetic シ) — the ancients located every beginning in the mother: to begin.', 'Every story starts the same way: a woman (女) on the stage (台) — はじめる. 始めまして: ''we are at the beginning'', the first greeting.'),
  ('死', '死', '["death","die"]'::jsonb, '{"シ"}', '{"し.ぬ","し.に-"}', 'N4', 3, 6, '6b7b', 'Compound ideograph: bare bones (歹) with a person kneeling beside them (匕) — the mourner at the remains: death.', 'Someone kneels by what is left — しぬ. The number four (シ) shares its sound, which is why hospitals skip the 4th floor.'),
  ('事', '事', '["matter","thing","fact","business","reason","possibly"]'::jsonb, '{"ジ","ズ"}', '{"こと","つか.う","つか.える"}', 'N4', 3, 8, '4e8b', 'Pictograph: a hand gripping a writing tablet or flagged pole — official business being recorded: an affair, a matter, the abstract ''thing''.', 'A clerk''s hand skewering paperwork on a spike — こと. Intangible things only: 仕事 the work-thing, 食事 the meal-thing, 大事 the thing that matters.'),
  ('持', '持', '["hold","have"]'::jsonb, '{"ジ"}', '{"も.つ","-も.ち","も.てる"}', 'N4', 3, 9, '6301', 'Phono-semantic: hand (扌) + 寺 ''temple'' (phonetic ジ) — the hand that grips and keeps: to hold, to possess.', 'Hold it the way a temple holds its relics: firmly, forever — もつ. 気持ち is what your heart is currently holding.'),
  ('写', '写', '["copy","be photographed","describe"]'::jsonb, '{"シャ","ジャ"}', '{"うつ.す","うつ.る","うつ-","うつ.し"}', 'N4', 3, 5, '5199', 'Simplified from 寫, originally ''to transfer things into a house'' — transferring an image onto paper: to copy, to photograph.', 'Slip the sheet under the cover (冖) and trace what shows through (与) — うつす. 写真: reality, transferred and ''true''.'),
  ('者', '者', '["someone","person"]'::jsonb, '{"シャ"}', '{"もの"}', 'N4', 3, 8, '8005', 'Originally a picture of firewood boiling something (the root of 煮), borrowed since antiquity for ''the one who…'' — the all-purpose person suffix.', 'An old-timer (耂) telling stories in the sun (日): ''the one who…'' — もの, シャ. 医者, 学者, 記者 — name the deed and 者 names the doer.'),
  ('主', '主', '["lord","chief","master","main thing","principal"]'::jsonb, '{"シュ","ス","シュウ"}', '{"ぬし","おも","あるじ"}', 'N4', 3, 5, '4e3b', 'Pictograph: an oil lamp with its flame (the dot) — the master of the house keeps the lamp burning: lord, chief, main.', 'One flame on the lampstand and the whole household orbits it — ぬし, シュ. The 主人 is whoever tends the flame; the 主 idea is the one lit brightest.'),
  ('終', '終', '["end","finish"]'::jsonb, '{"シュウ"}', '{"お.わる","-お.わる","おわ.る","お.える","つい","つい.に"}', 'N4', 3, 11, '7d42', 'Phono-semantic: thread (糸) + 冬 ''winter'' (phonetic シュウ) — the year''s thread wound up at winter: to end.', 'Wind the last of the thread as the first ice forms: done — おわる. 終電: the day''s thread runs out at the station.'),
  ('習', '習', '["learn"]'::jsonb, '{"シュウ","ジュ"}', '{"なら.う","なら.い"}', 'N4', 3, 11, '7fd2', 'Compound ideograph: young wings (羽) over 白 (originally the sun/self) — a fledgling flapping day after day until flight comes: to learn by repetition.', 'Little wings beating over the nest every single morning — ならう. 練習, 復習: learning is just flapping, counted in days.'),
  ('集', '集', '["gather","meet","congregate","swarm","flock"]'::jsonb, '{"シュウ"}', '{"あつ.まる","あつ.める","つど.う"}', 'N4', 3, 12, '96c6', 'Compound ideograph: a bird (隹) on a tree (木) — the old form had three birds: a flock settling at dusk: to gather.', 'One tree, and every bird in the valley lands on it at sunset — あつまる. 集合! and the flock assembles.'),
  ('住', '住', '["dwell","reside","live","inhabit"]'::jsonb, '{"ジュウ","ヂュウ","チュウ"}', '{"す.む","す.まう","-ず.まい"}', 'N4', 3, 7, '4f4f', 'Phono-semantic: person (亻) + 主 ''the lamp of the master'' (phonetic ジュウ) — the person beside the burning lamp: to dwell.', 'Where your lamp (主) burns, that''s where you live — すむ. 住所 is the map coordinate of your flame.'),
  ('重', '重', '["heavy","important","esteem","respect","heap up","pile up","nest of boxes","-fold"]'::jsonb, '{"ジュウ","チョウ"}', '{"え","おも.い","おも.り","おも.なう","かさ.ねる","かさ.なる","おも"}', 'N4', 3, 9, '91cd', 'Pictograph: a person bent under a heavy sack pressing toward the ground — heavy; and layers stacked one on another (かさねる).', 'The porter''s silhouette compressed by the load, stroke stacked on stroke — おもい. Heavy things pile: 重ねる; important things weigh: 大事×重 = 重要.'),
  ('所', '所', '["place","extent"]'::jsonb, '{"ショ"}', '{"ところ","-ところ","どころ","とこ"}', 'N4', 3, 8, '6240', 'Phono-semantic: door (戸) + axe (斤, phonetic ショ) — where the axe rings by the doorway: the spot, the place.', 'You can find the woodcutter''s house with your eyes closed: follow the axe sound to the door — ところ. 台所, 住所, 場所 — every ''where'' ends here.'),
  ('暑', '暑', '["sultry","hot","summer heat"]'::jsonb, '{"ショ"}', '{"あつ.い"}', 'N4', 3, 12, '6691', 'Phono-semantic: sun (日) + 者 (phonetic ショ — whose own origin is ''boiling'') — the sun boiling the air: sultry heat.', 'The sun sets the kettle of the sky to boil — あつい. August in Japan: the 者 under the 日 is you, simmering.'),
  ('乗', '乗', '["ride","power","multiplication","record","counter for vehicles","board","mount","join"]'::jsonb, '{"ジョウ","ショウ"}', '{"の.る","-の.り","の.せる"}', 'N4', 3, 9, '4e57', 'Simplified from 乘: a person standing high in a tree, feet on the branches — climbing aboard: to ride, to mount.', 'Climb the trunk, settle on the highest branch: all aboard — のる. Same move at the station every morning: 電車に乗る.'),
  ('真', '真', '["reality","Buddhist sect"]'::jsonb, '{"シン"}', '{"ま","ま-","まこと"}', 'N4', 3, 10, '771f', 'Simplified from 眞: a filled vessel set perfectly upright — full to the brim, not a drop false: genuine, true.', 'Ten (十) eyes (目) inspected it on one (一) bench: certified true — まこと, シン. 写真 is ''the true copy''; 真ん中 the true middle.'),
  ('進', '進', '["advance","proceed","progress","promote"]'::jsonb, '{"シン"}', '{"すす.む","すす.める"}', 'N4', 3, 11, '9032', 'Compound ideograph: movement (辶) + bird (隹) — birds cannot fly backward: to advance, only forward.', 'A bird on the road has one gear: forward — すすむ. When you can''t reverse, every step is 前進.'),
  ('世', '世', '["generation","world","society","public"]'::jsonb, '{"セイ","セ","ソウ"}', '{"よ"}', 'N4', 3, 5, '4e16', 'Ideograph: three tens (十) joined at the base — thirty years: the span of one generation; then the world that generation inhabits.', 'Thirty years welded into one bracket: your allotted lap — よ, セ. 世界 is all the laps being run at once; お世話 is helping someone through theirs.'),
  ('送', '送', '["escort","send"]'::jsonb, '{"ソウ"}', '{"おく.る"}', 'N4', 3, 9, '9001', 'Phono-semantic: movement (辶) + a phonetic showing hands lifting an offering — walking a gift or a guest on their way: to send, to see off.', 'Carry the parcel down the road with both hands until the road takes over — おくる. 見送り is when it''s a person, and you wave until the train is gone.'),
  ('族', '族', '["tribe","family"]'::jsonb, '{"ゾク"}', '{}', 'N4', 3, 11, '65cf', 'Compound ideograph: a banner with an arrow beneath it — the clan mustered under its standard, arrows ready: tribe, family line.', 'One flag, everyone''s arrows stacked beneath it: that''s a family — ゾク. 家族: the tribe whose banner hangs at your door.'),
  ('待', '待', '["wait","depend on"]'::jsonb, '{"タイ"}', '{"ま.つ","-ま.ち"}', 'N4', 3, 9, '5f85', 'Phono-semantic: step (彳) + 寺 ''temple'' (phonetic タイ) — pacing back and forth before the temple where you were told to be: to wait.', 'Little steps in front of the temple gate, checking the road again — まつ. ちょっと待って: two more paces, they''ll come.'),
  ('代', '代', '["substitute","change","convert","replace","period","age","counter for decades of ages, eras, etc.","generation","charge","rate","fee"]'::jsonb, '{"ダイ","タイ"}', '{"か.わる","かわ.る","かわ.り","か.わり","-がわ.り","-が.わり","か.える","よ","しろ"}', 'N4', 3, 5, '4ee3', 'Phono-semantic: person (亻) + 弋 ''stake, tally'' (phonetic ダイ) — one person staked in for another: substitute; the tally of reigns: era; the tally of payment: fee.', 'Plant a stake where you stood and someone takes your shift — かわる. Eras substitute for eras (時代), coins for goods (電気代): the same swap, three sizes.'),
  ('題', '題', '["topic","subject"]'::jsonb, '{"ダイ"}', '{}', 'N4', 3, 18, '984c', 'Phono-semantic: 是 (phonetic ダイ) + 頁 ''head'' — what stands at the head of a text: its title, its topic.', 'The heading at the top of the page, big letters, first thing your head meets — ダイ. 宿題 is the topic that follows you home; 問題 the one that fights back.'),
  ('短', '短', '["short","brevity","fault","defect","weak point"]'::jsonb, '{"タン"}', '{"みじか.い"}', 'N4', 3, 12, '77ed', 'Compound: arrow (矢) + 豆 ''stemmed vessel'' — the ancients measured small lengths against arrows and cups: short.', 'Measured against a single arrow, it doesn''t even reach the cup: short — みじかい. 短い夏: a summer one arrow long.'),
  ('着', '着', '["don","arrive","wear","counter for suits of clothing"]'::jsonb, '{"チャク","ジャク"}', '{"き.る","き.せる","つ.く","つ.ける"}', 'N4', 3, 12, '7740', 'Variant of 著 ''to attach'': clothing attached to the body — to wear; a traveler attached to the destination — to arrive.', 'Pull the wool sweater down past your eye (目): it''s on — きる. The same ''sticking'' gets the train to the platform: 到着.'),
  ('注', '注', '["pour","irrigate","shed (tears)","flow into","concentrate on","notes","comment","annotate"]'::jsonb, '{"チュウ"}', '{"そそ.ぐ","さ.す","つ.ぐ"}', 'N4', 3, 8, '6ce8', 'Phono-semantic: water (氵) + 主 (phonetic チュウ) — water poured in a steady stream; attention poured onto a point.', 'The master (主) tips the jug and the water threads down in one line — そそぐ. 注意: pour your mind the same way, without splashing.'),
  ('転', '転', '["revolve","turn around","change"]'::jsonb, '{"テン"}', '{"ころ.がる","ころ.げる","ころ.がす","ころ.ぶ","まろ.ぶ","うたた","うつ.る","くる.めく"}', 'N4', 3, 11, '8ee2', 'Phono-semantic (simplified from 轉): cart (車) + 云 (from the phonetic 專) — wheels going around: to revolve, roll, tumble.', 'Cartwheels spinning till the spokes blur into clouds (云) — ころぶ, テン. 運転 is keeping the spin on the road; 自転車 is the spin you pedal.'),
  ('都', '都', '["metropolis","capital","all","everything"]'::jsonb, '{"ト","ツ"}', '{"みやこ"}', 'N4', 3, 11, '90fd', 'Phono-semantic: 者 (phonetic ト) + city wall (阝) — the city of cities, seat of the court: the metropolis. 東京都 wears it today.', 'Everyone (者) plus walls: the city everybody moved to — みやこ, ト. 都合 is metropolitan scheduling: ''when the big city of my life allows''.'),
  ('度', '度', '["degrees","occurrence","time","counter for occurrences","consider","attitude"]'::jsonb, '{"ド","ト","タク"}', '{"たび","-た.い"}', 'N4', 3, 9, '5ea6', 'Compound: under a roof (广), a hand (又) measuring in spans — a unit of measure: degree, and each ''take'' of an action: once, twice.', 'A hand ticking off spans on the workshop wall: one notch, one degree, one time — ド. 今度 is ''this next notch''; 温度 the notches of heat.'),
  ('動', '動', '["move","motion","change","confusion","shift","shake"]'::jsonb, '{"ドウ"}', '{"うご.く","うご.かす"}', 'N4', 3, 11, '52d5', 'Phono-semantic: 重 ''heavy'' (phonetic ドウ) + 力 ''strength'' — muscle set against a heavy load until it shifts: to move.', 'Put strength (力) against the heaviest sack (重) and it finally budges — うごく. 動物 are ''the moving things''; 自動 is the sack moving itself.'),
  ('発', '発', '["departure","discharge","publish","emit","start from","disclose","counter for gunshots"]'::jsonb, '{"ハツ","ホツ"}', '{"た.つ","あば.く","おこ.る","つか.わす","はな.つ"}', 'N4', 3, 9, '767a', 'Simplified from 發: feet planted apart (癶) and a bow releasing — the arrow leaves: to discharge, depart, emit.', 'Stance set, string loosed: whatever it was, it''s launched — ハツ. Trains 出発, ideas 発明, words 発音 — all arrows off this one bow.'),
  ('病', '病', '["ill","sick"]'::jsonb, '{"ビョウ","ヘイ"}', '{"や.む","-や.み","やまい"}', 'N4', 3, 10, '75c5', 'Phono-semantic: the sickbed radical (疒 — a person laid on a slanted cot) + 丙 (phonetic ビョウ/ヘイ): laid up: illness.', 'Flat on the tilted cot with a C-grade (丙) fever chart — びょうき. Everything under the 疒 roof is some way of feeling awful; 病院 is where the cots line up.'),
  ('品', '品', '["goods","refinement","dignity","article","counter for meal courses"]'::jsonb, '{"ヒン","ホン"}', '{"しな"}', 'N4', 3, 9, '54c1', 'Compound ideograph: three boxes/mouths stacked — wares piled for inspection; many mouths judging them gives ''quality, refinement''.', 'Three crates stacked in the shop window — しな. 品物 are the crates; 上品 is how neatly they''re stacked.'),
  ('服', '服', '["clothing","admit","obey","discharge"]'::jsonb, '{"フク"}', '{}', 'N4', 3, 8, '670d', 'Originally ''to make submit / to attach to one''s service'' (a hand pressing a kneeling figure); clothing is what attaches to the body — dress, and ''a dose'' of tea or medicine.', 'The body (月) fitted into its uniform until it behaves — フク. 洋服, 制服: cloth that tells the flesh who''s in charge today.'),
  ('物', '物', '["thing","object","matter"]'::jsonb, '{"ブツ","モツ"}', '{"もの","もの-"}', 'N4', 3, 8, '7269', 'Phono-semantic: ox (牛) + 勿 ''streamers of many colors'' (phonetic ブツ/モツ) — oxen of every color: things of every kind, the physical ''thing''.', 'A cow walking through fluttering ribbons: cargo of every color — もの. 買い物, 食べ物, 飲み物: name the verb, 物 makes it stuff.'),
  ('勉', '勉', '["exertion","endeavour","encourage","strive","make effort","diligent"]'::jsonb, '{"ベン"}', '{"つと.める"}', 'N4', 3, 10, '52c9', 'Phono-semantic: 免 (phonetic ベン; originally a birth — the ultimate strain) + 力 ''strength'' — straining with everything one has: exertion.', 'Pushing with all your strength toward the escape hatch (免) — ベン. 勉強 is exactly that feeling, applied to a textbook.'),
  ('味', '味', '["flavor","taste"]'::jsonb, '{"ミ"}', '{"あじ","あじ.わう"}', 'N4', 3, 8, '5473', 'Phono-semantic: mouth (口) + 未 ''not yet'' (phonetic ミ) — what the mouth knows before words do: taste, flavor.', 'The tongue meets something it can''t name yet (未): pure flavor — あじ. 意味 is the same tasting done by the mind: meaning.'),
  ('問', '問', '["question","ask","problem"]'::jsonb, '{"モン"}', '{"と.う","と.い","とん"}', 'N4', 3, 11, '554f', 'Phono-semantic: gate (門, phonetic モン) + mouth (口) — a mouth at the gate, calling in: to ask, to inquire.', 'Knock-knock at the gate: ''Anyone home?'' — とう. Every 問題 starts as a mouth at a closed door.'),
  ('薬', '薬', '["medicine","chemical","enamel","gunpowder","benefit"]'::jsonb, '{"ヤク"}', '{"くすり"}', 'N4', 3, 16, '85ac', 'Phono-semantic: plants (艹) + 楽 ''comfort, ease'' (phonetic ヤク) — the herb that restores ease: medicine.', 'The plant (艹) that puts the music (楽) back in you — くすり. The 薬局 shelves are rows of bottled comfort.'),
  ('有', '有', '["possess","have","exist","happen","occur","approx"]'::jsonb, '{"ユウ","ウ"}', '{"あ.る"}', 'N4', 3, 6, '6709', 'Compound ideograph: a hand (𠂇) holding meat (月) — having something in hand: to possess, to exist.', 'A fist closed around tonight''s dinner: ownership at its most primal — ある, ユウ. 有名: possessed of a name everyone holds.'),
  ('洋', '洋', '["ocean","sea","foreign","Western style"]'::jsonb, '{"ヨウ"}', '{}', 'N4', 3, 9, '6d0b', 'Phono-semantic: water (氵) + 羊 ''sheep'' (phonetic ヨウ) — waters vast as drifting flocks: the open ocean; and what came across it: the West.', 'Whitecaps like a million sheep grazing to the horizon — ヨウ. Cross that flock and you reach 洋服, 洋食, 洋楽: the sheep-water world.'),
  ('旅', '旅', '["trip","travel"]'::jsonb, '{"リョ"}', '{"たび"}', 'N4', 3, 10, '65c5', 'Compound ideograph: a banner with people marching beneath it — originally a military column of five hundred; the column on the move became the journey.', 'Pack behind the flag and start walking — たび. 旅行 keeps the ancient column alive: everyone still follows the tour guide''s little banner.'),
  ('委', '委', '["committee","entrust to","leave to","devote","discard"]'::jsonb, '{"イ"}', '{"ゆだ.ねる"}', 'N3', 3, 8, '59d4', 'Compound ideograph: grain (禾) bending supple over a woman (女) — to bend to another''s will: to entrust, delegate.', 'Hand your harvest over and let someone else carry it — イ. A 委員会 is a room of people holding everyone else''s grain.'),
  ('育', '育', '["bring up","grow up","raise","rear"]'::jsonb, '{"イク"}', '{"そだ.つ","そだ.ち","そだ.てる","はぐく.む"}', 'N3', 3, 8, '80b2', 'Compound ideograph: a child head-down at birth (𠫓) over flesh (月) — the newborn fed and grown: to raise, to be raised.', 'From the first upside-down cry, feeding flesh onto tiny bones — そだてる. 教育 raises the mind the same way.'),
  ('泳', '泳', '["swim"]'::jsonb, '{"エイ"}', '{"およ.ぐ"}', 'N3', 3, 8, '6cf3', 'Phono-semantic: water (氵) + 永 ''long, eternal'' (phonetic エイ) — long strokes drawn through water: to swim.', 'Stretch each stroke as long as forever (永) — およぐ. 水泳: eternity practiced in a 25-meter pool.'),
  ('央', '央', '["center","middle"]'::jsonb, '{"オウ"}', '{}', 'N3', 3, 5, '592e', 'Pictograph: a person framed squarely inside a carrying-yoke — pinned at the exact middle: center.', 'Shoulders in the yoke, dead center by definition — オウ. 中央: the middle of the middle.'),
  ('横', '横', '["sideways","side","horizontal","width","woof","unreasonable","perverse"]'::jsonb, '{"オウ"}', '{"よこ"}', 'N3', 3, 15, '6a2a', 'Phono-semantic: wood (木) + 黄 (phonetic オウ) — the crossbar laid sideways across the gate: horizontal, side.', 'The yellow beam bolted crosswise on the frame — よこ. 横浜: the shore that runs sideways along the bay.'),
  ('温', '温', '["warm"]'::jsonb, '{"オン"}', '{"あたた.か","あたた.かい","あたた.まる","あたた.める","ぬく"}', 'N3', 3, 12, '6e29', 'Phono-semantic: water (氵) + 昷 (phonetic オン — read as a covered dish of warm food given kindly) — warmth, in water and in character.', 'A covered bowl of soup floated to someone who needs it — あたたかい. 温泉: the earth doing the same favor with a whole spring.'),
  ('化', '化', '["change","take the form of","influence","enchant","delude","-ization"]'::jsonb, '{"カ","ケ"}', '{"ば.ける","ば.かす","ふ.ける","け.する"}', 'N3', 3, 4, '5316', 'Compound ideograph: a person upright (亻) beside a person inverted (匕) — one being flipped into another state: transformation.', 'Same person, before and after the flip — ばける, カ. 文化 transforms people; 化学 transforms matter; 花 is 化 happening to a plant.'),
  ('荷', '荷', '["baggage","shoulder-pole load","bear (a burden)","shoulder (a gun)","load","cargo","freight"]'::jsonb, '{"カ"}', '{"に"}', 'N3', 3, 10, '8377', 'Phono-semantic: plants (艹) + 何 (phonetic カ — itself originally ''to shoulder a load'') — the bundle on the shoulder-pole: baggage; also the lotus.', 'Stalks bound and slung on the pole 何 once pictured — に. 荷物: everything your shoulders answer for.'),
  ('階', '階', '["storey","stair","counter for storeys of a building"]'::jsonb, '{"カイ"}', '{"きざはし"}', 'N3', 3, 12, '968e', 'Phono-semantic: mound (阝) + 皆 ''all'' (phonetic カイ) — steps cut up the slope, one for everyone: stairs; a building''s floors.', 'Everybody (皆) climbing the terraced hill one step at a time — カイ. 二階, 三階: the hill moved indoors.'),
  ('感', '感', '["emotion","feeling","sensation"]'::jsonb, '{"カン"}', '{}', 'N3', 3, 13, '611f', 'Phono-semantic: 咸 ''all, entire'' (phonetic カン) + heart (心) — the heart moved entirely: feeling, sensation.', 'Not one corner of the heart left dry: total impact — カン. 感じる is when the whole 心 rings at once.'),
  ('岸', '岸', '["beach"]'::jsonb, '{"ガン"}', '{"きし"}', 'N3', 3, 8, '5cb8', 'Phono-semantic: mountain (山) and cliff (厂) + 干 (phonetic ガン) — where high ground breaks off at the water: the shore.', 'Mountain, then cliff, then the drying line (干) where waves give up — きし. The land''s last three strokes before the sea.'),
  ('期', '期', '["period","time","date","term"]'::jsonb, '{"キ","ゴ"}', '{}', 'N3', 3, 12, '671f', 'Phono-semantic: 其 (phonetic キ) + moon (月) — time measured by the moon''s fixed rounds: a set period, a term.', 'Mark the calendar by moons: this basket of days is one term — キ. 学期, 期間, 期待: hopes with a due date.'),
  ('客', '客', '["guest","visitor","customer","client"]'::jsonb, '{"キャク","カク"}', '{}', 'N3', 3, 9, '5ba2', 'Phono-semantic: roof (宀) + 各 ''arrive'' (phonetic キャク) — the one who arrives under your roof: guest, customer.', 'Footsteps arriving (各) under your roof: set another place — キャク. お客さん: the arrival you bow to.'),
  ('球', '球', '["ball","sphere"]'::jsonb, '{"キュウ"}', '{"たま"}', 'N3', 3, 11, '7403', 'Phono-semantic: jade (王) + 求 (phonetic キュウ) — jade ground into a perfect sphere: a ball, a globe.', 'Polish the gem until it rolls — たま, キュウ. 野球 sends it flying; 地球 is the one we stand on.'),
  ('級', '級', '["class","rank","grade"]'::jsonb, '{"キュウ"}', '{}', 'N3', 3, 9, '7d1a', 'Phono-semantic: thread (糸) + 及 ''reach up to'' (phonetic キュウ) — threads graded length by length: rank, class.', 'Silk sorted by how far each strand reaches — キュウ. 上級, 初級: how far up the thread you''ve climbed.'),
  ('橋', '橋', '["bridge"]'::jsonb, '{"キョウ"}', '{"はし"}', 'N3', 3, 16, '6a4b', 'Phono-semantic: wood (木) + 喬 ''tall, arching'' (phonetic キョウ) — timber arched high over the water: a bridge.', 'Wood bent into a high arc so boats pass under — はし. 日本橋: kilometer zero is a bridge.'),
  ('局', '局', '["bureau","board","office","affair","conclusion","court lady","lady-in-waiting","her apartment"]'::jsonb, '{"キョク"}', '{"つぼね"}', 'N3', 3, 7, '5c40', 'Compound: a body bent (尸) into a cramped compartment — a partitioned room; hence the office, the bureau, and a ''board'' situation (結局).', 'A clerk folded into a cubicle — キョク. 郵便局, 薬局: wherever there''s a counter and a queue, there''s a 局.'),
  ('曲', '曲', '["bend","music","melody","composition","pleasure","injustice","fault","curve","crooked","perverse","lean"]'::jsonb, '{"キョク"}', '{"ま.がる","ま.げる","くま"}', 'N3', 3, 6, '66f2', 'Pictograph: a bent piece of basketwork or a carpenter''s curved ruler — a bend; a melody is a line that bends.', 'A basket seen edge-on, ribs curving — まがる. Music borrowed it: a 曲 is sound refusing to go straight.'),
  ('苦', '苦', '["suffering","trial","worry","hardship","feel bitter","scowl"]'::jsonb, '{"ク"}', '{"くる.しい","-ぐる.しい","くる.しむ","くる.しめる","にが.い","にが.る"}', 'N3', 3, 8, '82e6', 'Phono-semantic: plants (艹) + 古 (phonetic ク) — the bitter old herb: bitterness; hence hardship, suffering.', 'Chew the ancient weed and wince — にがい, くるしい. 苦労: life''s aftertaste, prescribed daily.'),
  ('具', '具', '["tool","utensil","means","possess","ingredients","counter for armor, suits, sets of furniture"]'::jsonb, '{"グ"}', '{"そな.える","つぶさ.に"}', 'N3', 3, 8, '5177', 'Compound ideograph: two hands offering up a vessel — implements presented ready for use: tool, equipment.', 'Both hands holding up the kit, ready to work — グ. 道具 for the craftsman, 家具 for the home, 具 in your soup: the stuff involved.'),
  ('君', '君', '["mister","you","ruler","male name suffix"]'::jsonb, '{"クン"}', '{"きみ","-ぎみ"}', 'N3', 3, 7, '541b', 'Compound ideograph: a hand holding the staff of office (尹) + mouth (口) — the one whose word commands: lord; softened into the familiar ''you'' and the name-suffix 〜君.', 'Staff in hand, giving orders — きみ. Time demoted the lord into a schoolboy: 田中君, our young ruler of the classroom.'),
  ('係', '係', '["person in charge","connection","duty","concern oneself"]'::jsonb, '{"ケイ"}', '{"かか.る","かかり","-がかり","かか.わる"}', 'N3', 3, 9, '4fc2', 'Compound: person (亻) + 系 ''thread of connection'' — the person tied by a thread to a duty: the one in charge.', 'A thread runs from the task to someone''s wrist — かかり. Follow it and you find the 係の人, the person it''s tied to.'),
  ('決', '決', '["decide","fix","agree upon","appoint"]'::jsonb, '{"ケツ"}', '{"き.める","-ぎ.め","き.まる","さ.く"}', 'N3', 3, 7, '6c7a', 'Phono-semantic: water (氵) + 夬 ''breach'' (phonetic ケツ) — the dike cut and the water committed to one channel: to decide.', 'Break the dam: the water can never un-choose its path — きめる. 決して: ''never'', said with the dike already cut.'),
  ('血', '血', '["blood"]'::jsonb, '{"ケツ"}', '{"ち"}', 'N3', 3, 6, '8840', 'Compound ideograph: a drop falling into the ritual dish (皿) — sacrificial blood in the bowl: blood.', 'One dark drop over the bowl — ち. The dish under it makes it ceremony; the kanji never forgot the altar.'),
  ('庫', '庫', '["warehouse","storehouse"]'::jsonb, '{"コ","ク"}', '{"くら"}', 'N3', 3, 10, '5eab', 'Compound ideograph: carts (車) parked under a roof (广) — the arsenal and storehouse: warehouse.', 'Wagons rolled in under one long roof — コ. 冷蔵庫: the household''s coldest garage.'),
  ('湖', '湖', '["lake"]'::jsonb, '{"コ"}', '{"みずうみ"}', 'N3', 3, 12, '6e56', 'Phono-semantic: water (氵) + 胡 (phonetic コ) — the great still water: a lake.', 'Water so wide the far shore is a rumor — みずうみ. 琵琶湖: the lake shaped like a lute.'),
  ('向', '向', '["yonder","facing","beyond","confront","defy","tend toward","approach"]'::jsonb, '{"コウ"}', '{"む.く","む.い","-む.き","む.ける","-む.け","む.かう","む.かい","む.こう","む.こう-","むこ","むか.い"}', 'N3', 3, 6, '5411', 'Pictograph: a house wall with its one window — the direction the window faces: to face, toward, yonder.', 'The house looks wherever its window does — むかう. 向こう is what the window sees: over there.'),
  ('幸', '幸', '["happiness","blessing","fortune"]'::jsonb, '{"コウ"}', '{"さいわ.い","さち","しあわ.せ"}', 'N3', 3, 8, '5e78', 'Pictograph of manacles — and the luck of escaping them: good fortune. Happiness, in the oldest script, is the shackle you were spared.', 'The handcuffs that didn''t close on you — しあわせ. 幸せ has always meant: it could have gone otherwise, and didn''t.'),
  ('港', '港', '["harbor"]'::jsonb, '{"コウ"}', '{"みなと"}', 'N3', 3, 12, '6e2f', 'Phono-semantic: water (氵) + 巷 ''lanes of a town'' (phonetic コウ) — streets of water where ships park: a harbor.', 'The town''s alleys continue straight into the sea, boats instead of carts — みなと. 空港: the same alleys, drawn in sky.'),
  ('号', '号', '["nickname","number","item","title","pseudonym","name","call"]'::jsonb, '{"ゴウ"}', '{"さけ.ぶ","よびな"}', 'N3', 3, 5, '53f7', 'Simplified from 號: a mouth (口) with breath bending out (丂) — a cry, a call; hence a name called out, a numbered designation.', 'A shout with a hook on it: ''Number 5!'' — ゴウ. Trains, typhoons and magazine issues all answer to their 号.'),
  ('根', '根', '["root","radical","head (pimple)"]'::jsonb, '{"コン"}', '{"ね","-ね"}', 'N3', 3, 10, '6839', 'Phono-semantic: tree (木) + 艮 ''fixed, unyielding'' (phonetic コン) — the part of the tree that refuses to move: the root.', 'Pull all you want: the stubborn (艮) part of the tree wins — ね. 大根: the vegetable that is entirely root and pride.'),
  ('祭', '祭', '["ritual","offer prayers","celebrate","deify","enshrine","worship"]'::jsonb, '{"サイ"}', '{"まつ.る","まつ.り","まつり"}', 'N3', 3, 11, '796d', 'Compound ideograph: a hand (又) laying meat (月) on the altar (示) — the offering rite: festival.', 'The offering placed, the drums start — まつり. Every 祭 in Japan is this kanji with lanterns on.'),
  ('坂', '坂', '["slope","incline","hill"]'::jsonb, '{"ハン"}', '{"さか"}', 'N3', 3, 7, '5742', 'Phono-semantic: earth (土) + 反 (phonetic ハン) — ground tilted against you: a slope.', 'The ground pushes back (反) at every step: uphill — さか. 大阪: the big slope that became a big city.'),
  ('皿', '皿', '["dish","a helping","plate"]'::jsonb, '{"ベイ"}', '{"さら"}', 'N3', 3, 5, '76bf', 'Pictograph: a shallow dish on its stand, seen from the side — plate, and counter for helpings.', 'A serving plate drawn in cross-section, food-side up — さら. At the sushi bar you are billed by the stack of 皿.'),
  ('指', '指', '["finger","point to","indicate","put into","play (chess)","measure (ruler)"]'::jsonb, '{"シ"}', '{"ゆび","さ.す","-さ.し"}', 'N3', 3, 9, '6307', 'Phono-semantic: hand (扌) + 旨 (phonetic シ) — the hand''s pointers: fingers; to point, to indicate.', 'The part of the hand that knows what it wants (旨) — ゆび. 指す points, 指輪 rings it, 指定 pins the seat.'),
  ('歯', '歯', '["tooth","cog"]'::jsonb, '{"シ"}', '{"よわい","は","よわ.い","よわい.する"}', 'N3', 3, 12, '6b6f', 'Phono-semantic (simplified from 齒): 止 (phonetic シ) over a pictograph of teeth in an open mouth — tooth.', 'Open wide: rice grains of enamel in their box — は. The 歯医者 is the only person paid to look in there.'),
  ('次', '次', '["next","order","sequence"]'::jsonb, '{"ジ","シ"}', '{"つ.ぐ","つぎ"}', 'N3', 3, 6, '6b21', 'Compound: two (二→冫) + a person pausing open-mouthed (欠) — the second stop, the one after: next.', 'Catch your breath, then the second leg — つぎ. 次の駅: the station your yawn arrives at.'),
  ('式', '式', '["style","ceremony","rite","function","method","system","form","expression"]'::jsonb, '{"シキ"}', '{}', 'N3', 3, 6, '5f0f', 'Phono-semantic: 弋 ''marker stake'' + 工 ''work'' (phonetic シキ) — work done to the staked-out pattern: the set form, a ceremony, a formula.', 'Stakes out, string taut, everyone follows the pattern — シキ. Weddings (結婚式) and equations (数式) run on the same rails.'),
  ('実', '実', '["reality","truth","seed","fruit","nut"]'::jsonb, '{"ジツ","シツ"}', '{"み","みの.る","まこと","みの","みち.る"}', 'N3', 3, 8, '5b9f', 'Simplified from 實: a house (宀) strung full of coins (貫) — a filled house: substance; the plant''s substance is its fruit; the fact''s substance is reality.', 'The house is actually full — み, the fruit; ジツ, the fact. 実は…: ''here''s what''s really in the house.'''),
  ('取', '取', '["take","fetch","take up"]'::jsonb, '{"シュ"}', '{"と.る","と.り","と.り-","とり","-ど.り"}', 'N3', 3, 8, '53d6', 'Compound ideograph: an ear (耳) in a hand (又) — warriors took the ears of the fallen as proof: to take, grimly literal.', 'A hand closes on an ear and doesn''t let go — とる. Modern life softened it to 取る a photo, 受け取る a parcel.'),
  ('守', '守', '["guard","protect","defend","obey"]'::jsonb, '{"シュ","ス"}', '{"まも.る","まも.り","もり","-もり","かみ"}', 'N3', 3, 6, '5b88', 'Compound ideograph: a hand (寸) under the roof (宀) — the hand that keeps the house: to guard, to keep (a promise).', 'One hand on the door, all night — まもる. お守り: the shrine sells you that hand, folded in brocade.'),
  ('酒', '酒', '["sake","alcohol"]'::jsonb, '{"シュ"}', '{"さけ","さか-"}', 'N3', 3, 10, '9152', 'Compound: liquid (氵) + the wine jar (酉, a pictograph of the fermenting vessel) — the jar''s liquid: alcohol.', 'What the ancient jar (酉) sweats out — さけ. 居酒屋: the room built around that jar.'),
  ('受', '受', '["accept","undergo","answer (phone)","take","get","catch","receive"]'::jsonb, '{"ジュ"}', '{"う.ける","-う.け","う.かる"}', 'N3', 3, 8, '53d7', 'Compound ideograph: one hand (爫) passing a tray (冖) to another hand (又) — the handover: to receive, accept.', 'Two hands, one tray, mid-air — うける. 受験 is holding your tray out to an exam board.'),
  ('州', '州', '["state","province"]'::jsonb, '{"シュウ","ス"}', '{"す"}', 'N3', 3, 6, '5dde', 'Pictograph: the river (川) with sandbar islets (the dots) — settled sandbanks became districts: province, state.', 'Three islands anchored in the current — シュウ. 九州: nine of them, grown into a region; アメリカの州: fifty.'),
  ('拾', '拾', '["pick up","gather","find","go on foot","ten"]'::jsonb, '{"シュウ","ジュウ"}', '{"ひろ.う"}', 'N3', 3, 9, '62fe', 'Phono-semantic: hand (扌) + 合 ''fit'' (phonetic シュウ) — the hand closing on what it finds: to pick up. Also the formal legal ''ten''.', 'Hand meets object, perfect fit: yours now — ひろう. On contracts it moonlights as an unforgeable 十.'),
  ('宿', '宿', '["inn","lodging","relay station","dwell","lodge","be pregnant","home","dwelling"]'::jsonb, '{"シュク"}', '{"やど","やど.る","やど.す"}', 'N3', 3, 11, '5bbf', 'Compound ideograph: a person (亻) on a mat (百-shaped bedding) under a roof (宀) — a traveler bedded down: lodging, an inn.', 'One roof, one stranger, one rented futon — やど. 新宿: the ''new inn'' that became three million beds; 宿題 the homework you lodge overnight.'),
  ('助', '助', '["help","rescue","assist"]'::jsonb, '{"ジョ"}', '{"たす.ける","たす.かる","す.ける","すけ"}', 'N3', 3, 7, '52a9', 'Phono-semantic: 且 (phonetic ジョ) + strength (力) — strength added from the side: to help.', 'Your load, plus someone else''s muscle sliding under it — たすける. 助けて! calls for exactly one more 力.'),
  ('勝', '勝', '["victory","win","prevail","excel"]'::jsonb, '{"ショウ"}', '{"か.つ","-が.ち","まさ.る","すぐ.れる","かつ"}', 'N3', 3, 12, '52dd', 'Phono-semantic: a phonetic (朕) + strength (力) — strength that lifts and prevails: to win.', 'Muscle under the load until it rises: victory — かつ. 勝負 pairs this kanji with its shadow, defeat.'),
  ('商', '商', '["make a deal","selling","dealing in","merchant"]'::jsonb, '{"ショウ"}', '{"あきな.う"}', 'N3', 3, 11, '5546', 'Originally the emblem of the Shang (商) people — after their kingdom fell, they wandered as traders, and their name became the word for commerce.', 'A whole fallen dynasty setting up market stalls — ショウ. 商売: history''s plan B, still in business.'),
  ('消', '消', '["extinguish","blow out","turn off","neutralize","cancel"]'::jsonb, '{"ショウ"}', '{"き.える","け.す"}', 'N3', 3, 10, '6d88', 'Phono-semantic: water (氵) + 肖 ''shrink, resemble-less'' (phonetic ショウ) — doused down to nothing: to extinguish, erase, vanish.', 'Water on the flame until nothing is left to resemble it — けす. 消しゴム erases pencil; 消える erases anything.'),
  ('章', '章', '["badge","chapter","composition","poem","design"]'::jsonb, '{"ショウ"}', '{}', 'N3', 3, 11, '7ae0', 'Originally a tattooing needle making its mark — a distinguishing sign: a badge; in texts, the marked-off unit: a chapter.', 'The stamp pressed at the end of a section: this part is sealed — ショウ. Chapters and medals are the same thing: marks that say ''unit complete''.'),
  ('植', '植', '["plant"]'::jsonb, '{"ショク"}', '{"う.える","う.わる"}', 'N3', 3, 12, '690d', 'Phono-semantic: tree (木) + 直 ''straight'' (phonetic ショク) — setting a sapling in straight: to plant.', 'Hold the sapling plumb-straight (直) while the soil goes in — うえる. 植物: everything that got planted and stayed.'),
  ('深', '深', '["deep","heighten","intensify","strengthen"]'::jsonb, '{"シン"}', '{"ふか.い","-ぶか.い","ふか.まる","ふか.める","み-"}', 'N3', 3, 11, '6df1', 'Phono-semantic: water (氵) + 罙 ''reach far in'' (phonetic シン) — water you can reach into without touching bottom: deep.', 'Arm in to the shoulder and still no floor — ふかい. Deep water, deep night (深夜), deep thoughts: same missing bottom.'),
  ('申', '申', '["have the honor to","sign of the monkey","3-5PM","ninth sign of Chinese zodiac"]'::jsonb, '{"シン"}', '{"もう.す","もう.し-","さる"}', 'N3', 3, 5, '7533', 'Pictograph: forked lightning stretching down — the gods declaring themselves; hence to state (humbly, 申す), and the zodiac monkey by borrowing.', 'Lightning speaks first, you answer politely — もうす. 申します: introducing yourself under a sky that outranks you.'),
  ('神', '神', '["gods","mind","soul"]'::jsonb, '{"シン","ジン"}', '{"かみ","かん-","こう-"}', 'N3', 3, 9, '795e', 'Phono-semantic: altar (示/ネ) + 申 ''lightning'' (phonetic シン) — the power addressed at the altar, announced in lightning: the gods.', 'Where lightning meets the altar — かみ. 神社 is the address; 神様 the resident.'),
  ('身', '身', '["somebody","person","one''s station in life"]'::jsonb, '{"シン"}', '{"み"}', 'N3', 3, 7, '8eab', 'Pictograph: a torso in profile with a full belly — originally a pregnant body: the living body, one''s person.', 'A silhouette carrying life in its belly — み. 身体 is the body; 中身 the body of anything — what''s carried inside.'),
  ('整', '整', '["organize","arranging","tune","tone","meter","key (music)"]'::jsonb, '{"セイ"}', '{"ととの.える","ととの.う"}', 'N3', 3, 16, '6574', 'Compound: a bundle (束) tapped by a hand (攵) until correct (正) — knocked into order: to arrange, adjust.', 'Tap the stack square on the desk until every edge is 正 — ととのえる. 整理: the satisfying thunk of order.'),
  ('昔', '昔', '["once upon a time","antiquity","old times"]'::jsonb, '{"セキ","シャク"}', '{"むかし"}', 'N3', 3, 8, '6614', 'Compound ideograph: layers (廿) piled over days (日) — days heaped on days: long ago, antiquity.', 'Day pressed on day like sediment — むかし. Every folktale drills into the same stratum: 昔々, once upon a time.'),
  ('全', '全', '["whole","entire","all","complete","fulfill"]'::jsonb, '{"ゼン"}', '{"まった.く","すべ.て"}', 'N3', 3, 6, '5168', 'Compound ideograph: flawless jade (王) kept under cover (𠆢) — intact, untouched: whole, complete.', 'The gem still in its case, not a scratch — ゼン. 全部, 全然, 安全: wholeness, in stock, on sale, and kept safe.'),
  ('想', '想', '["idea","thought","conception","think"]'::jsonb, '{"ソウ","ソ"}', '{"おも.う"}', 'N3', 3, 13, '60f3', 'Phono-semantic: 相 ''facing, mutual'' (phonetic ソウ) + heart (心) — the heart facing an image of what isn''t there: to imagine, conceive.', 'The heart holds a picture up and studies it — ソウ. 思想 is a gallery of them; 可哀想 is the picture that hurts to look at.'),
  ('相', '相', '["inter-","mutual","together","each other","minister of state","councillor","aspect","phase","physiognomy"]'::jsonb, '{"ソウ","ショウ"}', '{"あい-"}', 'N3', 3, 9, '76f8', 'Compound ideograph: an eye (目) examining a tree (木) — observer and observed facing each other: mutual, reciprocal; an aspect; a minister who ''oversees''.', 'You look at the tree; on some level the tree looks back — あい. 相手: the one on the other end of your gaze.'),
  ('息', '息', '["breath","respiration","son","interest (on money)","rest","coming to an end"]'::jsonb, '{"ソク"}', '{"いき"}', 'N3', 3, 10, '606f', 'Compound ideograph: nose (自) over heart (心) — the current running between nose and heart: breath; a son (one''s own breath continued).', 'Air rides from the nose down to the heart and back — いき. 休息 is when you finally hear it; 息子 is your breath walking around outside you.'),
  ('速', '速', '["quick","fast"]'::jsonb, '{"ソク"}', '{"はや.い","はや-","はや.める","すみ.やか"}', 'N3', 3, 10, '901f', 'Phono-semantic: movement (辶) + 束 ''tied bundle'' (phonetic ソク) — strapped tight and speeding: fast.', 'Cinch the pack down and nothing rattles: pure speed — はやい. The 高速 is where tight bundles overtake loose ones.'),
  ('他', '他', '["other","another","the others"]'::jsonb, '{"タ"}', '{"ほか"}', 'N3', 3, 5, '4ed6', 'Phono-semantic: person (亻) + 也 (phonetic タ) — some person over there, not this one: other.', 'A figure trailing off in another direction — ほか. その他: everyone and everything the sentence didn''t name.'),
  ('打', '打', '["strike","hit","knock","pound","dozen"]'::jsonb, '{"ダ","ダース"}', '{"う.つ","う.ち-","ぶ.つ"}', 'N3', 3, 5, '6253', 'Phono-semantic: hand (扌) + 丁 ''nail'' (phonetic ダ/チョウ) — the hand coming down on the nail: to strike.', 'Hammer-hand meets nail head — うつ. Baseball took it (打つ, batting), and so did your keyboard: 打ち込む.'),
  ('対', '対', '["vis-a-vis","opposite","even","equal","versus","anti-","compare"]'::jsonb, '{"タイ","ツイ"}', '{"あいて","こた.える","そろ.い","つれあ.い","なら.ぶ","むか.う"}', 'N3', 3, 7, '5bfe', 'Simplified from 對: a hand (寸) answering a rack of bells — to respond in kind, face to face: versus, vis-à-vis.', 'Two players squared up across the table — タイ. 3対2, 反対, 対する: everything that stands facing something else.'),
  ('第', '第', '["No.","residence"]'::jsonb, '{"ダイ","テイ"}', '{}', 'N3', 3, 11, '7b2c', 'Phono-semantic: bamboo (⺮) + 弟 ''birth-order'' (phonetic ダイ) — bamboo slips filed in sequence: number so-and-so.', 'The bamboo tags on a string, each with its rank — ダイ. 第一 hangs first; everything else queues behind it.'),
  ('炭', '炭', '["charcoal","coal"]'::jsonb, '{"タン"}', '{"すみ"}', 'N3', 3, 9, '70ad', 'Compound: fire (火) burning under the mountain''s cliff (山+厂) — the kiln in the hillside: charcoal, coal.', 'Fire sealed in the hill until wood turns black and light — すみ. The yakitori grill still runs on this kanji.'),
  ('談', '談', '["discuss","talk"]'::jsonb, '{"ダン"}', '{}', 'N3', 3, 15, '8ac7', 'Phono-semantic: words (言) + 炎 ''blaze'' (phonetic ダン) — talk by the fire, or talk that catches like one: discussion.', 'Words traded across a campfire, sparks included — ダン. 相談 is bringing your problem to that fire.'),
  ('柱', '柱', '["pillar","post","cylinder","support"]'::jsonb, '{"チュウ"}', '{"はしら"}', 'N3', 3, 9, '67f1', 'Phono-semantic: wood (木) + 主 ''master'' (phonetic チュウ) — the master timber the whole house hangs on: the pillar.', 'One post holds the roof the way the master holds the household — はしら. Remove it and everything above remembers why it mattered.'),
  ('調', '調', '["tune","tone","meter","key (music)","writing style","prepare","exorcise","investigate","harmonize","mediate"]'::jsonb, '{"チョウ"}', '{"しら.べる","しら.べ","ととの.う","ととの.える"}', 'N3', 3, 15, '8abf', 'Phono-semantic: words (言) + 周 ''all the way around'' (phonetic チョウ) — checking a thing from every side: to tune, adjust, investigate.', 'Walk your questions all the way around it (周) until it sounds right — しらべる. 調べる investigates; 調子 is the tuning you''re in today.'),
  ('追', '追', '["chase","drive away","follow","pursue","meanwhile"]'::jsonb, '{"ツイ"}', '{"お.う"}', 'N3', 3, 9, '8ffd', 'Compound: movement (辶) + 𠂤 ''massed troops'' — marching after a retreating column: to pursue, chase.', 'Their dust cloud is still visible — go! — おう. 追いかける: the whole kanji at a sprint.'),
  ('定', '定', '["determine","fix","establish","decide"]'::jsonb, '{"テイ","ジョウ"}', '{"さだ.める","さだ.まる","さだ.か"}', 'N3', 3, 8, '5b9a', 'Compound ideograph: things set correct (正) under the roof (宀) — settled in place: fixed, determined.', 'Everything in the house squared and bolted — さだめる, テイ. 予定, 定食: the schedule and the set meal — life pre-decided.'),
  ('庭', '庭', '["courtyard","garden","yard"]'::jsonb, '{"テイ"}', '{"にわ"}', 'N3', 3, 10, '5ead', 'Phono-semantic: building (广) + 廷 ''royal court'' (phonetic テイ) — the open ground within the walls: courtyard, garden.', 'The palace court shrunk to fit behind your house — にわ. Every 庭 keeps a little ceremony in its gravel.'),
  ('鉄', '鉄', '["iron"]'::jsonb, '{"テツ"}', '{"くろがね"}', 'N3', 3, 13, '9244', 'Simplified from 鐵: metal (金) + a phonetic now written 失 — the workhorse metal: iron.', 'The metal that loses (失) its shine and keeps its strength — てつ. 地下鉄: iron veins under the city.'),
  ('登', '登', '["ascend","climb up"]'::jsonb, '{"トウ","ト","ドウ","ショウ","チョウ"}', '{"のぼ.る","あ.がる"}', 'N3', 3, 12, '767b', 'Compound ideograph: feet set apart (癶) climbing with the offering vessel (豆) — mounting the altar steps: to ascend.', 'Step by step up the shrine stairs, bowl held level — のぼる. 登山 is the same climb with a bigger altar.'),
  ('島', '島', '["island"]'::jsonb, '{"トウ"}', '{"しま"}', 'N3', 3, 10, '5cf6', 'Compound ideograph: a bird (鳥, tail clipped) on a mountain (山) rising from the sea — where seabirds rest: an island.', 'A peak just big enough for the gulls to land — しま. Japan: one country, 14,000 of these kanji.'),
  ('投', '投', '["throw","discard","abandon","launch into","join","invest in","hurl","give up","sell at a loss"]'::jsonb, '{"トウ"}', '{"な.げる","-な.げ"}', 'N3', 3, 7, '6295', 'Compound ideograph: hand (扌) + 殳 ''lance'' — the hand hurling the weapon: to throw.', 'Wind-up, release: spear away — なげる. The pitcher (投手) does it for a living, mercifully with a ball.'),
  ('湯', '湯', '["hot water","bath","hot spring"]'::jsonb, '{"トウ"}', '{"ゆ"}', 'N3', 3, 12, '6e6f', 'Phono-semantic: water (氵) + 昜 ''sun blazing up'' (phonetic トウ) — water with the sun in it: hot water.', 'Water heated until it glows like sunrise — ゆ. The ♨ sign and the sentō curtain both spell this one kanji.'),
  ('等', '等', '["etc.","and so forth","class (first)","quality","equal","similar"]'::jsonb, '{"トウ"}', '{"ひと.しい","など","-ら"}', 'N3', 3, 12, '7b49', 'Compound: bamboo slips (⺮) sorted at the office (寺) — graded into equal ranks: equal; ''and the rest of the same grade'': etc.', 'Slips of the same length in the same box — ひとしい. 一等 is the top box; 等々 waves at all the boxes you didn''t list.'),
  ('童', '童', '["juvenile","child"]'::jsonb, '{"ドウ"}', '{"わらべ"}', 'N3', 3, 12, '7ae5', 'Grim origin: a tattooed (辛-marked) servant child; the meaning softened over centuries to simply ''child''.', 'The kanji grew up gentler than it was born: now it just means kids — わらべ, ドウ. 児童 in school, 童話 at bedtime.'),
  ('農', '農', '["agriculture","farmers"]'::jsonb, '{"ノウ"}', '{}', 'N3', 3, 13, '8fb2', 'Compound ideograph: field rows worked with the shell-hoe (辰 — a clamshell blade) — dawn labor on the land: agriculture.', 'A clamshell lashed to a stick, scraping rows before sunrise — ノウ. 農家: the people who fed everyone with a seashell.'),
  ('波', '波', '["waves","billows","Poland"]'::jsonb, '{"ハ"}', '{"なみ"}', 'N3', 3, 8, '6ce2', 'Phono-semantic: water (氵) + 皮 ''skin'' (phonetic ハ) — the sea''s moving skin: waves.', 'The ocean flexing its hide — なみ. Radio waves, heat waves, 津波: everything that travels as rolling skin.'),
  ('配', '配', '["distribute","spouse","exile","rationing"]'::jsonb, '{"ハイ"}', '{"くば.る"}', 'N3', 3, 10, '914d', 'Compound ideograph: an attendant (己) kneeling at the wine jar (酉), portioning it out — to distribute, allot; the allotted partner: spouse.', 'Cup by cup around the table, no one skipped — くばる. 心配 is your heart doing rounds it wasn''t asked to do.'),
  ('倍', '倍', '["double","twice","times","fold"]'::jsonb, '{"バイ"}', '{}', 'N3', 3, 10, '500d', 'Phono-semantic: person (亻) + 咅 (phonetic バイ) — originally to split away, and a thing split makes two: double, -fold.', 'Cut the mochi in half: now you have two — バイ. 二倍, 三倍: multiplication by cheerful cutting.'),
  ('箱', '箱', '["box","chest","case","bin","railway car"]'::jsonb, '{"ソウ"}', '{"はこ"}', 'N3', 3, 15, '7bb1', 'Phono-semantic: bamboo (⺮) + 相 (phonetic ソウ→はこ) — the woven bamboo chest: a box.', 'Bamboo strips facing each other (相) until they close into walls — はこ. 箱根: the box canyon with hot springs in it.'),
  ('畑', '畑', '["farm","field","garden","one''s specialty","(kokuji)"]'::jsonb, '{}', '{"はた","はたけ","-ばたけ"}', 'N3', 3, 9, '7551', 'A kokuji — invented in Japan: fire (火) + field (田) — land cleared by burning for dry crops (no paddy water): a farm field.', 'Burn the brush, plant the slope: the dry field — はたけ. Japan built this kanji itself, ash and all.'),
  ('反', '反', '["anti-"]'::jsonb, '{"ハン","ホン","タン","ホ"}', '{"そ.る","そ.らす","かえ.す","かえ.る","-かえ.る"}', 'N3', 3, 4, '53cd', 'Compound ideograph: a hand (又) pressed against the cliff (厂), pushing back — to turn over, oppose: anti-.', 'Palm flat on the rock face, shoving the other way — ハン. 反対 is the shove made official.'),
  ('板', '板', '["plank","board","plate","stage"]'::jsonb, '{"ハン","バン"}', '{"いた"}', 'N3', 3, 8, '677f', 'Phono-semantic: wood (木) + 反 (phonetic ハン) — wood flipped and planed flat: a board.', 'Turn the log, shave; turn, shave — until it''s a plank — いた. The 黒板 and the 掲示板 are its indoor careers.'),
  ('悲', '悲', '["grieve","sad","deplore","regret"]'::jsonb, '{"ヒ"}', '{"かな.しい","かな.しむ"}', 'N3', 3, 12, '60b2', 'Phono-semantic: 非 ''pulled apart in two directions'' (phonetic ヒ) + heart (心) — a heart split open: sorrow.', 'Two wings tearing away from each other with the heart between — かなしい. Grief is the heart''s wishbone moment.'),
  ('皮', '皮', '["pelt","skin","hide","leather","skin radical (no. 107)"]'::jsonb, '{"ヒ"}', '{"かわ"}', 'N3', 3, 5, '76ae', 'Pictograph: a hand stripping the hide from a carcass — skin, pelt, bark, peel.', 'The hand at the bottom is mid-peel — かわ. Banana skin, tree bark, dumpling wrapper: all 皮 to Japanese.'),
  ('美', '美', '["beauty","beautiful"]'::jsonb, '{"ビ","ミ"}', '{"うつく.しい"}', 'N3', 3, 9, '7f8e', 'Compound ideograph: a big (大) sheep (羊) — the fattest, finest animal brought for offering: fine, beautiful.', 'The prize sheep, groomed and gleaming, led up the aisle — うつくしい. Beauty began as the best thing you could give.'),
  ('鼻', '鼻', '["nose","snout"]'::jsonb, '{"ビ"}', '{"はな"}', 'N3', 3, 14, '9f3b', 'Phono-semantic: 自 (the original nose pictograph) + 畀 (phonetic ビ) — added when 自 drifted off to mean ''oneself'': the nose proper.', 'The old nose (自) needed scaffolding once ''self'' stole it: behold the full apparatus — はな. Biggest kanji on the face.'),
  ('筆', '筆', '["writing brush","writing","painting brush","handwriting"]'::jsonb, '{"ヒツ"}', '{"ふで"}', 'N3', 3, 12, '7b46', 'Compound ideograph: bamboo (⺮) + 聿 ''hand gripping a brush'' — the bamboo-handled writing brush.', 'Bamboo shaft, wolf-hair tip, hand steady — ふで. The 鉛筆 is its graphite grandchild.'),
  ('氷', '氷', '["icicle","ice","hail","freeze","congeal"]'::jsonb, '{"ヒョウ"}', '{"こおり","ひ","こお.る"}', 'N3', 3, 5, '6c37', 'Compound: water (水) with a single freezing drop added — water gone solid: ice.', 'Water with one extra chip in it: frozen — こおり. The shaved-ice flags of summer fly this kanji, かき氷.'),
  ('表', '表', '["surface","table","chart","diagram"]'::jsonb, '{"ヒョウ"}', '{"おもて","-おもて","あらわ.す","あらわ.れる","あら.わす"}', 'N3', 3, 8, '8868', 'Compound ideograph: a garment (衣) worn fur-side out — the outside face of things: surface, exterior; what is displayed: a chart, a table.', 'Wear the coat fur-out and everyone sees your outside — おもて, ヒョウ. 発表 is turning your inside out on purpose.'),
  ('秒', '秒', '["second (1/60 minute)"]'::jsonb, '{"ビョウ"}', '{}', 'N3', 3, 9, '79d2', 'Compound: grain (禾) + 少 ''tiny'' — originally the hair-thin awn at the grain''s tip; adopted for the thinnest slice of time: the second.', 'Time shaved as fine as the whisker on a rice grain — ビョウ. 一秒: one awn''s worth of your life.'),
  ('負', '負', '["defeat","negative","-","minus","bear","owe","assume a responsibility"]'::jsonb, '{"フ"}', '{"ま.ける","ま.かす","お.う"}', 'N3', 3, 9, '8ca0', 'Compound ideograph: a person bent over a cowrie (貝) — shouldering a debt: to bear a burden; the one who carries the loss: defeat.', 'Bowed under the moneylender''s shell — まける. To lose is to carry; 勝負 asks who walks away upright.'),
  ('部', '部', '["section","bureau","dept","class","copy","part","portion","counter for copies of a newspaper or magazine"]'::jsonb, '{"ブ"}', '{"-べ"}', 'N3', 3, 11, '90e8', 'Phono-semantic: 咅 (phonetic ブ) + city (阝) — one district of the town: a section, department; in school, the club.', 'The town carved into wards, your name on one — ブ. 全部 is all the wards at once; 部活 the ward you sweat for after class.'),
  ('福', '福', '["blessing","fortune","luck","wealth"]'::jsonb, '{"フク"}', '{}', 'N3', 3, 13, '798f', 'Phono-semantic: altar (示/ネ) + 畐 ''jar filled to the brim'' (phonetic フク) — abundance granted at the altar: blessing, good fortune.', 'The offering jar comes back from the altar full — フク. 福 is what spills over; 幸福 when it spills on you.'),
  ('平', '平', '["even","flat","peace"]'::jsonb, '{"ヘイ","ビョウ","ヒョウ"}', '{"たい.ら","たい.らげる","ひら"}', 'N3', 3, 5, '5e73', 'Pictograph read as a balance at rest — or duckweed lying flat on water: level, even, calm.', 'The scale''s beam dead level, nothing trembling — たいら, ヘイ. 平和 is that stillness scaled up to nations.'),
  ('返', '返', '["return","answer","fade","repay"]'::jsonb, '{"ヘン"}', '{"かえ.す","-かえ.す","かえ.る","-かえ.る"}', 'N3', 3, 7, '8fd4', 'Phono-semantic: movement (辶) + 反 ''flip'' (phonetic ヘン) — walking the road flipped around: to return something, to reply.', 'Same road, reversed footage — かえす. 返事 is words making the return trip.'),
  ('放', '放', '["set free","release","fire","shoot","emit","banish","liberate"]'::jsonb, '{"ホウ"}', '{"はな.す","-っぱな.し","はな.つ","はな.れる","こ.く","ほう.る"}', 'N3', 3, 8, '653e', 'Phono-semantic: 方 ''direction'' (phonetic ホウ) + 攵 ''hand with stick'' — driven off toward the horizon: to release, let go, banish.', 'A tap of the stick and it bolts for open country — はなす. 放送 releases voices into the air on purpose.'),
  ('命', '命', '["fate","command","decree","destiny","life","appoint"]'::jsonb, '{"メイ","ミョウ"}', '{"いのち"}', 'N3', 3, 8, '547d', 'Compound ideograph: an order (口) spoken from above the assembly (亼) to one kneeling (卩) — the command; and the allotted span it decrees: life, fate.', 'The decree read out while you kneel: this much time, this path — いのち. Life, in the old script, is an order you receive.'),
  ('面', '面', '["mask","face","features","surface"]'::jsonb, '{"メン","ベン"}', '{"おも","おもて","つら"}', 'N3', 3, 9, '9762', 'Pictograph: a face framed by its outline with one eye showing — the face; a mask; any facing surface or aspect.', 'An eye peering from inside the frame of a Noh mask — メン. 場面, 画面, 真面目: scenes, screens and the earnest face you keep on.'),
  ('役', '役', '["duty","war","campaign","drafted labor","office","service","role"]'::jsonb, '{"ヤク","エキ"}', '{}', 'N3', 3, 7, '5f79', 'Compound ideograph: marching (彳) with a weapon (殳) — pressed into service: duty, office; the part one is assigned: a role.', 'Shouldering the spear because your number came up — ヤク. On stage the draft is kinder: 役 is just your role.'),
  ('油', '油', '["oil","fat"]'::jsonb, '{"ユ","ユウ"}', '{"あぶら"}', 'N3', 3, 8, '6cb9', 'Phono-semantic: liquid (氵) + 由 (phonetic ユ) — the slick liquid: oil.', 'A liquid with its own agenda (由): it floats, it clings, it burns — あぶら. 醤油: the oil-like sauce that runs Japan.'),
  ('由', '由', '["wherefore","a reason"]'::jsonb, '{"ユ","ユウ","ユイ"}', '{"よし","よ.る"}', 'N3', 3, 5, '7531', 'Origin debated — a gourd putting out its sprout, or a wick rising from a lamp; since antiquity it has meant the ''whence'': cause, reason, via.', 'The sprout shows where the vine came from — ユ. 理由 is the sprout of any claim; 自由 is growing wherever you please.'),
  ('遊', '遊', '["play"]'::jsonb, '{"ユウ","ユ"}', '{"あそ.ぶ","あそ.ばす"}', 'N3', 3, 12, '904a', 'Phono-semantic: movement (辶) + 斿 ''banner streaming, child beneath'' (phonetic ユウ) — drifting like a flag on the wind: to roam, to play.', 'A kid trailing a streamer, going nowhere in particular, perfectly — あそぶ. 遊園地: the industrial complex of exactly that.'),
  ('予', '予', '["beforehand","previous","myself","I"]'::jsonb, '{"ヨ","シャ"}', '{"あらかじ.め"}', 'N3', 3, 4, '4e88', 'Pictograph read as a weaver''s shuttle handed forward — what is passed ahead of the weave: beforehand, in advance.', 'The shuttle is already through before the thread arrives — ヨ. 予定, 予約, 天気予報: tomorrow, pre-threaded.'),
  ('様', '様', '["Esq.","way","manner","situation","polite suffix"]'::jsonb, '{"ヨウ","ショウ"}', '{"さま","さん"}', 'N3', 3, 14, '69d8', 'Phono-semantic: wood (木) + a phonetic (羕, ヨウ) — the pattern of the grain: manner, appearance; extended into the honorific 〜様.', 'Every tree''s grain flows its own way: its manner — ヨウ. Address people by their grain: 田中様, treated wood-grain-up.'),
  ('葉', '葉', '["leaf","plane","lobe","needle","blade","spear","counter for flat things","fragment","piece"]'::jsonb, '{"ヨウ"}', '{"は"}', 'N3', 3, 12, '8449', 'Phono-semantic: plants (艹) + 枼 ''thin slats on a tree'' (phonetic ヨウ) — the tree''s thin green plates: leaves.', 'Generations (世) budding off the tree in flat green sheets — は. 言葉: words are the leaves the mouth puts out.'),
  ('陽', '陽', '["sunshine","yang principle","positive","male","heaven","daytime"]'::jsonb, '{"ヨウ"}', '{"ひ"}', 'N3', 3, 12, '967d', 'Phono-semantic: mound (阝) + 昜 ''sun blazing up'' (phonetic ヨウ) — the sunlit south face of the hill: sunshine, the yang principle.', 'The bright side of the slope, where snow gives up first — ヨウ. 太陽: the source of every south face.'),
  ('落', '落', '["fall","drop","come down","village","hamlet"]'::jsonb, '{"ラク"}', '{"お.ちる","お.ち","お.とす"}', 'N3', 3, 12, '843d', 'Phono-semantic: plants (艹) + 洛 (phonetic ラク) — leaves letting go one by one: to fall, drop, fail.', 'Every leaf reaches the same conclusion separately — おちる. 落ち着く is falling until you settle, calm at last.'),
  ('流', '流', '["current","a sink","flow","forfeit"]'::jsonb, '{"リュウ","ル"}', '{"なが.れる","なが.れ","なが.す","-なが.す"}', 'N3', 3, 10, '6d41', 'Compound: water (氵) + 㐬 — a newborn head-down with hair streaming — carried off by the water: current, to flow.', 'Hair streaming in the current, everything swept one way — ながれる. Styles, rumors and rivers all 流れる.'),
  ('両', '両', '["both","old Japanese coin","counter for carriages (e.g., in a train)","two"]'::jsonb, '{"リョウ"}', '{"てる","ふたつ"}', 'N3', 3, 6, '4e21', 'Simplified from 兩: a yoke or scale-beam holding two sides in balance — both; an old coin weighed on such scales.', 'One beam, two pans, matched — リョウ. 両手, 両親, 両方: hands, parents, sides — the things that come in balanced pairs.'),
  ('緑', '緑', '["green"]'::jsonb, '{"リョク","ロク"}', '{"みどり"}', 'N3', 3, 14, '7dd1', 'Phono-semantic: thread (糸) + 彔 (phonetic リョク) — silk dyed the color of young growth: green.', 'Thread pulled from the dye-vat dripping spring color — みどり. The Yamanote line runs on rails of this kanji.'),
  ('礼', '礼', '["salute","bow","ceremony","thanks","remuneration"]'::jsonb, '{"レイ","ライ"}', '{}', 'N3', 3, 5, '793c', 'Simplified from 禮: altar (示) + ritual vessel (豊) — the proper conduct of the rite: etiquette, the bow, thanks.', 'At the altar, the body folds on the little hook: the bow — レイ. お礼 is that hook offered to a person instead of a god.'),
  ('列', '列', '["file","row","rank","tier","column"]'::jsonb, '{"レツ","レ"}', '{}', 'N3', 3, 6, '5217', 'Compound ideograph: bones (歹) laid out in order by the blade (刂) — things arranged in sequence: a row, a file.', 'The surgeon''s tray: everything in its grim, tidy line — レツ. 行列 is the human version: the queue.'),
  ('練', '練', '["practice","gloss","train","drill","polish","refine"]'::jsonb, '{"レン"}', '{"ね.る","ね.り"}', 'N3', 3, 14, '7df4', 'Phono-semantic: thread (糸) + 柬 (phonetic レン) — raw silk boiled and worked until supple: to refine; refining yourself: practice.', 'Boil the silk, work it, boil it again: softness is earned — レン. 練習 does to you what the vat does to thread.'),
  ('路', '路', '["path","route","road","distance"]'::jsonb, '{"ロ","ル"}', '{"-じ","みち"}', 'N3', 3, 13, '8def', 'Phono-semantic: foot (足) + 各 ''arrive'' (phonetic ロ) — where feet arrive one after another: the road, the route.', 'Feet arriving in each other''s prints until the ground remembers — ロ. 道路 doubles it; 線路 lays it in steel.'),
  ('和', '和', '["harmony","Japanese style","peace","soften","Japan"]'::jsonb, '{"ワ","オ","カ"}', '{"やわ.らぐ","やわ.らげる","なご.む","なご.やか","あ.える"}', 'N3', 3, 8, '548c', 'Phono-semantic: grain (禾, phonetic ワ) + mouth (口) — grain shared among mouths: peace, harmony; the name Japan chose for its own style: 和.', 'Rice enough for every mouth at the table — ワ. 平和 is the treaty; 和食, 和室, 和風: harmony you can eat, sit in, and decorate with.'),
  ('宮', '宮', '["Shinto shrine","constellations","palace","princess"]'::jsonb, '{"キュウ","グウ","ク","クウ"}', '{"みや"}', 'N2', 3, 10, '5bae', 'Compound ideograph: many rooms (呂) under one great roof (宀) — a palace; the god''s palace: a shrine.', 'Room after room under the sacred roof — みや. 宮崎, 神宮: palaces on the map.'),
  ('詩', '詩', '["poem","poetry"]'::jsonb, '{"シ"}', '{"うた"}', 'N2', 3, 13, '8a69', 'Phono-semantic: words (言) + 寺 (phonetic シ) — words measured like temple bells: poetry.', 'Language that keeps temple time — シ. 詩人: the bell-keeper.'),
  ('昭', '昭', '["shining","bright"]'::jsonb, '{"ショウ"}', '{}', 'N2', 3, 9, '662d', 'Phono-semantic: sun (日) + 召 (phonetic ショウ) — light called forth: shining, luminous.', 'The kanji of the 昭和 era — ショウ: the sun summoned onto a whole century.'),
  ('丁', '丁', '["street","ward","town","counter for guns, tools, leaves or cakes of something","even number","4th calendar sign"]'::jsonb, '{"チョウ","テイ","チン","トウ","チ"}', '{"ひのと"}', 'N2', 3, 2, '4e01', 'Pictograph: a nail seen from the side — borrowed for city blocks (丁目) and for the politeness of 丁寧.', 'One nail pins one block of the city grid — チョウ. 丁寧: work done to the last nail.'),
  ('帳', '帳', '["notebook","account book","album","curtain","veil","net","tent"]'::jsonb, '{"チョウ"}', '{"とばり"}', 'N2', 3, 11, '5e33', 'Phono-semantic: cloth (巾) + 長 (phonetic チョウ) — the long hanging register: account book, notebook.', 'The ledger unrolling like drapery — チョウ. 手帳: the pocket edition.'),
  ('笛', '笛', '["flute","clarinet","pipe","whistle","bagpipe","piccolo"]'::jsonb, '{"テキ"}', '{"ふえ"}', 'N2', 3, 11, '7b1b', 'Phono-semantic: bamboo (⺮) + 由 (phonetic テキ) — the bored bamboo pipe: a flute, a whistle.', 'Bamboo with a reason (由) to sing — ふえ. 口笛: the built-in model.'),
  ('豆', '豆', '["beans","pea","midget"]'::jsonb, '{"トウ","ズ"}', '{"まめ","まめ-"}', 'N2', 3, 7, '8c46', 'Pictograph: a stemmed offering vessel — borrowed long ago for the beans it held.', 'The dish that became its contents — まめ. 豆腐: beans, transfigured.'),
  ('羊', '羊', '["sheep"]'::jsonb, '{"ヨウ"}', '{"ひつじ"}', 'N2', 3, 6, '7f8a', 'Pictograph: a sheep''s head with curling horns — the favored offering, hiding inside 美, 洋, 善.', 'Horns, ears, muzzle — ひつじ. The quietest component in the beautiful kanji.'),
  ('以', '以', '["by means of","because","in view of","compared with"]'::jsonb, '{"イ"}', '{"もっ.て"}', 'N4', 4, 5, '4ee5', 'Oracle-bone form shows a person carrying a tool — ''taking (something) as means'': by, with, from a given point (以上, 以下).', 'Grab the tool and the boundary line moves with it — イ. Set the marker: 三つ以上, everything from three up; 以外, everything the tool didn''t touch.'),
  ('英', '英', '["England","English","hero","outstanding","calyx"]'::jsonb, '{"エイ"}', '{"はなぶさ"}', 'N4', 4, 8, '82f1', 'Phono-semantic: plants (艹) + 央 ''center'' (phonetic エイ) — the central blossom, the finest flower: outstanding; chosen to transcribe ''England'' (英国).', 'The one flower standing dead-center of the field, taller than the rest — エイ. It lent its brilliance to a whole language: 英語.'),
  ('建', '建', '["build"]'::jsonb, '{"ケン","コン"}', '{"た.てる","た.て","-だ.て","た.つ"}', 'N4', 4, 9, '5efa', 'Compound ideograph: a brush (聿) drafting plans along a long stride (廴) — pacing out the site, plans in hand: to build, to erect.', 'Blueprint in one hand, long strides across the empty lot — たてる. A 建物 is a drawing that learned to stand.'),
  ('験', '験', '["verification","effect","testing"]'::jsonb, '{"ケン","ゲン"}', '{"あかし","しるし","ため.す","ためし"}', 'N4', 4, 18, '9a13', 'Phono-semantic: horse (馬) + a phonetic (僉, ケン) — testing horses before buying them: verification by trial.', 'Ride the horse around the yard before you pay: that ride is the test — ケン. 試験 and 経験: exams and experience, both just laps on the horse.'),
  ('好', '好', '["fond","pleasing","like something"]'::jsonb, '{"コウ"}', '{"この.む","す.く","よ.い","い.い"}', 'N4', 4, 6, '597d', 'Compound ideograph: woman (女) + child (子) — a mother with her child: affection itself; good, beloved.', 'Mother and child leaning into each other: the warmest picture the script owns — すき. 大好き stacks ''big'' on top and means it.'),
  ('菜', '菜', '["vegetable","side dish","greens"]'::jsonb, '{"サイ"}', '{"な"}', 'N4', 4, 11, '83dc', 'Phono-semantic: plants (艹) + 采 ''a hand picking from a tree'' (phonetic サイ) — greens gathered by hand: vegetables, side dishes.', 'A hand in the greens, picking dinner leaf by leaf — な, サイ. 野菜: the pickings of the open field.'),
  ('産', '産', '["products","bear","give birth","yield","childbirth","native","property"]'::jsonb, '{"サン"}', '{"う.む","う.まれる","うぶ-","む.す"}', 'N4', 4, 11, '7523', 'Compound: a phonetic top (产) over 生 ''life'' — life brought forth: to bear, to produce; hence products and property.', 'Under the overhang, new life (生) arrives — うむ. Farms 生産 their crops, mothers 出産, and the 産 on souvenir boxes means ''born here'': 北海道産.'),
  ('試', '試', '["test","try","attempt","experiment","ordeal"]'::jsonb, '{"シ"}', '{"こころ.みる","ため.す"}', 'N4', 4, 13, '8a66', 'Phono-semantic: words (言) + 式 ''set form, ceremony'' (phonetic シ) — putting performance against the set form: to test, to try.', 'Read the standard aloud (言), then try to match it (式) — ためす. 試験 measures the gap; 試着 is the fitting-room version.'),
  ('借', '借', '["borrow","rent"]'::jsonb, '{"シャク"}', '{"か.りる"}', 'N4', 4, 10, '501f', 'Phono-semantic: person (亻) + 昔 ''long ago'' (phonetic シャク) — a person trading on old ties: to borrow.', '''Remember old times (昔)? So… could I borrow it?'' — かりる. Debts age like the kanji says: from yesterday''s favor to ancient history.'),
  ('説', '説', '["opinion","theory","explanation","rumor"]'::jsonb, '{"セツ","ゼイ"}', '{"と.く"}', 'N4', 4, 14, '8aac', 'Phono-semantic: words (言) + 兌 ''to loosen, exchange'' (phonetic セツ) — words that unravel a knot: to explain; a theory.', 'Talk (言) until the tangled thing comes loose (兌) — セツ. 説明 is untying in public; a 小説 unties a whole life, slowly.'),
  ('低', '低', '["lower","short","humble"]'::jsonb, '{"テイ"}', '{"ひく.い","ひく.める","ひく.まる"}', 'N4', 4, 7, '4f4e', 'Phono-semantic: person (亻) + 氐 ''base, bottom'' (phonetic テイ) — a person down at the base line: low.', 'Someone crouched at the foundation line, head below the fence — ひくい. Low prices, low voices, low ceilings: all down at 氐.'),
  ('働', '働', '["work","(kokuji)"]'::jsonb, '{"ドウ"}', '{"はたら.く"}', 'N4', 4, 13, '50cd', 'A kokuji — a kanji invented in Japan: person (亻) + 動 ''move'' — a person in motion: to work. China later borrowed it back.', 'A person set in motion and kept there: work — はたらく. Japan needed a kanji for it badly enough to build one from scratch.'),
  ('特', '特', '["special"]'::jsonb, '{"トク"}', '{}', 'N4', 4, 10, '7279', 'Phono-semantic: ox (牛) + 寺 ''temple'' (phonetic トク) — the bull chosen for the temple sacrifice: singled out, special.', 'Of the whole herd, one bull gets the temple ribbon — トク. 特別, 特急: whatever wears the ribbon skips the line.'),
  ('飯', '飯', '["meal","boiled rice"]'::jsonb, '{"ハン"}', '{"めし"}', 'N4', 4, 12, '98ef', 'Phono-semantic: food (飠) + 反 ''turn over'' (phonetic ハン) — rice turned in the pot as it steams: cooked rice, the meal itself.', 'Fold the rice over once more before serving — ごはん. In Japanese, ''meal'' and ''rice'' are the same word, and this kanji is why.'),
  ('不', '不', '["negative","non-","bad","ugly","clumsy"]'::jsonb, '{"フ","ブ"}', '{}', 'N4', 4, 4, '4e0d', 'Origin debated — a flower calyx, or a bird beating upward and never arriving. Pure negation since the oracle bones: un-, non-, not.', 'A bird flapping at the underside of the sky, never getting through — フ. Stick it on anything and the thing fails: 不便, 不安, 不可能.'),
  ('別', '別', '["separate","branch off","diverge","fork","another","extra","specially"]'::jsonb, '{"ベツ"}', '{"わか.れる","わ.ける"}', 'N4', 4, 7, '5225', 'Compound ideograph: flesh parted from the bone with a blade (刂) — to divide cleanly: separate, distinct, another.', 'One clean stroke of the cleaver and it''s two things now — わかれる, ベツ. 別々に: ''separately, please'' — the check gets the blade too.'),
  ('便', '便', '["convenience","facility","excrement","feces","letter","chance"]'::jsonb, '{"ベン","ビン"}', '{"たよ.り"}', 'N4', 4, 9, '4fbf', 'Compound: person (亻) + 更 ''change, renew'' — a person smoothing things over for others: convenience; the courier who makes distance convenient: the post.', 'The fixer who rearranges (更) everything until it''s easy — ベン; and the mail (ビン) that spares you the trip. 便利: life with the fixer on call.'),
  ('民', '民', '["people","nation","subjects"]'::jsonb, '{"ミン"}', '{"たみ"}', 'N4', 4, 5, '6c11', 'Grim origin: an eye pierced by a needle — the blinded captives of early states, hence ''the subjects, the common people''. The meaning softened into ''the people, the nation''.', 'The masses packed under one low roof-stroke, anonymous by design — ミン. 国民, 市民: the crowd every government answers to (eventually).'),
  ('料', '料', '["fee","materials"]'::jsonb, '{"リョウ"}', '{}', 'N4', 4, 10, '6599', 'Compound ideograph: rice (米) + measuring ladle (斗) — grain measured out: materials, provisions, and the measured price: fee.', 'Scoop the rice, level it, name the price — リョウ. 料理 measures ingredients; 料金 measures your wallet.'),
  ('愛', '愛', '["love","affection","favourite"]'::jsonb, '{"アイ"}', '{"いと.しい","かな.しい","め.でる","お.しむ","まな"}', 'N3', 4, 13, '611b', 'Compound: a hand drawing something under cover, the heart (心) held close, feet trailing slow (夂) — walking carefully with a full heart: love.', 'Carrying a heart so carefully your feet forget to hurry — あい. The kanji walks the way people in love actually walk.'),
  ('案', '案', '["plan","suggestion","draft","ponder","fear","proposition","idea","expectation","worry","table","bench"]'::jsonb, '{"アン"}', '{"つくえ"}', 'N3', 4, 10, '6848', 'Phono-semantic: 安 ''at ease'' (phonetic アン) + wood (木) — the desk one leans on at ease; what is drafted there: a plan, a proposal.', 'Elbows on the wooden desk, turning the idea over in comfort — アン. 案内 hands your plan to a stranger politely.'),
  ('位', '位', '["rank","grade","throne","crown","about","some"]'::jsonb, '{"イ"}', '{"くらい","ぐらい"}', 'N3', 4, 7, '4f4d', 'Compound ideograph: a person (亻) at their standing-place (立) in the court line-up — one''s position: rank, grade.', 'Everyone stands exactly where their title puts them — イ. 一位, 二位: the podium is just this kanji with steps.'),
  ('衣', '衣', '["garment","clothes","dressing"]'::jsonb, '{"イ","エ"}', '{"ころも","きぬ","-ぎ"}', 'N3', 4, 6, '8863', 'Pictograph: a robe with its crossed collar and trailing hems — clothing. As a component (衤) it dresses kanji like 服''s cousins 被 and 裏.', 'The kimono collar crossing at the throat, hem sweeping the floor — ころも, イ. 衣服: the kanji you put on every day.'),
  ('印', '印', '["stamp","seal","mark","imprint","symbol","emblem","trademark","evidence","souvenir","India"]'::jsonb, '{"イン"}', '{"しるし","-じるし","しる.す"}', 'N3', 4, 6, '5370', 'Compound ideograph: a hand pressing a kneeling figure down — pressing from above: to stamp; the seal so pressed.', 'Press straight down and hold: the mark takes — しるし, イン. In Japan the 印鑑 outranks your signature.'),
  ('栄', '栄', '["flourish","prosperity","honor","glory","splendor"]'::jsonb, '{"エイ","ヨウ"}', '{"さか.える","は.え","-ば.え","は.える","え"}', 'N3', 4, 9, '6804', 'Simplified from 榮: torches blazing around a tree in full bloom — splendor, prosperity: to flourish.', 'A tree lit up like a festival, every branch a lantern — さかえる. 栄光: the tree at maximum wattage.'),
  ('塩', '塩', '["salt"]'::jsonb, '{"エン"}', '{"しお"}', 'N3', 4, 13, '5869', 'Simplified from 鹽: brine worked in pans (皿) on the shore (土) — sea-water boiled down: salt.', 'Seawater in the flat dish, sun and fire doing the rest: white crystals — しお. The one rock you eat daily.'),
  ('億', '億', '["hundred million","10**8"]'::jsonb, '{"オク"}', '{}', 'N3', 4, 15, '5104', 'Phono-semantic: person (亻) + 意 (phonetic オク) — a number at the edge of what a mind can hold: one hundred million.', 'A person trying to imagine (意) the crowd: 100,000,000 — オク. Japan counts its population in 億 — barely.'),
  ('加', '加', '["add","addition","increase","join","include","Canada"]'::jsonb, '{"カ"}', '{"くわ.える","くわ.わる"}', 'N3', 4, 5, '52a0', 'Compound ideograph: strength (力) added to the voice (口) — piling on: to add, to join.', 'Push (力) your word (口) onto the pile: +1 — くわえる. 参加 is adding yourself; カナダ borrowed it for its own name: 加奈陀.'),
  ('果', '果', '["fruit","reward","carry out","achieve","complete","end","finish","succeed"]'::jsonb, '{"カ"}', '{"は.たす","はた.す","-は.たす","は.てる","-は.てる","は.て"}', 'N3', 4, 8, '679c', 'Pictograph: a tree (木) with a round fruit heavy at its top — fruit; what ripens from actions: result.', 'The tree holds up its finished work — くだもの (果物), the fruit; 結果, the fruit of everything else.'),
  ('課', '課', '["chapter","lesson","section","department","division","counter for chapters (of a book)"]'::jsonb, '{"カ"}', '{}', 'N3', 4, 15, '8ab2', 'Phono-semantic: words (言) + 果 ''result'' (phonetic カ) — tasks assigned and reckoned by results: a lesson, an administrative section.', 'Assignments handed out, fruit expected by Friday — カ. 第一課 in the textbook, 課長 at the office: same harvest logic.'),
  ('貨', '貨', '["freight","goods","property"]'::jsonb, '{"カ"}', '{"たから"}', 'N3', 4, 11, '8ca8', 'Phono-semantic: 化 ''change'' (phonetic カ) + money (貝) — goods that change into money and back: wares, freight, currency.', 'Boxes that are just money in disguise (化) — カ. 貨物 rides the rails; 硬貨 jingles in your pocket.'),
  ('改', '改', '["reformation","change","modify","mend","renew","examine","inspect","search"]'::jsonb, '{"カイ"}', '{"あらた.める","あらた.まる"}', 'N3', 4, 7, '6539', 'Compound ideograph: the self (己) under the correcting hand (攵) — beaten into better shape: to reform, revise.', 'Take the stick to your own habits — あらためる. 改札 reforms your ticket; 改善 reforms everything else, kaizen.'),
  ('械', '械', '["contraption","fetter","machine","instrument"]'::jsonb, '{"カイ"}', '{"かせ"}', 'N3', 4, 11, '68b0', 'Phono-semantic: wood (木) + 戒 ''restrain'' (phonetic カイ) — originally wooden fetters; any engineered wooden device: a contraption, machinery.', 'Wood that holds and moves by design: first shackles, then machines — カイ. 機械: the contraption fully grown.'),
  ('害', '害', '["harm","injury"]'::jsonb, '{"ガイ"}', '{}', 'N3', 4, 10, '5bb3', 'Compound: under a roof (宀), a gouging instrument (丰) over a mouth (口) — damage done within the house: harm, injury.', 'The wound happens indoors, where it isn''t supposed to — ガイ. 公害, 被害: harm with an address.'),
  ('各', '各', '["each","every","either"]'::jsonb, '{"カク"}', '{"おのおの"}', 'N3', 4, 6, '5404', 'Compound ideograph: a foot (夂) arriving at a doorway (口) — arrivals one at a time: each, respectively.', 'One visitor at a time crossing the doorstep — カク. 各駅停車: the train that greets each station personally.'),
  ('覚', '覚', '["memorize","learn","remember","awake","sober up"]'::jsonb, '{"カク"}', '{"おぼ.える","さ.ます","さ.める","さと.る"}', 'N3', 4, 12, '899a', 'Simplified from 覺: the crown of learning over 見 ''see'' — seeing with sudden clarity: to awaken; to fix in mind: to memorize.', 'The lights snap on over your eyes: got it, and I''m keeping it — おぼえる; 目が覚める, the same lights at 7 a.m.'),
  ('完', '完', '["perfect","completion","end"]'::jsonb, '{"カン"}', '{}', 'N3', 4, 7, '5b8c', 'Phono-semantic: roof (宀) + 元 (phonetic カン) — the house finished down to the roofbeam: complete.', 'The last tile set on the roof: nothing left to build — カン. 完成! — stamp it and step back.'),
  ('官', '官', '["bureaucrat","the government","organ"]'::jsonb, '{"カン"}', '{}', 'N3', 4, 8, '5b98', 'Compound ideograph: officials quartered (𠂤) under the state roof (宀) — government officers: the bureaucrat.', 'Under the official roof, the staff stack like sediment — カン. 警察官, 外交官: give a roof a stamp and it breeds officials.'),
  ('管', '管', '["pipe","tube","wind instrument","drunken talk","control","jurisdiction"]'::jsonb, '{"カン"}', '{"くだ"}', 'N3', 4, 14, '7ba1', 'Phono-semantic: bamboo (⺮) + 官 (phonetic カン) — the hollow bamboo tube: a pipe; what flows must be managed: control.', 'Bamboo plumbing with an official in charge of the valves — くだ. 管理: bureaucracy applied to pipes, then to everything.'),
  ('観', '観', '["outlook","look","appearance","condition","view"]'::jsonb, '{"カン"}', '{"み.る","しめ.す"}', 'N3', 4, 18, '89b3', 'Phono-semantic (simplified from 觀): 雚 ''heron'' (phonetic カン) + 見 ''see'' — the heron''s fixed stare over the marsh: to observe; a view.', 'Stand heron-still and just watch — カン. 観光 is doing it on vacation; 観客 doing it in seats.'),
  ('関', '関', '["connection","barrier","gateway","involve","concerning"]'::jsonb, '{"カン"}', '{"せき","-ぜき","かか.わる","からくり","かんぬき"}', 'N3', 4, 14, '95a2', 'Simplified from 關: a gate (門) with its cross-bolts — the checkpoint barrier; what passes through it: connections.', 'The bolt across the gate decides who''s connected to whom — カン. 関係: the doors between people; 関西: west of the barrier.'),
  ('願', '願', '["petition","request","vow","wish","hope"]'::jsonb, '{"ガン"}', '{"ねが.う","-ねがい"}', 'N3', 4, 19, '9858', 'Phono-semantic: 原 (phonetic ガン) + head (頁) — the head bowed at the source of authority: to petition, to wish.', 'Head lowered all the way to the spring — ねがう. お願いします: the everyday bow this kanji performs.'),
  ('器', '器', '["utensil","vessel","receptacle","implement","instrument","ability","container","tool","set"]'::jsonb, '{"キ"}', '{"うつわ"}', 'N3', 4, 15, '5668', 'Compound ideograph, classically read: four vessels (口×4) with a dog (犬) guarding them — the household''s utensils; by extension, capacity.', 'Four bowls and one dog on duty between them — うつわ. 楽器, 食器: instruments and dishes, all guarded goods.'),
  ('希', '希', '["hope","beg","request","pray","beseech","Greece","dilute (acid)","rare","few","phenomenal"]'::jsonb, '{"キ","ケ"}', '{"まれ","こいねが.う"}', 'N3', 4, 7, '5e0c', 'Compound: threads crossed sparse (㐅) over cloth (巾) — a weave so loose it''s rare; what is rare is longed for: hope.', 'A weave with more gaps than thread: rare as the thing you''re hoping for — キ. 希望: hope, honest about the odds.'),
  ('機', '機', '["loom","mechanism","machine","airplane","opportunity","potency","efficacy","occasion"]'::jsonb, '{"キ"}', '{"はた"}', 'N3', 4, 16, '6a5f', 'Phono-semantic: wood (木) + 幾 (phonetic キ) — the wooden loom, the first machine; hence mechanism, and the critical moment its trigger implies.', 'The loom clacks: wood doing arithmetic — キ. 飛行機, 洗濯機, チャンスは機会 — every machine and moment descends from it.'),
  ('季', '季', '["seasons"]'::jsonb, '{"キ"}', '{}', 'N3', 4, 8, '5b63', 'Compound ideograph: grain (禾) + child (子) — the youngest grain of the year; each round of planting: a season.', 'The grain''s newest child arrives four times a year — キ. 季節: the calendar told by what''s sprouting.'),
  ('議', '議', '["deliberation","consultation","debate","consideration"]'::jsonb, '{"ギ"}', '{}', 'N3', 4, 20, '8b70', 'Phono-semantic: words (言) + 義 ''what is right'' (phonetic ギ) — arguing out the right course: deliberation.', 'Words wrestling over what''s right, at length — ギ. 会議: the room; 議論: the sport played in it.'),
  ('求', '求', '["request","want","wish for","require","demand"]'::jsonb, '{"キュウ","グ"}', '{"もと.める"}', 'N3', 4, 7, '6c42', 'Pictograph: a fur garment — borrowed since antiquity for ''to seek, to request'' (the original sense lives on in 裘).', 'Reaching for the warm pelt in midwinter: pure wanting — もとめる. 求人: companies doing the reaching.'),
  ('泣', '泣', '["cry","weep","moan"]'::jsonb, '{"キュウ"}', '{"な.く"}', 'N3', 4, 8, '6ce3', 'Phono-semantic: water (氵) + 立 (phonetic キュウ) — tears while standing: to weep (quietly — the loud kind is 鳴).', 'Standing still while the water runs down — なく. The kanji cries without moving; so do most adults.'),
  ('給', '給', '["salary","wage","gift","allow","grant","bestow on"]'::jsonb, '{"キュウ"}', '{"たま.う","たも.う","-たま.え"}', 'N3', 4, 12, '7d66', 'Phono-semantic: thread (糸) + 合 (phonetic キュウ) — thread supplied to match the need: to provide; what''s provided monthly: salary.', 'The supply line feeds you exactly what fits — キュウ. 給料: the thread that arrives on the 25th.'),
  ('漁', '漁', '["fishing","fishery"]'::jsonb, '{"ギョ","リョウ"}', '{"あさ.る"}', 'N3', 4, 14, '6f01', 'Compound ideograph: water (氵) + fish (魚) — going after fish in the water: fishing.', 'Fish plus water plus intent — リョウ. A 漁師 is the fish kanji with a boat and a schedule.'),
  ('競', '競', '["emulate","compete with","bid","sell at auction","bout","contest","race"]'::jsonb, '{"キョウ","ケイ"}', '{"きそ.う","せ.る","くら.べる"}', 'N3', 4, 20, '7af6', 'Compound ideograph: two figures (立+兄) side by side, straining forward — a footrace in kanji form: to compete.', 'Twin runners frozen at the same stride — きそう. 競争 is the photo finish; 競馬 adds horses.'),
  ('共', '共', '["together","both","neither","all","and","alike","with"]'::jsonb, '{"キョウ"}', '{"とも","とも.に","-ども"}', 'N3', 4, 6, '5171', 'Pictograph: two hands raising one object together — jointly: together, shared.', 'Four hands, one load, lifted level — とも. 共通, 共同: whatever needs more hands than yours.'),
  ('協', '協', '["co-","cooperation"]'::jsonb, '{"キョウ"}', '{}', 'N3', 4, 8, '5354', 'Compound ideograph: ten (十) + three strengths (力×3) — many muscles pulling as one: cooperation.', 'Three biceps bolted to one crossbeam — キョウ. 協力: the kanji is literally a tug-of-war team.'),
  ('極', '極', '["extreme","pole","extremely","very","highly","most","end","settlement","conclusion","highest rank"]'::jsonb, '{"キョク","ゴク"}', '{"きわ.める","きわ.まる","きわ.まり","きわ.み","き.める","-ぎ.め","き.まる"}', 'N3', 4, 12, '6975', 'Phono-semantic: wood (木) + 亟 (phonetic キョク) — the ridgepole, highest timber of the house: the utmost point, the pole.', 'The one beam nothing sits above — きわめる. 北極 hangs the planet on it; 極めて pushes any adjective to the rafter.'),
  ('訓', '訓', '["instruction","Japanese character reading","explanation","read"]'::jsonb, '{"クン","キン"}', '{"おし.える","よ.む","くん.ずる"}', 'N3', 4, 10, '8a13', 'Phono-semantic: words (言) + 川 ''stream'' (phonetic クン) — teaching that flows downhill from master to pupil: instruction; the native Japanese reading ''taught onto'' each kanji.', 'Words channeled like water down a course — クン. Every kanji you learn drinks from two streams: 音 and 訓.'),
  ('群', '群', '["flock","group","crowd","herd","swarm","cluster"]'::jsonb, '{"グン"}', '{"む.れる","む.れ","むら","むら.がる"}', 'N3', 4, 13, '7fa4', 'Phono-semantic: 君 ''lord'' (phonetic グン) + sheep (羊) — the lord''s sheep moving as one: a flock, a crowd.', 'Where the shepherd-lord walks, the wool follows in a single blob — むれ. 群馬: a whole prefecture of herds.'),
  ('軍', '軍', '["army","force","troops","war","battle"]'::jsonb, '{"グン"}', '{"いくさ"}', 'N3', 4, 9, '8ecd', 'Compound ideograph: chariots (車) drawn into a covered ring (冖) — the encircled war-camp: army.', 'Wagons circled tight under one canopy — グン. 軍手, army gloves: the war-camp''s one export to your toolbox.'),
  ('景', '景', '["scenery","view"]'::jsonb, '{"ケイ"}', '{}', 'N3', 4, 12, '666f', 'Phono-semantic: sun (日) + 京 ''capital'' (phonetic ケイ) — sunlight over the capital''s towers: a fine view, scenery.', 'Morning light hitting the skyline: postcard weather — ケイ. 景色 is the view; 夜景 the same city after dark.'),
  ('芸', '芸', '["technique","art","craft","performance","acting","trick","stunt"]'::jsonb, '{"ゲイ","ウン"}', '{"う.える","のり","わざ"}', 'N3', 4, 7, '82b8', 'Simplified from 藝, originally a figure kneeling to plant a seedling — the cultivated skill: art, craft, performance.', 'Planting done so precisely it counts as performance — ゲイ. 芸術 hangs in museums; 芸人 does it on television.'),
  ('欠', '欠', '["lack","gap","fail","yawning radical (no. 76)"]'::jsonb, '{"ケツ","ケン"}', '{"か.ける","か.く"}', 'N3', 4, 4, '6b20', 'Pictograph: a person with mouth gaping wide — the open hole; in Japanese, what''s missing: lack, absence.', 'A yawn is a hole in your face; 欠 is a hole in the roster — かける. 欠席: the empty chair kanji.'),
  ('結', '結', '["tie","bind","contract","join","organize","do up hair","fasten"]'::jsonb, '{"ケツ","ケチ"}', '{"むす.ぶ","ゆ.う","ゆ.わえる"}', 'N3', 4, 12, '7d50', 'Phono-semantic: thread (糸) + 吉 (phonetic ケツ) — the auspicious knot: to tie, join, conclude.', 'Tie the lucky knot and it holds — むすぶ. 結婚 ties people; 結果 is where any thread ends up.'),
  ('健', '健', '["healthy","health","strength","persistence"]'::jsonb, '{"ケン"}', '{"すこ.やか"}', 'N3', 4, 11, '5065', 'Phono-semantic: person (亻) + 建 ''build'' (phonetic ケン) — a person built sound and standing firm: healthy, robust.', 'A body with good architecture — ケン. 健康: the building inspection you pass by sleeping and eating well.'),
  ('固', '固', '["harden","set","clot","curdle"]'::jsonb, '{"コ"}', '{"かた.める","かた.まる","かた.まり","かた.い"}', 'N3', 4, 8, '56fa', 'Phono-semantic: enclosure (囗) + 古 ''old'' (phonetic コ) — what has sat walled-in and aged: hardened, firm.', 'Something old sealed in a box until it sets like concrete — かたい. 固い約束: a promise past its bending date.'),
  ('候', '候', '["climate","season","weather","wait for","expect"]'::jsonb, '{"コウ"}', '{"そうろう"}', 'N3', 4, 10, '5019', 'Compound: a person (亻) posted to watch and attend — reading the signs of sky and season: climate, symptoms, attendance.', 'The lookout notes wind, clouds, mood of the sky — コウ. 天候: the sentry''s daily report; 気候: his yearly one.'),
  ('康', '康', '["ease","peace"]'::jsonb, '{"コウ"}', '{}', 'N3', 4, 11, '5eb7', 'Origin read as grain threshed in abundance (husks flying below the frame) — plenty, hence ease and well-being.', 'The barn full, the chaff dancing, nothing to fear from winter — コウ. 健康 pairs a sound frame with a full barn.'),
  ('香', '香', '["incense","smell","perfume"]'::jsonb, '{"コウ","キョウ"}', '{"か","かお.り","かお.る"}', 'N3', 4, 9, '9999', 'Compound ideograph: grain (禾) over sweetness (曰) — the smell of grain cooking sweet: fragrance, incense.', 'Rice on the fire, the whole house leaning toward the pot — かおり. 香水 bottles the effect.'),
  ('差', '差', '["distinction","difference","variation","discrepancy","margin","balance"]'::jsonb, '{"サ"}', '{"さ.す","さ.し"}', 'N3', 4, 10, '5dee', 'Compound: grain hanging uneven over the workman''s square — lengths that don''t match: difference, discrepancy.', 'Hold the ruler to the stalks: no two agree — さ. 時差 is the planet failing the same inspection.'),
  ('最', '最', '["utmost","most","extreme"]'::jsonb, '{"サイ","シュ"}', '{"もっと.も","つま"}', 'N3', 4, 12, '6700', 'Compound: a daring seizure (取) made under the helmet (曰) — the boldest stroke of all: the utmost, the most.', 'Reach in and take the top prize — もっとも, サイ. Prefix it and win any superlative: 最高, 最初, 最強.'),
  ('材', '材', '["lumber","log","timber","wood","materials","ingredients","talent"]'::jsonb, '{"ザイ"}', '{}', 'N3', 4, 7, '6750', 'Phono-semantic: wood (木) + 才 ''inborn stuff'' (phonetic ザイ) — timber with potential in it: material.', 'A log already dreaming of being a beam — ザイ. 材料 is any ingredient mid-dream; 人材 does it to people.'),
  ('昨', '昨', '["yesterday","previous"]'::jsonb, '{"サク"}', '{}', 'N3', 4, 9, '6628', 'Phono-semantic: day (日) + 乍 ''freshly cut'' (phonetic サク) — the day just sliced off the calendar: yesterday.', 'The day the blade just trimmed away, still lying there — サク. 昨日: close enough to touch, gone for good.'),
  ('刷', '刷', '["printing","print","brush"]'::jsonb, '{"サツ"}', '{"す.る","-ず.り","-ずり","は.く"}', 'N3', 4, 8, '5237', 'Compound: scraping a carved block clean with cloth and blade — pressing off copies: to print.', 'Ink the block, wipe, press, repeat — する, サツ. 印刷: the wipe that filled the world''s libraries.'),
  ('察', '察', '["guess","presume","surmise","judge","understand"]'::jsonb, '{"サツ"}', '{}', 'N3', 4, 14, '5bdf', 'Phono-semantic: roof (宀) + 祭 ''rite'' (phonetic サツ) — inspecting the rite under the roof for the smallest fault: to scrutinize, to infer.', 'Reading the ceremony for what nobody said aloud — サツ. 警察 does it for a living; 察する is doing it kindly.'),
  ('札', '札', '["tag","paper money","counter for bonds","placard","bid"]'::jsonb, '{"サツ"}', '{"ふだ"}', 'N3', 4, 5, '672d', 'Compound: wood (木) + a hook (乚) — a thin wooden slip hung up: a tag, a card; paper money by descent.', 'The wooden tag swinging on its nail — ふだ. 改札 checks yours; 千円札 is the tag you''d rather keep.'),
  ('参', '参', '["nonplussed","three (in documents)","going","coming","visiting","visit","be defeated","die","be madly in love","participate","take part in"]'::jsonb, '{"サン","シン"}', '{"まい.る","まい-","まじわる","みつ"}', 'N3', 4, 8, '53c2', 'Pictograph read as hairpins glittering on a figure going to court — to present oneself: to visit (humbly), to participate; formal ''three''.', 'Dressed, pinned and sparkling: off to appear before someone — まいる. 参加 is showing up; 参りました is showing up defeated.'),
  ('散', '散', '["scatter","disperse","spend","squander"]'::jsonb, '{"サン"}', '{"ち.る","ち.らす","-ち.らす","ち.らかす","ち.らかる","ち.らばる","ばら","ばら.ける"}', 'N3', 4, 12, '6563', 'Compound: meat beaten apart with a stick — knocked into pieces and strewn: to scatter, disperse.', 'One whack and everything flies apart — ちる. 散歩 is the peaceful version: scattering yourself around the block.'),
  ('残', '残', '["remainder","leftover","balance"]'::jsonb, '{"ザン","サン"}', '{"のこ.る","のこ.す","そこな.う","のこ.り"}', 'N3', 4, 10, '6b8b', 'Phono-semantic: bones (歹) + 戔 ''blades'' (phonetic ザン) — what the blades leave on the field: the remainder; the cruelty that left it.', 'After everything is taken, this is what stays — のこる. 残念: the leftovers of a hope.'),
  ('司', '司', '["director","official","govt office","rule","administer"]'::jsonb, '{"シ"}', '{"つかさど.る"}', 'N3', 4, 5, '53f8', 'Compound ideograph: a hand raised over a commanding mouth — the one who directs affairs: to administer.', 'One raised hand, one clear order — シ. 上司 gives them; 司会 directs the party with a microphone.'),
  ('児', '児', '["newborn babe","child","young of animals"]'::jsonb, '{"ジ","ニ","ゲイ"}', '{"こ","-こ","-っこ"}', 'N3', 4, 7, '5150', 'Simplified from 兒: an infant with the fontanelle still open (the gap in the top) on baby legs — a newborn, a child.', 'Soft-skulled and wobbling but already walking — ジ. 児童 fills classrooms; 育児 fills your nights.'),
  ('治', '治', '["reign","be at peace","calm down","subdue","quell","govt","cure","heal","rule","conserve"]'::jsonb, '{"ジ","チ"}', '{"おさ.める","おさ.まる","なお.る","なお.す"}', 'N3', 4, 8, '6cbb', 'Phono-semantic: water (氵) + 台 (phonetic ジ/チ) — mastering the rivers was the first governing; setting things right heals: to govern, to cure.', 'Tame the flood and you can rule anything, including a fever — おさめる, なおる. 政治 and 治療: same verb, different floods.'),
  ('辞', '辞', '["resign","word","term","expression"]'::jsonb, '{"ジ"}', '{"や.める","いな.む"}', 'N3', 4, 13, '8f9e', 'Simplified from 辭: the tongue (舌) and the branding needle (辛) — formal words, sharp enough to cut ties: an address; to resign.', 'Words with a needle in them: the farewell speech — ジ. 辞書 collects the words; 辞める uses the needle.'),
  ('失', '失', '["lose","error","fault","disadvantage","loss"]'::jsonb, '{"シツ"}', '{"うしな.う","う.せる"}', 'N3', 4, 5, '5931', 'Pictograph: a hand with something dropping from it — gone before the fingers close: to lose.', 'The exact instant it leaves your grip — うしなう. 失敗 is losing hold of the plan; 失礼 of the manners.'),
  ('種', '種', '["species","kind","class","variety","seed"]'::jsonb, '{"シュ"}', '{"たね","-ぐさ"}', 'N3', 4, 14, '7a2e', 'Phono-semantic: grain (禾) + 重 ''heavy'' (phonetic シュ) — the heaviest grains kept for sowing: seed; each seed its kind: species.', 'The fattest seeds go in the sowing jar, sorted by kind — たね. 種類: the jars, labeled.'),
  ('周', '周', '["circumference","circuit","lap"]'::jsonb, '{"シュウ"}', '{"まわ.り"}', 'N3', 4, 8, '5468', 'Pictograph: a field planted thick to its borders — covering all the way around: circumference, circuit.', 'Plow to every edge, then walk the fence line — シュウ. 一周: one full lap of anything.'),
  ('祝', '祝', '["celebrate","congratulate"]'::jsonb, '{"シュク","シュウ"}', '{"いわ.う"}', 'N3', 4, 9, '795d', 'Compound ideograph: the speaker (兄, a mouth on legs) at the altar (ネ) — reciting the blessing: to celebrate.', 'The family''s voice steps up to the altar with good news — いわう. お祝い: the blessing plus an envelope.'),
  ('順', '順', '["obey","order","turn","right","docility","occasion"]'::jsonb, '{"ジュン"}', '{}', 'N3', 4, 12, '9806', 'Compound ideograph: a head (頁) following the stream (川) — going with the current: obedient; the sequence the current makes: order.', 'Float head-first the way the river says — ジュン. 順番: the river arranging everyone into a queue.'),
  ('初', '初', '["first time","beginning"]'::jsonb, '{"ショ"}', '{"はじ.め","はじ.めて","はつ","はつ-","うい-","-そ.める","-ぞ.め"}', 'N3', 4, 7, '521d', 'Compound ideograph: cloth (衤) + blade (刀) — the tailor''s first cut into new fabric: the very beginning.', 'Scissors poised over untouched cloth: no undo after this — はじめて. 最初 is that cut; 初めまして its social version.'),
  ('焼', '焼', '["bake","burning"]'::jsonb, '{"ショウ"}', '{"や.く","や.き","や.き-","-や.き","や.ける"}', 'N3', 4, 12, '713c', 'Phono-semantic: fire (火) + 尭 ''raised high'' (phonetic ショウ) — flames piled high: to burn, grill, bake.', 'Stack the fire and put dinner over it — やく. 焼き鳥, 焼きそば, お好み焼き: Japan''s tastiest kanji.'),
  ('照', '照', '["illuminate","shine","compare","bashful"]'::jsonb, '{"ショウ"}', '{"て.る","て.らす","て.れる"}', 'N3', 4, 13, '7167', 'Phono-semantic: 昭 ''shining'' (phonetic ショウ) + fire (灬) — light cast down onto: to illuminate.', 'Floodlights plus footlights: everything visible — てる. 照れる is being lit up when you''d rather not be: blushing.'),
  ('省', '省', '["government ministry","conserve","omit"]'::jsonb, '{"セイ","ショウ"}', '{"かえり.みる","はぶ.く"}', 'N3', 4, 9, '7701', 'Compound ideograph: narrowing (少) the eye (目) — close inspection: to reflect (反省); to trim what inspection finds useless: omit; the inspecting office: ministry.', 'Squint hard at it: examine, then cut the excess — かえりみる, はぶく. The 省 ministries were born squinting at budgets.'),
  ('笑', '笑', '["laugh"]'::jsonb, '{"ショウ"}', '{"わら.う","え.む"}', 'N3', 4, 10, '7b11', 'Classically read: bamboo (⺮) swaying like a person doubled over (夭) — the whole grove shaking: to laugh.', 'Wind hits the grove and every stalk cracks up — わらう. 笑顔: the face doing what bamboo does.'),
  ('城', '城', '["castle"]'::jsonb, '{"ジョウ","セイ"}', '{"しろ"}', 'N3', 4, 9, '57ce', 'Phono-semantic: earth (土) + 成 ''completed'' (phonetic ジョウ) — earthworks raised to completion: a castle.', 'Dirt piled until it becomes (成) power — しろ. 大阪城: the hill that means business.'),
  ('信', '信', '["faith","truth","fidelity","trust"]'::jsonb, '{"シン"}', '{}', 'N3', 4, 9, '4fe1', 'Compound ideograph: a person (亻) standing by their word (言) — word and person aligned: trust, faith; a message so backed.', 'Where the person and the promise overlap — シン. 信じる is betting on that overlap; 自信 betting on your own.'),
  ('臣', '臣', '["retainer","subject"]'::jsonb, '{"シン","ジン"}', '{}', 'N3', 4, 7, '81e3', 'Pictograph: an eye turned down in a bowed head — the posture of service: retainer, minister.', 'The eye that never meets the throne''s — シン. 大臣: the deepest bow with the biggest office.'),
  ('成', '成', '["turn into","become","get","grow","elapse","reach"]'::jsonb, '{"セイ","ジョウ"}', '{"な.る","な.す","-な.す"}', 'N3', 4, 6, '6210', 'Compound: work driven to its end under the halberd''s authority — brought to completion: to become, to accomplish.', 'The final nail goes in and the thing exists — なる. 成功 is the nail landing; 成る the moment before.'),
  ('清', '清', '["pure","purify","cleanse","exorcise","Manchu dynasty"]'::jsonb, '{"セイ","ショウ","シン"}', '{"きよ.い","きよ.まる","きよ.める"}', 'N3', 4, 11, '6e05', 'Phono-semantic: water (氵) + 青 ''blue-green'' (phonetic セイ) — water so clean it shows blue: pure, clear.', 'Water you can read a book through — きよい. 清水寺: the temple named for exactly that spring.'),
  ('静', '静', '["quiet"]'::jsonb, '{"セイ","ジョウ"}', '{"しず-","しず.か","しず.まる","しず.める"}', 'N3', 4, 14, '9759', 'Phono-semantic: 青 (phonetic セイ) + 争 ''struggle'' — the struggle settled into blue calm: quiet, still.', 'The fight ends and blue silence pours back in — しずか. 静かに: what the librarian''s whole body says.'),
  ('席', '席', '["seat","mat","occasion","place"]'::jsonb, '{"セキ"}', '{"むしろ"}', 'N3', 4, 10, '5e2d', 'Compound: a cloth mat (巾) spread under the canopy (广) — one''s place on the matting: a seat.', 'Your square of cloth in the pavilion: reserved — セキ. 出席 is putting your body on it; 欠席 leaving it cold.'),
  ('積', '積', '["volume","product (x*y)","acreage","contents","pile up","stack","load","amass"]'::jsonb, '{"セキ"}', '{"つ.む","-づ.み","つ.もる","つ.もり"}', 'N3', 4, 16, '7a4d', 'Phono-semantic: grain (禾) + 責 ''levy'' (phonetic セキ) — the tax-grain stacked sack on sack: to pile up; the pile measured: volume, product.', 'Sacks climbing the granary wall, tallied as they rise — つむ. 積極的: piling effort the same way.'),
  ('折', '折', '["fold","break","fracture","bend","yield","submit"]'::jsonb, '{"セツ","シャク"}', '{"お.る","おり","お.り","-お.り","お.れる"}', 'N3', 4, 7, '6298', 'Compound ideograph: hand (扌) + axe (斤) — snapping green wood over the knee or blade: to break; the gentler bend: to fold.', 'Crease it like the axe would cut it — おる. 折り紙 folds paper; 骨折 folds what shouldn''t fold.'),
  ('節', '節', '["node","season","period","occasion","verse","clause","stanza","honor","joint","knuckle","knob","knot","tune","melody"]'::jsonb, '{"セツ","セチ"}', '{"ふし","-ぶし","のっと"}', 'N3', 4, 13, '7bc0', 'Phono-semantic: bamboo (⺮) + 即 (phonetic セツ) — the bamboo''s joints: nodes; the year''s joints: seasons; joints hold things in check: moderation.', 'Bamboo grows in verses with a knuckle between each — ふし. 季節 are the year''s knuckles; 節約 is gripping at one.'),
  ('戦', '戦', '["war","battle","match"]'::jsonb, '{"セン"}', '{"いくさ","たたか.う","おのの.く","そよ.ぐ","わなな.く"}', 'N3', 4, 13, '6226', 'Phono-semantic: 単 (phonetic セン — originally a forked hunting weapon) + 戈 ''halberd'' — weapons against weapons: war.', 'Two arsenals in one character, nothing else in it — たたかう. 戦争 doubles the word; history keeps doubling the kanji.'),
  ('浅', '浅', '["shallow","superficial","frivolous","wretched","shameful"]'::jsonb, '{"セン"}', '{"あさ.い"}', 'N3', 4, 9, '6d45', 'Phono-semantic: water (氵) + 戔 ''pared down'' (phonetic セン) — water shaved thin: shallow.', 'Blades planed the river down to ankle depth — あさい. 浅草: the ''shallow grass'' district, deep only in crowds.'),
  ('選', '選', '["elect","select","choose","prefer"]'::jsonb, '{"セン"}', '{"えら.ぶ","え.る","よ.る"}', 'N3', 4, 15, '9078', 'Phono-semantic: movement (辶) + 巽 (phonetic セン) — candidates presented and one sent forward: to select, elect.', 'The line walks past; you point at one — えらぶ. 選手 is the chosen athlete; 選挙 the national pointing.'),
  ('然', '然', '["sort of thing","so","if so","in that case","well"]'::jsonb, '{"ゼン","ネン"}', '{"しか","しか.り","しか.し","さ"}', 'N3', 4, 12, '7136', 'Originally ''to burn'' (meat + dog + fire — the root of 燃); borrowed since antiquity for ''thus, so, in that manner''.', 'The fire says: that''s just how it is — ゼン. 自然 is the world being so by itself; 全然 is ''not so at all''.'),
  ('争', '争', '["contend","dispute","argue"]'::jsonb, '{"ソウ"}', '{"あらそ.う","いか.でか"}', 'N3', 4, 6, '4e89', 'Compound ideograph: two hands wrenching one hooked object in opposite directions — to contend, dispute.', 'Both grips on the same handle, neither letting go — あらそう. 戦争 is this kanji armed; 競争 this kanji in sneakers.'),
  ('側', '側', '["side","lean","oppose","regret"]'::jsonb, '{"ソク"}', '{"かわ","がわ","そば"}', 'N3', 4, 11, '5074', 'Phono-semantic: person (亻) + 則 (phonetic ソク) — the person stationed beside: the side, the flank.', 'Always at your elbow, by the rules — がわ. 右側, 向こう側: pick your flank.'),
  ('束', '束', '["bundle","sheaf","ream","tie in bundles","govern","manage","control"]'::jsonb, '{"ソク"}', '{"たば","たば.ねる","つか","つか.ねる"}', 'N3', 4, 7, '675f', 'Pictograph: sticks cinched with a band around the middle — a bundle, a sheaf.', 'Firewood strapped tight through the waist — たば. 約束 ties two people the same way: a promise.'),
  ('続', '続', '["continue","series","sequel"]'::jsonb, '{"ゾク","ショク","コウ","キョウ"}', '{"つづ.く","つづ.ける","つぐ.ない"}', 'N3', 4, 13, '7d9a', 'Phono-semantic (simplified from 續): thread (糸) + a phonetic now written 売 — thread joined to thread without end: to continue.', 'Splice the new spool to the old before it runs out — つづく. Every cliffhanger ends with this kanji: 続く.'),
  ('卒', '卒', '["graduate","soldier","private","die"]'::jsonb, '{"ソツ","シュツ"}', '{"そっ.する","お.える","お.わる","ついに","にわか"}', 'N3', 4, 8, '5352', 'Originally the marked garment of conscript soldiers — the lowest rank; serving one''s full term gave ''to finish'': graduation.', 'Uniforms in rows, the term served out — ソツ. 卒業 is handing the uniform back with a diploma.'),
  ('孫', '孫', '["grandchild","descendants"]'::jsonb, '{"ソン"}', '{"まご"}', 'N3', 4, 10, '5b6b', 'Compound ideograph: child (子) + connecting thread (系) — the child one thread further down the line: grandchild.', 'Your child''s child, one more knot along the family rope — まご. The thread does the explaining.'),
  ('帯', '帯', '["sash","belt","obi","zone","region"]'::jsonb, '{"タイ"}', '{"お.びる","おび"}', 'N3', 4, 10, '5e2f', 'Pictograph: a sash with ornaments hanging over the skirt cloth — the belt; what a belt does: to carry on one; a belt of territory: zone.', 'The obi cinched, charms dangling — おび. 熱帯 is the planet''s hot waistband; 携帯 what you carry tucked in yours.'),
  ('達', '達', '["accomplished","reach","arrive","attain"]'::jsonb, '{"タツ","ダ"}', '{"-たち"}', 'N3', 4, 12, '9054', 'Phono-semantic: movement (辶) + 羍 (phonetic タツ — a lamb delivered without difficulty) — arriving without obstruction: to attain, reach.', 'Delivery without a single snag — タツ. 友達: the people your road reliably reaches; 配達: the parcel version.'),
  ('単', '単', '["simple","one","single","merely"]'::jsonb, '{"タン"}', '{"ひとえ"}', 'N3', 4, 9, '5358', 'Simplified from 單: a forked hunting weapon or shield — one piece of equipment, one man: single, simple.', 'One tool, no attachments — タン. 簡単 is the two-kanji hymn to it; 単語: words taken one at a time.'),
  ('置', '置', '["placement","put","set","deposit","leave behind","keep","employ","pawn"]'::jsonb, '{"チ"}', '{"お.く","-お.き"}', 'N3', 4, 13, '7f6e', 'Phono-semantic: net (罒) + 直 ''straight'' (phonetic チ) — the net set out straight and left: to place, to set down.', 'Lay it flat, square it, walk away — おく. 位置: where things got 置いた and stayed.'),
  ('仲', '仲', '["go-between","relationship"]'::jsonb, '{"チュウ"}', '{"なか"}', 'N3', 4, 6, '4ef2', 'Phono-semantic: person (亻) + 中 ''middle'' (phonetic チュウ) — the person in the middle of two others: go-between; the state between people: terms.', 'Standing exactly between two friends, keeping them friends — なか. 仲がいい: the middle is warm.'),
  ('兆', '兆', '["portent","10**12","trillion","sign","omen","symptoms"]'::jsonb, '{"チョウ"}', '{"きざ.す","きざ.し"}', 'N3', 4, 6, '5146', 'Pictograph: the cracks radiating across a heated tortoise shell — read by diviners as signs: portent; borrowed for the enormous number 10¹².', 'The shell splits into a map of the future — きざし. Big enough news to need the number: 一兆.'),
  ('底', '底', '["bottom","sole","depth","bottom price","base","kind","sort"]'::jsonb, '{"テイ"}', '{"そこ"}', 'N3', 4, 8, '5e95', 'Phono-semantic: building (广) + 氐 ''base'' (phonetic テイ) — the building''s lowest point: the bottom.', 'Below the floor, below the footing: the true floor — そこ. 海底: the one basement the planet has.'),
  ('的', '的', '["bull''s eye","mark","target","object","adjective ending"]'::jsonb, '{"テキ"}', '{"まと"}', 'N3', 4, 8, '7684', 'Phono-semantic: white (白) + 勺 (phonetic テキ) — the white disc of the target: bullseye; grammaticalized into the adjective-making suffix 〜的.', 'The white circle everything aims at — まと. Attach 〜的 and any noun starts aiming: 目的, 具体的.'),
  ('伝', '伝', '["transmit","go along","walk along","follow","report","communicate","legend","tradition"]'::jsonb, '{"デン","テン"}', '{"つた.わる","つた.える","つた.う","つだ.う","-づた.い","つて"}', 'N3', 4, 6, '4f1d', 'Simplified from 傳: person (亻) + a phonetic — the relay rider passing the message on: to transmit, hand down.', 'One person breathes it (云) to the next — つたえる. 手伝う: passing your hands along too.'),
  ('徒', '徒', '["on foot","junior","emptiness","vanity","futility","uselessness","ephemeral thing","gang","set","party","people"]'::jsonb, '{"ト"}', '{"いたずら","あだ"}', 'N3', 4, 10, '5f92', 'Compound: road (彳) + going (走) — traveling on foot; those who walk behind a master: followers, students.', 'No horse, no cart: the ones walking behind — ト. 生徒: students, still on foot behind the teacher.'),
  ('努', '努', '["toil","diligent","as much as possible"]'::jsonb, '{"ド"}', '{"つと.める"}', 'N3', 4, 7, '52aa', 'Phono-semantic: 奴 ''slave'' (phonetic ド) + strength (力) — working like one owned: to strive, exert.', 'Muscle spent as if you had no choice — つとめる. 努力: choosing that grind voluntarily.'),
  ('灯', '灯', '["lamp","a light","light","counter for lights"]'::jsonb, '{"トウ"}', '{"ひ","ほ-","ともしび","とも.す","あかり"}', 'N3', 4, 6, '706f', 'Phono-semantic (simplified from 燈): fire (火) + 丁 (phonetic トウ) — fire fixed on a stand: the lamp.', 'A flame nailed in place so it can''t wander — ひ, トウ. 電灯: the nail is now a socket.'),
  ('熱', '熱', '["heat","temperature","fever","mania","passion"]'::jsonb, '{"ネツ"}', '{"あつ.い"}', 'N3', 4, 15, '71b1', 'Phono-semantic: 埶 (phonetic ネツ) + fire (灬) — fire tended below: heat; the body''s own fire: fever.', 'Flames under everything you care about — あつい. 熱がある: the fire moved indoors; 熱心: the useful kind.'),
  ('念', '念', '["wish","sense","idea","thought","feeling","desire","attention"]'::jsonb, '{"ネン"}', '{}', 'N3', 4, 8, '5ff5', 'Phono-semantic: 今 ''now'' (phonetic ネン) + heart (心) — the heart holding this very moment: a fixed thought, a wish.', 'The heart pressing ''save'' on the present — ネン. 残念: the save that failed; 記念: the one that took.'),
  ('敗', '敗', '["failure","defeat","reversal"]'::jsonb, '{"ハイ"}', '{"やぶ.れる"}', 'N3', 4, 11, '6557', 'Phono-semantic: 貝 ''treasure'' (phonetic ハイ) + 攵 ''strike'' — the treasure smashed: ruin, defeat.', 'The stick comes down on the shell: what you built, broken — やぶれる. 失敗 pairs losing grip with the crack.'),
  ('飛', '飛', '["fly","skip (pages)","scatter"]'::jsonb, '{"ヒ"}', '{"と.ぶ","と.ばす","-と.ばす"}', 'N3', 4, 9, '98db', 'Pictograph: a bird climbing with both wings beating and neck stretched — to fly.', 'Mid-takeoff, feathers everywhere — とぶ. 飛行機 borrowed the wings; the kanji still owns them.'),
  ('必', '必', '["invariably","certain","inevitable"]'::jsonb, '{"ヒツ"}', '{"かなら.ず"}', 'N3', 4, 5, '5fc5', 'Originally the bound haft of a weapon — ''fixed firm''; the shape later read as a heart pinned by a stroke: invariably, without fail.', 'A heart with a stake through it cannot change its mind — かならず. 必要, 必死: needs and resolves at 100%.'),
  ('標', '標', '["signpost","seal","mark","stamp","imprint","symbol","emblem","trademark","evidence","souvenir","target"]'::jsonb, '{"ヒョウ"}', '{"しるべ","しるし"}', 'N3', 4, 15, '6a19', 'Phono-semantic: wood (木) + 票 (phonetic ヒョウ) — the marker at the treetop, visible far off: a sign, a mark.', 'The flag lashed to the tallest branch: aim here — ヒョウ. 目標: the branch your eyes keep returning to.'),
  ('付', '付', '["adhere","attach","refer to","append"]'::jsonb, '{"フ"}', '{"つ.ける","-つ.ける","-づ.ける","つ.け","つ.け-","-つ.け","-づ.け","-づけ","つ.く","-づ.く","つ.き","-つ.き","-つき","-づ.き","-づき"}', 'N3', 4, 5, '4ed8', 'Compound ideograph: a hand (寸) pressing something onto a person (亻) — to hand over, to attach.', 'Pressed into your palm until it sticks — つける. 受付 attaches visitors to the building; 気を付けて attaches care to you.'),
  ('夫', '夫', '["husband","man"]'::jsonb, '{"フ","フウ","ブ"}', '{"おっと","それ"}', 'N3', 4, 4, '592b', 'Pictograph: a grown man (大) with the pin of adulthood through his topknot (一) — a full-grown man: husband.', 'The pin through the hair says: adult, married, responsible — おっと. 大丈夫 stacks three sturdy kanji into ''it''s fine''.'),
  ('富', '富', '["wealth","enrich","abundant"]'::jsonb, '{"フ","フウ"}', '{"と.む","とみ"}', 'N3', 4, 12, '5bcc', 'Phono-semantic: roof (宀) + 畐 ''jar full to the brim'' (phonetic フ) — abundance under the roof: wealth.', 'The pantry jar that never empties — とみ. 富士山: the mountain named like a full house.'),
  ('府', '府', '["borough","urban prefecture","govt office","representative body","storehouse"]'::jsonb, '{"フ"}', '{}', 'N3', 4, 8, '5e9c', 'Phono-semantic: building (广) + 付 (phonetic フ) — the government repository where documents attach: the seat of administration; today Osaka-fu, Kyoto-fu.', 'The building all the paperwork sticks to — フ. 政府: the biggest flypaper of all.'),
  ('副', '副', '["vice-","assistant","aide","duplicate","copy"]'::jsonb, '{"フク"}', '{}', 'N3', 4, 11, '526f', 'Phono-semantic: 畐 ''full vessel'' (phonetic フク) + blade (刂) — the vessel split to make a matching second: duplicate, deputy: vice-.', 'Slice the jar''s contents into a twin copy — フク. 副社長: the copy that signs when the original is away.'),
  ('兵', '兵', '["soldier","private","troops","army","warfare","strategy","tactics"]'::jsonb, '{"ヘイ","ヒョウ"}', '{"つわもの"}', 'N3', 4, 7, '5175', 'Compound ideograph: an axe (斤) gripped in both hands — the armed man: soldier, troops.', 'Both fists on the axe-haft, ready — ヘイ. 兵士: the kanji is already at attention.'),
  ('変', '変', '["unusual","change","strange"]'::jsonb, '{"ヘン"}', '{"か.わる","か.わり","か.える"}', 'N3', 4, 9, '5909', 'Simplified from 變: tangled threads beaten (攵) into a new state — to change; what changed too far: strange.', 'Beat the knot until it becomes something else — かわる; if it comes out weird, that''s 変 too — へん.'),
  ('辺', '辺', '["environs","boundary","border","vicinity"]'::jsonb, '{"ヘン"}', '{"あた.り","ほと.り","-べ"}', 'N3', 4, 5, '8fba', 'Simplified from 邊: movement (辶) + a tall phonetic — where the road runs out: the edge, the vicinity.', 'Walk until the map frays — あたり, ベ. この辺: ''around here'', measured in strolls.'),
  ('包', '包', '["wrap","pack up","cover","conceal"]'::jsonb, '{"ホウ"}', '{"つつ.む","くる.む"}', 'N3', 4, 5, '5305', 'Pictograph: a body curled around a fetus (勹 around 巳) — the original wrapping: to wrap, envelop.', 'Curled protectively around what''s inside — つつむ. 包丁, oddly, is the kitchen knife: what unwraps dinner.'),
  ('法', '法', '["method","law","rule","principle","model","system"]'::jsonb, '{"ホウ","ハッ","ホッ","フラン"}', '{"のり"}', 'N3', 4, 8, '6cd5', 'Compound: water (氵) + 去 — law like water: it finds its level everywhere it goes; the leveled way of doing: method.', 'Water settles perfectly flat, no exceptions granted — ホウ. 方法 is the路 of doing; 法律 the water applied to people.'),
  ('望', '望', '["ambition","full moon","hope","desire","aspire to","expect"]'::jsonb, '{"ボウ","モウ"}', '{"のぞ.む","もち"}', 'N3', 4, 11, '671b', 'Compound: a figure standing tall, gazing at the moon (月) for what is absent (亡) — longing, hope; the moon gazed at fullest: full moon.', 'On tiptoe, eyes on the full moon, wanting — のぞむ. 希望: hope with its neck craned.'),
  ('末', '末', '["end","close","tip","powder","posterity"]'::jsonb, '{"マツ","バツ"}', '{"すえ","うら","うれ"}', 'N3', 4, 5, '672b', 'Ideograph: a tree (木) with a long stroke marking its topmost branch — the far end: the tip, the close. Mirror of 本, which marks the root.', 'The mark at the treetop: as far as it goes — すえ. 週末: the branch-tip of the week.'),
  ('満', '満', '["full","fullness","enough","satisfy"]'::jsonb, '{"マン","バン"}', '{"み.ちる","み.つ","み.たす"}', 'N3', 4, 12, '6e80', 'Phono-semantic: water (氵) + 㒼 (phonetic マン) — filled level to the rim: full, complete.', 'Poured to the brim without one drop over — みちる. 満員: a train filled by the same principle.'),
  ('未', '未', '["un-","not yet","hitherto","still","even now","sign of the ram","1-3PM","eighth sign of Chinese zodiac"]'::jsonb, '{"ミ","ビ"}', '{"いま.だ","ま.だ","ひつじ"}', 'N3', 4, 5, '672a', 'Ideograph: a tree (木) whose top branch is still short — growth unfinished: not yet. Twin of 末, where the branch has arrived.', 'The upper branch hasn''t caught up: unfinished — ミ. 未来: the not-yet, scheduled; 未満: not yet reaching the line.'),
  ('無', '無', '["nothingness","none","ain''t","nothing","nil","not"]'::jsonb, '{"ム","ブ"}', '{"な.い"}', 'N3', 4, 12, '7121', 'Pictograph of a dancer with tasseled sleeves, borrowed since the oracle bones for ''there is not'' — the dots below are the deformed legs, not fire.', 'The dance ends, the stage is bare — ない, ム. 無料 is ''nothing owed''; 無理 ''no way there''.'),
  ('約', '約', '["promise","approximately","shrink"]'::jsonb, '{"ヤク"}', '{"つづ.まる","つづ.める","つづま.やか"}', 'N3', 4, 9, '7d04', 'Phono-semantic: thread (糸) + 勺 (phonetic ヤク) — a cord knotted at the agreed measure: a promise; measured, not exact: approximately.', 'Tie the knot where you both agreed — ヤク. 約束 doubles the binding; 約3時間 keeps the knot loose.'),
  ('勇', '勇', '["courage","cheer up","be in high spirits","bravery","heroism"]'::jsonb, '{"ユウ"}', '{"いさ.む"}', 'N3', 4, 9, '52c7', 'Phono-semantic: 甬 (phonetic ユウ) + strength (力) — strength welling up and through: courage.', 'The strength that moves before fear finishes talking — いさむ. 勇気: the kanji that goes first.'),
  ('要', '要', '["need","main point","essence","pivot","key to"]'::jsonb, '{"ヨウ"}', '{"い.る","かなめ"}', 'N3', 4, 9, '8981', 'Pictograph: hands gripping a waist (the root of 腰) — the body''s pivot point: the essential; what the essential does: need.', 'Everything above and below turns on the waist — いる, ヨウ. 必要: pinned and pivotal at once.'),
  ('浴', '浴', '["bathe","be favored with","bask in"]'::jsonb, '{"ヨク"}', '{"あ.びる","あ.びせる"}', 'N3', 4, 10, '6d74', 'Phono-semantic: water (氵) + 谷 ''valley'' (phonetic ヨク) — stepping into the valley stream: to bathe, to bask.', 'The mountain pours a private shower into the ravine — あびる. 浴衣: what you wear walking back from it.'),
  ('利', '利', '["profit","advantage","benefit"]'::jsonb, '{"リ"}', '{"き.く"}', 'N3', 4, 7, '5229', 'Compound ideograph: grain (禾) + blade (刂) — the sickle slicing clean through the harvest: sharp; what the harvest yields: profit, advantage.', 'A sharp edge cuts more grain per swing — リ. 便利 is life with good edges; 利益 the grain they bring in.'),
  ('陸', '陸', '["land","six"]'::jsonb, '{"リク","ロク"}', '{"おか"}', 'N3', 4, 11, '9678', 'Phono-semantic: mound (阝) + 坴 (phonetic リク) — high dry ground: land, as opposed to sea.', 'Dirt piled on dirt until the sea gives up — リク. 大陸: the pile at continental scale; 陸上: sports on it.'),
  ('良', '良', '["good","pleasing","skilled"]'::jsonb, '{"リョウ"}', '{"よ.い","-よ.い","い.い","-い.い"}', 'N3', 4, 7, '826f', 'Pictograph: a sifting device separating fine grain from chaff — what passes the sieve: good.', 'Only the best grains make it through — よい. 良い is the sieve''s verdict; 奈良 wears it in its name.'),
  ('量', '量', '["quantity","measure","weight","amount","consider","estimate","surmise"]'::jsonb, '{"リョウ"}', '{"はか.る"}', 'N3', 4, 12, '91cf', 'Pictograph: a grain sack with a measuring opening at the top — to measure out: quantity.', 'The sack tells you how much by the mouthful — リョウ. 大量, measure overflowing; 測量, measuring gone professional.'),
  ('輪', '輪', '["wheel","ring","circle","link","loop","counter for wheels and flowers"]'::jsonb, '{"リン"}', '{"わ"}', 'N3', 4, 15, '8f2a', 'Phono-semantic: cart (車) + 侖 ''ordered arrangement'' (phonetic リン) — spokes set in perfect order: the wheel; any ring.', 'Spokes filed in a circle like books on a round shelf — わ. 指輪 for the finger, 五輪 for the Olympics.'),
  ('類', '類', '["sort","kind","variety","class","genus"]'::jsonb, '{"ルイ"}', '{"たぐ.い"}', 'N3', 4, 18, '985e', 'Phono-semantic: a phonetic built of rice and dog + head (頁) — things whose ''heads'' resemble each other, sorted into heaps: kind, sort.', 'Sort the pantry by lookalikes: this heap, that heap — ルイ. 種類: heaps with labels; 書類: heaps with staples.'),
  ('令', '令', '["orders","laws","command","decree","good"]'::jsonb, '{"レイ"}', '{}', 'N3', 4, 5, '4ee4', 'Compound ideograph: the assembly summoned (亼) and one kneeling (卩) to receive the word — a command, a decree.', 'The scroll read from the steps, everyone on one knee — レイ. 命令: orders with your name on them; 令和: an era named by one.'),
  ('例', '例', '["example","custom","usage","precedent"]'::jsonb, '{"レイ"}', '{"たと.える"}', 'N3', 4, 8, '4f8b', 'Phono-semantic: person (亻) + 列 ''row'' (phonetic レイ) — people lined up as precedents: an example, a custom.', 'Pull one person out of the line to show the rest — たとえば. 例えば: the kanji clearing its throat before a for-instance.'),
  ('冷', '冷', '["cool","cold (beer, person)","chill"]'::jsonb, '{"レイ"}', '{"つめ.たい","ひ.える","ひ.や","ひ.ややか","ひ.やす","ひ.やかす","さ.める","さ.ます"}', 'N3', 4, 7, '51b7', 'Phono-semantic: ice (冫) + 令 (phonetic レイ) — cold as a decree: chilled, cool (of things and of people).', 'Orders delivered over ice — つめたい. 冷蔵庫 keeps the beer 冷たい; some replies come out of the same drawer.'),
  ('連', '連', '["take along","lead","join","connect","party","gang","clique"]'::jsonb, '{"レン"}', '{"つら.なる","つら.ねる","つ.れる","-づ.れ"}', 'N3', 4, 10, '9023', 'Compound ideograph: carts (車) moving (辶) coupled in a train — linked one to the next: to connect, to take along.', 'Wagon hitched to wagon, all rolling together — つれる. 連絡 links people; 連休 links holidays.'),
  ('労', '労', '["labor","thank for","reward for","toil","trouble"]'::jsonb, '{"ロウ"}', '{"ろう.する","いたわ.る","いた.ずき","ねぎら","つか.れる","ねぎら.う"}', 'N3', 4, 7, '52b4', 'Simplified from 勞: fires blazing above strength (力) — strength burned through the night: labor, toil.', 'Working by torchlight until the fuel is you — ロウ. 苦労 is the invoice; ご苦労さま the receipt.'),
  ('老', '老', '["old man","old age","grow old"]'::jsonb, '{"ロウ"}', '{"お.いる","ふ.ける"}', 'N3', 4, 6, '8001', 'Pictograph: an elder with long hair bent over a cane — old age.', 'Hair grown past the shoulders, weight on the stick — おいる. 老人: the kanji leaning as it walks.'),
  ('録', '録', '["record"]'::jsonb, '{"ロク"}', '{"しる.す","と.る"}', 'N3', 4, 16, '9332', 'Phono-semantic: metal (金) + 彔 (phonetic ロク) — cut into bronze so it cannot be unsaid: to record.', 'Engraved, not jotted — ロク. 記録 outlives the writer; 録音 does it to sound.'),
